insert into private.study_guides (guide, chunks, sha256) values ('study_guide_acc121', 50, 'bde023f2200d4c9eda28e7a87b00ce8dd137c92f4e5a9c2b0101782df89359c9');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 1, $study_guide${"guide":"study_guide_acc121","code":"ACC121","courseId":"0412653e-c891-5f49-abd8-927ed986fb78","actor":"00000000-0000-4000-8000-000000000045","course":{"contentKey":"introduction-cost-accounting","titles":["Introduction to Cost Accounting"],"level":"100-level","semesters":["second-semester"]},"overview":{"itemId":"a7ce1bb4-06e5-5f46-9abf-3142e628c775","create":true,"after":{"title":"Introduction to Cost Accounting","body":"Every topic is examinable.","outcomes":["Explain the nature, objectives and scope of cost accounting and how it differs from financial accounting.","Classify costs by element, function and behaviour, and build up a cost sheet.","Separate semi-variable costs with the high-low method and estimate total cost from a cost function.","Control and price materials (FIFO, LIFO, average), set stock levels and calculate the economic order quantity.","Calculate wages under time, piece and bonus schemes, and treat overtime, shift premium and idle time correctly.","Allocate, apportion and absorb overheads, and work out under- or over-absorption.","Cost jobs and batches and prepare quotations.","Prepare marginal and absorption costing statements and reconcile their profits.","Use break-even analysis for planning and decisions.","Calculate direct material and labour variances and reconcile standard and actual cost.","Explain contemporary developments in cost accounting."],"assessment":["Questions may be multiple choice, short problems and long problems.","Many questions are calculations. Work through every worked example in Topics 3 to 10 until you can do them quickly."]}},"retire":[],"notes":[{"kind":"note","itemId":"8d7af188-69fa-5bea-a36d-a598072f9533","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Nature and Scope of Cost Accounting","body":"What cost, costing and cost accounting mean; the objectives of cost accounting; how it differs from financial accounting and relates to management accounting; the costing terms (cost object, cost unit, cost centre, profit, revenue and investment centres); the role of cost accounting in management; the purposes and qualities of cost information; and the scope of cost accounting.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What cost, costing and cost accounting mean; the objectives of cost accounting; how it differs from financial accounting and relates to management accounting; the costing terms (cost object, cost unit, cost centre, profit, revenue and investment centres); the role of cost accounting in management; the purposes and qualities of cost information; and the scope of cost accounting."}],"lessons":[{"number":"1.1","title":"Cost, costing and cost accounting","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost:","bold":true},{"text":" the amount of expenditure (actual or notional) incurred on, or attributable to, a specified thing or activity. To the producer, cost is what was spent to make a product or give a service; to the customer, the figure paid is the "},{"text":"price","bold":true},{"text":". Cost and price are not the same."}]},{"text":[{"text":"Basic formula:","bold":true},{"text":" Cost = Quantity × Price (rate) per unit. Example: 250 litres of diesel at ₦1,450 per litre cost 250 × ₦1,450 = ₦362,500."}]},{"text":[{"text":"Cost per unit","bold":true},{"text":" = Total cost ÷ Number of units produced (or service units given)."}]},{"text":[{"text":"Costing:","bold":true},{"text":" the techniques and processes of "},{"text":"ascertaining cost","bold":true},{"text":". \"The process of ascertaining cost\" = costing."}]},{"text":[{"text":"Cost accounting:","bold":true},{"text":" the wider process of "},{"text":"recording, classifying, accumulating, assigning (allocating), controlling and reporting","bold":true},{"text":" costs, and presenting suitably arranged information to management for control and guidance. It is a specialised branch of accounting."}]},{"text":[{"text":"Costing vs cost accounting:","bold":true},{"text":" they are "},{"text":"different","bold":true},{"text":". Costing is the technique of ascertaining costs; cost accounting is the wider system of recording, classifying and reporting costs that provides the basis for costing."}]},{"text":[{"text":"Cost accountancy:","bold":true},{"text":" the application of costing and cost accounting principles, methods and techniques to the science, art and practice of cost control and the ascertainment of profitability, including presenting information for managerial decision making. It is the widest of the three terms."}]},{"text":[{"text":"Cost audit:","bold":true},{"text":" the verification of cost accounts and a check that the costing plan is followed."}]}]},{"type":"paragraph","text":[{"text":"Objectives of cost accounting (learn the list):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ascertain the cost","bold":true},{"text":" of each product, job, process, service or department (cost per unit)."}]},{"text":[{"text":"Control costs:","bold":true},{"text":" keep actual costs within budgets and standards."}]},{"text":[{"text":"Reduce costs:","bold":true},{"text":" find real, lasting savings without lowering quality."}]},{"text":[{"text":"Help fix selling prices","bold":true},{"text":" and prepare quotations and tenders."}]},{"text":[{"text":"Value inventory","bold":true},{"text":" (stock) and measure profit for each period, product or department."}]},{"text":[{"text":"Reveal waste and inefficiency","bold":true},{"text":" in materials, labour time, expenses and machines."}]},{"text":[{"text":"Provide information for planning and decision making","bold":true},{"text":" (budgets, standards, make or buy, special orders, which products to push or drop)."}]},{"text":[{"text":"Present comparative cost data","bold":true},{"text":" for different periods and levels of output."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Not","bold":true},{"text":" objectives: helping shareholder$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 2, $study_guide$s decide whether to buy or sell the company's shares, computing tax, declaring dividends, drawing up the published balance sheet. Those belong to financial accounting and investors."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example: cost per unit at a Lagos bakery.","bold":true},{"text":" Mama Tolu Bakery, Surulere, bakes 20,000 loaves in March. Costs: flour 40 bags at ₦52,000; sugar 10 bags at ₦38,000; other ingredients ₦300,000; bakers' wages ₦900,000; diesel 600 litres at ₦1,100; rent ₦250,000."}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"Working"}],[{"text":"₦"}]],"rows":[[[{"text":"Flour"}],[{"text":"40 × 52,000"}],[{"text":"2,080,000"}]],[[{"text":"Sugar"}],[{"text":"10 × 38,000"}],[{"text":"380,000"}]],[[{"text":"Other ingredients"}],[{"text":"given"}],[{"text":"300,000"}]],[[{"text":"Wages"}],[{"text":"given"}],[{"text":"900,000"}]],[[{"text":"Diesel"}],[{"text":"600 × 1,100"}],[{"text":"660,000"}]],[[{"text":"Rent"}],[{"text":"given"}],[{"text":"250,000"}]],[[{"text":"Total cost","bold":true}],[],[{"text":"4,570,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Cost per loaf = ₦4,570,000 ÷ 20,000 = "},{"text":"₦228.50","bold":true},{"text":". Notice how each line uses Cost = Quantity × Price. If the bakery sells each loaf at ₦300, the ₦300 is the "},{"text":"price","bold":true},{"text":"; ₦228.50 is the "},{"text":"cost","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Cost is quantity multiplied by…\" Answer: "},{"text":"price (rate) per unit","bold":true},{"text":", not units sold, total revenue or profit per unit."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"What does cost accounting involve?\" Answer: "},{"text":"ascertainment of cost","bold":true},{"text":". Drawing up the balance sheet and preparing a statement of value added are financial-accounting tasks."}]},{"text":[{"text":"No single \"true\" cost.","bold":true},{"text":" Cost always depends on purpose and conditions. Much costing uses estimates (for example overheads are estimated in advance and shared over units), and different depreciation methods give different costs for the same product. Different costs for different purposes is a key idea in the nature of cost accounting."}]},{"text":[{"text":"Cost control vs cost reduction:","bold":true},{"text":" control keeps costs at the planned level (actual compared with budget or standard); reduction lowers the planned level itself, permanently, without hurting quality."}]},{"text":[{"text":"How it began:","bold":true},{"text":" cost accounting grew after the Industrial Revolution, when large factories needed to know the cost of each process to judge efficiency; later, cost-plus government contracts (price = cost + agreed profit) increased its importance."}]}]}]},{"number":"1.2","title":"Cost accounting, financial accounting and management accounting","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial accounting:","bold":true},{"text":" records transactions of the whole business and prepares the published financial statements (statement of profit or loss, statement of financial position) for "},{"text":"external","bold":true},{"text":" users: shareholders, investors, lenders, government, tax authorities."}]},{"text":[{"text":"Cost accounting:","bold":true},{"text":" provides detailed, "},{"text":"tailor-made","bold":true},{"text":" information to "},{"text":"management","bold":true},{"text":" (internal users)."}]},{"text":[{"text":"Management accounting:","bold":true},{"text":" the wider function of providing information to managers for planning, organising, directing, controlling and decision making. It uses cost-accounting data plus budgeting, financial analysis and forecasting. "},{"text":"Cost accounting is an integral part of management accounting.","bold":true}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Financial accounting"}],[{"text":"Cost accounting"}]],"rows":[[[{"text":"Main users"}],[{"text":"External (shareholders, lenders, government)"}],[{"text":"Internal (management)"}]],[[{"text":"Legal requirement"}],[{"text":"Compulsory for companies"}],[{"text":"Not compulsory; kept by choice"}]],[[{"text":"Rules"}],[{"text":"Must follow accounting standards (IFRS) and company law"}],[{"text":"No compulsory standards; format suits management"}]],[[{"text":"Coverage"}],[{"text":"The whole business as one"}],[{"text":"Products, jobs, processes, departments, cost centres"}]],[[{"text":"Period"}],[{"text":"Usually yearly (fixed periods)"}],[{"text":"As often as needed: daily, weekly, monthly"}]],[[{"text":"Data"}],[{"text":"Mainly historical, actual figures"}],[{"text":"Historical plus estimates, budgets and standards"}]],[[{"text":"Units"}],[{"text":"Money only"}],[{"text":"Money and physical units (kg, hours, litres)"}]],[[{"text":"Main purpose"}],[{"text":"True and fair view, stewardship"}],[{"text":"Ascertainment, control, pricing, decisions"}]],[[{"text":"Stock valuation"}],[{"text":"Cost or net realisable value, whichever is lower"}],[{"text":"Detailed cost of each item and stage"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Similarity:","bold":true},{"text":" both use the same basic transaction data, both are mostly expressed in money, and "},{"text":"the information of both is used for decision making","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Cost accounting"}],[{"text":"Management accounting"}]],"rows":[[[{"text":"Scope"}],[{"text":"Narrower: cost data"}],[{"text":"Wider: cost, financial and non-financial data"}]],[[{"text":"Focus"}],[{"text":"Ascertaining and controlling cost"}],[{"text":"Planning, control and all management decisions"}]],[[{"text":"Relationship"}],[{"text":"A part of management accounting"}],[{"text":"Includes cost accounting"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 3, $study_guide$true},{"text":" \"Financial and cost accounting are similar because…\" The answer is that "},{"text":"their information is used for decision making","bold":true},{"text":". \"Both required by law\" is false (cost accounting is not compulsory). \"Both subject to accounting standards\" is false. \"Both prepared for the whole business\" is false (cost accounting breaks the business into products and departments)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Cost accounting mainly provides information for … users.\" Answer: "},{"text":"internal","bold":true},{"text":". \"Cost accounting provides … information to …\": "},{"text":"tailor-made; management","bold":true},{"text":". Not \"generic\", and not \"investors\"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Cost accounting is an integral part of…\" Answer: "},{"text":"management accounting","bold":true},{"text":", not financial, forensic or treasury accounting."}]},{"text":[{"text":"Why financial accounting is not enough for managers:","bold":true},{"text":" a Kano flour mill's annual report shows one total profit. It does not tell the managing director which product (semolina, wheat flour, bran) makes money, what one bag costs, where waste is, or what price to quote a bakery chain. Cost accounting fills these gaps."}]},{"text":[{"text":"In Nigeria, ICAN (the Institute of Chartered Accountants of Nigeria) examines cost and management accounting as core professional subjects."}]}]}]},{"number":"1.3","title":"Costing terms: cost object, cost unit and responsibility centres","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost object:","bold":true},{"text":" anything for which a separate measurement of cost is wanted: a product, service, job, batch, department, customer, project or activity."}]},{"text":[{"text":"Cost unit:","bold":true},{"text":" a unit of "},{"text":"product, service or time","bold":true},{"text":" (or combination) in relation to which costs are ascertained or expressed. It answers \"cost per what?\""}]},{"text":[{"text":"Composite cost unit:","bold":true},{"text":" combines two measures, for example passenger-kilometre, tonne-kilometre, kilowatt-hour, patient-day, room-day."}]},{"text":[{"text":"Cost centre:","bold":true},{"text":" a production or service "},{"text":"location, function, activity or item of equipment","bold":true},{"text":" (it can also be a person) for which costs are accumulated, and whose costs may then be attributed to cost units. The manager is responsible for "},{"text":"costs only","bold":true},{"text":"."}]},{"text":[{"text":"Revenue centre:","bold":true},{"text":" the manager is responsible for "},{"text":"revenue (sales) only","bold":true},{"text":", e.g. a sales office."}]},{"text":[{"text":"Profit centre:","bold":true},{"text":" a part of the business for which "},{"text":"both costs and revenues","bold":true},{"text":" are ascertained; the manager is responsible for "},{"text":"generating revenue and controlling costs so as to earn profit","bold":true},{"text":"."}]},{"text":[{"text":"Investment centre:","bold":true},{"text":" a profit centre whose manager also controls the "},{"text":"capital invested","bold":true},{"text":"; judged on return on capital employed (ROCE)."}]},{"text":[{"text":"Responsibility centres","bold":true},{"text":" = cost centres, revenue centres, profit centres and investment centres (the classic exam grouping is "},{"text":"cost, profit and investment centres","bold":true},{"text":")."}]}]},{"type":"paragraph","text":[{"text":"Types of cost centre:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production cost centre:","bold":true},{"text":" where goods are actually made (mixing, baking, cutting, assembly)."}]},{"text":[{"text":"Service cost centre:","bold":true},{"text":" supports production but makes no product (stores, maintenance, canteen, quality control)."}]},{"text":[{"text":"Personal cost centre:","bold":true},{"text":" a person or group of persons (e.g. a sales representative)."}]},{"text":[{"text":"Impersonal cost centre:","bold":true},{"text":" a location or item of equipment (e.g. an oven, a machine)."}]}]},{"type":"paragraph","text":[{"text":"Common cost units:","bold":true}]},{"type":"table","header":[[{"text":"Business"}],[{"text":"Cost unit"}]],"rows":[[[{"text":"Bicycle or car manufacturer"}],[{"text":"Per bicycle / per car"}]],[[{"text":"Brick making"}],[{"text":"Per 1,000 bricks"}]],[[{"text":"Cement, steel, sugar, flour"}],[{"text":"Per tonne (or per bag)"}]],[[{"text":"Hotel"}],[{"text":"Room-day (room-night), guest-night"}]],[[{"text":"Electricity supply"}],[{"text":"Kilowatt-hour (kWh)"}]],[[{"text":"Bus or rail transport"}],[{"text":"Passenger-kilometre"}]],[[{"text":"Haulage (goods transport)"}],[{"text":"Tonne-kilometre"}]],[[{"text":"Hospital"}],[{"text":"Patient-day, bed-night"}]],[[{"text":"School"}],[{"text":"Per student"}]],[[{"text":"Printing, shoe factory"}],[{"text":"Per job, per batch, per pair"}]],[[{"text":"Oil and water"}],[{"text":"Per litre, per barrel"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Formula:","bold":true},{"text":" ROCE = Profit ÷ Capital employed × 100."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost unit vs cost centre (most-swapped pair):","bold":true},{"text":" a cost "},{"text":"unit","bold":true},{"text":" is the thing you cost (a loaf, a passenger-kilometre). A cost "},{"text":"centre","bold":true},{"text":" is where costs are collected (the baking section, an oven). \"A machine in the factory\" is a cost "},{"text":"centre","bold":true},{"text":", "},{"text":"not","bold":true},{"text":" a cost unit. A definition with \"location, person or item of equipment\" describes a cost centre; \"unit of product, service or time\" describes a cost unit."}]},{"text":[{"text":"Choose the natural output.","bold":true},{"text":" For a bicycle maker the cost unit is "},{"text":"per bicycle","bo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 4, $study_guide$ld":true},{"text":": \"per part of a bicycle\" is too small, \"per tonne\" and \"per day\" do not describe the product. Select units that are simple, clear and commonly used in that industry."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"A location, function or activity for which "},{"text":"cost and revenue","bold":true},{"text":" can be ascertained\" = "},{"text":"profit centre","bold":true},{"text":" (both cost and revenue). Costs only = cost centre. Revenue only = revenue centre. Return on capital = investment centre."}]}]},{"type":"paragraph","text":[{"text":"Worked example 1: passenger-kilometre.","bold":true},{"text":" An Ibadan transport company runs 3 coaches on the Lagos–Ibadan route (128 km). Each coach makes 20 trips a month with an average of 18 passengers. Monthly cost is ₦6,912,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Passenger-km = 3 × 20 × 18 × 128 = 138,240."}]},{"text":[{"text":"Cost per passenger-km = ₦6,912,000 ÷ 138,240 = "},{"text":"₦50","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2: room-night.","bold":true},{"text":" A 40-room hotel in Abuja is open 30 days with 75% occupancy. Monthly cost is ₦13,500,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Room-nights sold = 40 × 30 × 75% = 900."}]},{"text":[{"text":"Cost per room-night = ₦13,500,000 ÷ 900 = "},{"text":"₦15,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3: profit and investment centres.","bold":true},{"text":" The Kaduna branch of a Kano flour mill earns revenue of ₦48,000,000 and incurs costs of ₦39,000,000; capital invested in it is ₦60,000,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"As a profit centre: profit = ₦48,000,000 − ₦39,000,000 = "},{"text":"₦9,000,000","bold":true},{"text":"."}]},{"text":[{"text":"As an investment centre: ROCE = ₦9,000,000 ÷ ₦60,000,000 × 100 = "},{"text":"15%","bold":true},{"text":"."}]}]}]},{"number":"1.4","title":"Role of cost accounting in management, purposes, qualities and scope","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Role in management:","bold":true},{"text":" cost accounting is a valuable aid to management in "},{"text":"planning, control and decision making","bold":true},{"text":". It also helps organise (by dividing the business into cost centres), coordinate, and motivate (through budgets, standards and incentive schemes)."}]}]},{"type":"paragraph","text":[{"text":"Purposes of cost accounting information:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Inventory valuation and profit measurement:","bold":true},{"text":" cost of closing stock and work in progress; profit per product or period."}]},{"text":[{"text":"Pricing:","bold":true},{"text":" setting selling prices, quotations and tenders."}]},{"text":[{"text":"Planning:","bold":true},{"text":" preparing budgets and setting standard costs."}]},{"text":[{"text":"Control:","bold":true},{"text":" comparing actual results with budgets or standards and acting on variances."}]},{"text":[{"text":"Decision making:","bold":true},{"text":" make or buy, accept or reject a special order, drop or keep a product, choose between methods."}]},{"text":[{"text":"Performance evaluation:","bold":true},{"text":" judging managers, departments and cost centres."}]}]},{"type":"paragraph","text":[{"text":"Qualities of good cost accounting information:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Relevant","bold":true},{"text":" to the decision or user."}]},{"text":[{"text":"Accurate","bold":true},{"text":" (reliable), accurate enough for its purpose."}]},{"text":[{"text":"Timely:","bold":true},{"text":" available when needed."}]},{"text":[{"text":"Complete","bold":true},{"text":" (no vital item left out)."}]},{"text":[{"text":"Clear and understandable","bold":true},{"text":" to the manager using it."}]},{"text":[{"text":"Cost-effective:","bold":true},{"text":" the benefit is greater than the cost of producing it."}]},{"text":[{"text":"Communicated to the right person","bold":true},{"text":" (the one who can act on it)."}]},{"text":[{"text":"Comparable","bold":true},{"text":" over periods and between centres."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Not","bold":true},{"text":" a quality: \"tax consciousness\"."}]}]},{"type":"paragraph","text":[{"text":"Scope of cost accounting:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cost ascertainment:","bold":true},{"text":" collecting, classifying and analysing costs to find cost per unit, job or process (by post costing after the event or continuous costing as work goes on)."}]},{"text":[{"text":"Cost bookkeeping (recording):","bold":true},{"text":" keeping cost records and accounts."}]},{"text":[{"text":"Cost control:","bold":true},{"text":" standards and budgets, comparison, corrective action."}]},{"text":[{"text":"Cost reduction:","bold":true},{"text":" permanent savings."}]},{"text":[{"text":"Cost reporting (presentation):","bold":true},{"text":" regular reports to management; matching costs with revenue for each period."}]},{"text":[{"text":"Cost audit:","bold":true},{"text":" checking cost records."}]},{"text":[{"text":"Aiding decision making:","bold":true},{"text":" cost data for choosing between alternatives."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Cost accounting is a valuable aid to management in ___, ___ and ___.\" Answer: "},{"text":"planning, control and decision making","bold":true},{"text":". Auditing, taxation and dividends; advertising and packaging; recruitment and promotion are wrong sets."}]},{"text":[{"text":"Trap:","bold":true},{"text":" cost-effective information means its value exceeds its cost to produce. Spending ₦2,000,000 a year on a reporting system that saves ₦500,000 fails this tes$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 5, $study_guide$t."}]},{"text":[{"text":"Who else benefits:","bold":true},{"text":" managers most of all; also employees (steady jobs, fair incentive pay), lenders (better judgement of profitability) and the national economy (efficient firms, less waste, more government revenue)."}]},{"text":[{"text":"How an Aba shoe factory uses it:","bold":true},{"text":" it finds the cost of each pair (ascertainment), keeps leather waste within the standard (control), compares this month with last month (comparison), quotes a school for 2,000 pairs of sandals (pricing), and decides whether to buy soles or make them (decision making)."}]},{"text":[{"text":"Nature, in summary:","bold":true},{"text":" cost accounting is a specialised, internal, non-compulsory branch of accounting; it deals with both past and future (estimates, budgets, standards); it uses money and physical units; it gives different costs for different purposes; and it serves management."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost = expenditure (actual or notional) incurred on, or attributable to, a specified thing or activity; Cost = Quantity × Price per unit."}]},{"text":[{"text":"Costing = ascertaining cost; cost accounting = the wider recording, classifying and reporting of costs; they are different."}]},{"text":[{"text":"Objectives: ascertain cost, control and reduce cost, fix prices, value stock, reveal waste, inform decisions. Helping shareholders trade shares is not one."}]},{"text":[{"text":"Cost accounting: internal users, tailor-made information for management, not compulsory, no compulsory standards; similar to financial accounting because both inform decisions."}]},{"text":[{"text":"Cost accounting is an integral part of management accounting."}]},{"text":[{"text":"Cost unit = unit of product, service or time (bicycle, room-day, kWh, passenger-km); cost centre = location, function, person or equipment (a machine is a cost centre)."}]},{"text":[{"text":"Responsibility centres: cost (costs), revenue (revenue), profit (cost and revenue), investment (profit plus capital)."}]},{"text":[{"text":"Aid to management in planning, control and decision making; good information is relevant, accurate, timely, complete, clear and cost-effective."}]},{"text":[{"text":"Scope: ascertainment, recording, control, reduction, reporting, audit, decision support."}]}]}],"theory":{"itemId":"249f7ad9-c015-541d-b687-06b2f5ac8251","question":[{"type":"paragraph","text":[{"text":"An Aba shoe factory produced 2,500 pairs of shoes in June. It used 1,250 m² of leather at ₦4,800 per m² and 2,500 soles at ₦900 each; labour cost ₦3,000,000 and factory overheads ₦1,750,000. (a) State a suitable cost unit and one cost centre. (b) Calculate the cost per unit."}]}]}}},{"kind":"note","itemId":"76d6dd4a-d282-549e-b9ba-7183513fa0c5","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Cost Classification","body":"What cost classification is and why it is done; the bases of classification (element, function, behaviour, traceability, controllability, relevance, normality, product vs period); fixed, variable, semi-variable and stepped costs; costing methods vs costing techniques; the elements of cost and how to build a cost sheet from prime cost to total cost and profit.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"What cost classification is and why it is done; the bases of classification (element, function, behaviour, traceability, controllability, relevance, normality, product vs period); fixed, variable, semi-variable and stepped costs; costing methods vs costing techniques; the elements of cost and how to build a cost sheet from prime cost to total cost and profit."}],"lessons":[{"number":"2.1","title":"Nature and purpose of cost classification","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost classification:","bold":true},{"text":" the arrangement of cost items in logical groups having regard to their nature or purpose. Costs that share a feature (what they are, where they arise, how they behave) are grouped together."}]},{"text":[{"text":"Major objective:","bold":true},{"text":" to assist management in various decision areas (planning, control, pricing, stock valuation, decision making). Classification is not mainly for product diversification or choosing a production mix; those are only some of the decisions it supports."}]},{"text":[{"text":"Purposes of classification:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ascertaining the cost of products and services (cost sheets, stock values)."}]},{"text":[{"text":"Planning and budgeting (fixed and variable costs behave differently)."}]},{"text":[{"text":"Control and responsibility (who can influence which cost)."}]},{"text":[{"text":"Decision making (which costs are relevant to a choice)."}]},{"text":[{"text":"Fixing selling prices and preparing quotations."}]}]}]},{"text":[{"text":"Bases (methods) of classification:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Element (nature):","bold":true},{"text":" materials, labour, expenses."}]},{"text":[{"text":"Function:","bold":true},{"text":" production, administration, selling and distribution (also research and development)."}]},{"text":[{"text":"Behaviour (activity level):","bold":true},{"text":" fixed, variable, semi-variable, stepped."}]},{"text":[{"text":"Traceability:","bold":true},{"text":" direct, indirect."}]},{"text":[{"text":"Controllability:","bold":true},{"text":" controllable, uncontrollable."}]},{"text":[{"text":"Relevance (decision making):","bold":true},{"text":" relevant, irrelevant (sunk, committed), opportunity, notional, incremental."}]},{"text":[{"text":"Normality:","bold":true},{"text":" normal, abnormal."}]},{"text":[{"text":"Association with the product (inventory):","bold":true},{"text":" product cost, period cost."}]},{"text":[{"text":"Time:","bold":true},{"text":" historical, predeter$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 6, $study_guide$mined (estimated, standard)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exam trap: \"adaptability of cost\", \"colour of cost\" or \"size of cost\" are "},{"text":"not","bold":true},{"text":" bases. Behaviour, relevance and function "},{"text":"are","bold":true},{"text":"."}]},{"text":[{"text":"The same cost can sit in several groups at once. Flour in a Lagos bakery is a material (element), a production cost (function), a variable cost (behaviour), a direct cost (traceability) and a product cost (inventory)."}]}]}]},{"number":"2.2","title":"Elements of cost, direct vs indirect, and function","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Elements of cost:","bold":true},{"text":" materials, labour and expenses. Each element is either direct or indirect."}]},{"text":[{"text":"Direct cost:","bold":true},{"text":" can be traced to (identified with) a specific cost unit, e.g. leather in a shoe, wages of plasterers in a construction company."}]},{"text":[{"text":"Indirect cost (overhead):","bold":true},{"text":" cannot be traced to a single unit or it is uneconomic to do so; shared by many units, e.g. factory rent, the maintenance manager's salary."}]},{"text":[{"text":"Direct expenses","bold":true},{"text":" (also called "},{"text":"chargeable expenses","bold":true},{"text":"): expenses, other than materials and labour, incurred for a specific job or unit. Examples: royalty paid per unit produced, hire of special equipment for a particular order, special design or drawings for one job, subcontract work on one order."}]}]},{"type":"table","header":[[],[{"text":"Direct"}],[{"text":"Indirect (overhead)"}]],"rows":[[[{"text":"Materials"}],[{"text":"Wood in a table, leather in a shoe"}],[{"text":"Glue, oil, cleaning materials"}]],[[{"text":"Labour"}],[{"text":"Machine operators, plasterers, bakers"}],[{"text":"Supervisors, storekeepers, cleaners"}]],[[{"text":"Expenses"}],[{"text":"Royalty per unit, special tool hire"}],[{"text":"Rent, electricity, insurance, depreciation"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Prime cost","bold":true},{"text":" = Direct materials + Direct labour + Direct expenses. Prime cost is a "},{"text":"direct","bold":true},{"text":" cost (the total of all direct costs)."}]},{"text":[{"text":"Overhead","bold":true},{"text":" = Indirect materials + Indirect labour + Indirect expenses."}]},{"text":[{"text":"Classification by function:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production (factory, manufacturing) overhead:","bold":true},{"text":" the total of all indirect costs associated with manufacturing."}]},{"text":[{"text":"Administration overhead:","bold":true},{"text":" costs of formulating policy, directing and controlling the organisation (directors' and chief accountant's salaries, head-office rent)."}]},{"text":[{"text":"Selling and distribution overhead:","bold":true},{"text":" selling = creating and stimulating demand (advertising, salesmen); distribution = getting goods to customers (delivery vans, warehousing)."}]}]}]},{"text":[{"text":"Total cost","bold":true},{"text":" = Prime cost + all overheads (production, administration, selling and distribution)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Royalty "},{"text":"per unit produced","bold":true},{"text":" is a direct expense. Royalty based on "},{"text":"sales","bold":true},{"text":" is a selling overhead. Read the wording."}]},{"text":[{"text":"Director's salary, advertising and general electricity are "},{"text":"not","bold":true},{"text":" direct expenses: they cannot be traced to one unit."}]},{"text":[{"text":"In a construction company the plasterers work on the building itself, so their wages are direct labour. A chief accountant at John Holt Plc, a general manager at Zenith Bank and a maintenance manager at Dangote Plc are all indirect: none of them works on a specific unit."}]},{"text":[{"text":"Prime cost is sometimes defined as direct materials plus direct labour only. When a question lists direct expenses, include them in prime cost."}]}]}]},{"number":"2.3","title":"Classification by behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost behaviour:","bold":true},{"text":" the way total cost and cost per unit are affected by changes in the level of activity."}]},{"text":[{"text":"Relevant range:","bold":true},{"text":" the range of activity over which the assumed behaviour holds."}]}]},{"type":"table","header":[[{"text":"Cost"}],[{"text":"Total cost as output rises"}],[{"text":"Cost per unit as output rises"}],[{"text":"Examples"}]],"rows":[[[{"text":"Fixed","bold":true}],[{"text":"Stays the same (within the relevant range)"}],[{"text":"Falls"}],[{"text":"Factory rent, insurance, salaried manager, straight-line depreciation"}]],[[{"text":"Variable","bold":true}],[{"text":"Rises in direct proportion"}],[{"text":"Stays constant"}],[{"text":"Direct materials, piece-rate wages, royalty per unit"}]],[[{"text":"Semi-variable (mixed)","bold":true}],[{"text":"Rises, but not in proportion"}],[{"text":"Falls"}],[{"text":"Electricity, telephone, salesman's salary plus commission"}]],[[{"text":"Stepped (step-fixed)","bold":true}],[{"text":"Fixed over a range, then jumps"}],[{"text":"Falls within each step"}],[{"text":"Supervisors' salaries, extra rented warehouse"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Fixed cost:","bold":true},{"text":" a cost which stays the same in total for a period, even when output changes (within the relevant range). Incurred even when nothing is produced."}]},{"text":[{"text":"Variable cost:","bold":true},{"text":" a cost incurred only when production takes place, rising in total as output rises. Variable cost "},{"text":"per unit remains constant","bold":true},{"text":" as output changes."}]},{"text":[{"text":"Semi-variable cost:","bold":true},{"text":" partly f$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 7, $study_guide$ixed and partly variable. Example: a phone bill = fixed line rental + charge per call."}]},{"text":[{"text":"Stepped cost:","bold":true},{"text":" fixed up to a certain activity level, then rises by a fixed amount to a new level."}]},{"text":[{"text":"Total cost = Total fixed cost + (Variable cost per unit × Units)"}]},{"text":[{"text":"Fixed cost per unit = Total fixed cost ÷ Units"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classic swap: a variable cost is "},{"text":"fixed per unit","bold":true},{"text":" and variable in total; a fixed cost is "},{"text":"fixed in total","bold":true},{"text":" and variable per unit. Options such as \"variable cost remains fixed in total\" are wrong."}]},{"text":[{"text":"Factory rent is "},{"text":"fixed","bold":true},{"text":", not semi-variable. Electricity (standing charge + units used), telephone (rental + calls) and a salesman's salary (basic pay + commission) are semi-variable."}]},{"text":[{"text":"Worked example (unit cost at a new output).","bold":true},{"text":" A Lagos bakery's cost per loaf is ₦200 when it bakes 5,000 loaves a month; 60% of this unit cost is variable. Find the cost per loaf at 8,000 loaves."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Variable cost per loaf = 60% × ₦200 = ₦120 (does not change with output)."}]},{"text":[{"text":"Fixed cost per loaf at 5,000 = ₦200 − ₦120 = ₦80, so total fixed cost = ₦80 × 5,000 = ₦400,000."}]},{"text":[{"text":"At 8,000 loaves: fixed cost per loaf = ₦400,000 ÷ 8,000 = ₦50."}]},{"text":[{"text":"New cost per loaf = ₦120 + ₦50 = "},{"text":"₦170","bold":true},{"text":" (total cost ₦1,360,000)."}]},{"text":[{"text":"Trap: do not keep ₦200, and do not scale the whole ₦200. Only the fixed part is spread more thinly. If output "},{"text":"falls","bold":true},{"text":" to 4,000, fixed cost per loaf rises to ₦100 and unit cost becomes ₦220."}]}]}]},{"text":[{"text":"Stepped example.","bold":true},{"text":" A Kano flour mill needs one supervisor, paid ₦150,000 a month, for every 1,000 bags (or part of 1,000) per month. At 2,500 bags it needs 3 supervisors: ₦450,000. From 2,001 to 3,000 bags the cost is fixed at ₦450,000; at 3,001 bags it steps up to ₦600,000."}]},{"text":[{"text":"Separating a semi-variable cost into its fixed and variable parts (the high-low method) is taught in Topic 3."}]}]}]},{"number":"2.4","title":"Controllability, relevance, normality, product and period costs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Controllable cost:","bold":true},{"text":" can be influenced by the actions of a specified manager (budget holder)."}]},{"text":[{"text":"Uncontrollable cost:","bold":true},{"text":" "},{"text":"cannot","bold":true},{"text":" be influenced by the actions of a specified manager (it may be controllable at a higher level)."}]},{"text":[{"text":"Responsibility centres","bold":true},{"text":" (classification by responsibility):"}]}]},{"type":"table","header":[[{"text":"Centre"}],[{"text":"Manager is responsible for"}]],"rows":[[[{"text":"Cost centre"}],[{"text":"Costs only"}]],[[{"text":"Revenue centre"}],[{"text":"Revenues only"}]],[[{"text":"Profit centre"}],[{"text":"Costs "},{"text":"and","bold":true},{"text":" revenues (hence profit)"}]],[[{"text":"Investment centre"}],[{"text":"Costs, revenues and capital investment (return on investment)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Relevant cost:","bold":true},{"text":" the cost considered when taking a decision: a "},{"text":"future, incremental cash","bold":true},{"text":" cost that "},{"text":"differs","bold":true},{"text":" between the options."}]},{"text":[{"text":"Sunk cost:","bold":true},{"text":" a cost already incurred that "},{"text":"cannot","bold":true},{"text":" be altered by any future decision. Sunk costs are "},{"text":"not relevant","bold":true},{"text":" for decision making. Examples: book value of an existing asset, depreciation of machines already bought, cost of resources acquired in the past."}]},{"text":[{"text":"Opportunity cost:","bold":true},{"text":" the benefit given up by choosing one option instead of the next best alternative."}]},{"text":[{"text":"Notional (imputed) cost:","bold":true},{"text":" a cost used in cost accounts that involves no actual cash outflow, e.g. interest on the owner's own capital, rent on premises the owner already owns."}]},{"text":[{"text":"Incremental (differential) cost:","bold":true},{"text":" the difference in total cost between two options or two activity levels."}]},{"text":[{"text":"Avoidable cost:","bold":true},{"text":" can be saved if an activity stops. "},{"text":"Unavoidable cost:","bold":true},{"text":" will be incurred anyway."}]},{"text":[{"text":"Normal cost:","bold":true},{"text":" normally incurred at a given level of output under normal conditions; included in product cost."}]},{"text":[{"text":"Abnormal cost:","bold":true},{"text":" "},{"text":"not","bold":true},{"text":" normally incurred at a given level of output (e.g. strike, fire, flood); excluded from product cost and written off to profit and loss."}]},{"text":[{"text":"Product cost:","bold":true},{"text":" cost of making the goods (direct materials, direct labour, direct expenses, production overhead); included in stock value until the goods are sold."}]},{"text":[{"text":"Period cost:","bold":true},{"text":" charged against profit of the period in which it is incurred (administration, selling and distribution)."}]},{"text":[{"text":"Unexpired cost:","bold":true},{"text":" cost of resources acquired that are expected to contribute to "},{"text":"future","bold":true},{"text":" revenue (e.g. closing stock, an asset); shown as an asset. "},{"text":"Expired cost:","bold":true},{"text":" already used up in earning revenue; shown as an expense."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (relevance).","bold":true},{"text":" An Aba shoe facto$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 8, $study_guide$ry bought a machine three years ago for ₦2,000,000; its book value is ₦800,000. It is deciding whether to buy a new machine for ₦3,500,000. The ₦800,000 book value and past depreciation are "},{"text":"sunk","bold":true},{"text":": they cannot change whatever is chosen. The ₦3,500,000 for the "},{"text":"new","bold":true},{"text":" plant is a future cost that depends on the decision, so it is "},{"text":"relevant","bold":true},{"text":" and is "},{"text":"not","bold":true},{"text":" a sunk cost."}]},{"text":[{"text":"If the owner could rent the factory floor out for ₦100,000 a month instead of using it, that ₦100,000 is an opportunity cost of using it."}]},{"text":[{"text":"Sunk costs, committed costs and notional costs are typical irrelevant costs; do not mix up \"notional\" (no cash flow) with \"sunk\" (already paid)."}]},{"text":[{"text":"A product cost held in closing stock is an unexpired cost; once the goods are sold it becomes cost of sales, an expired cost."}]}]}]},{"number":"2.5","title":"Costing methods vs costing techniques","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Costing method:","bold":true},{"text":" the way costs are "},{"text":"collected and ascertained","bold":true},{"text":", chosen to suit the type of product or service."}]},{"text":[{"text":"Costing technique:","bold":true},{"text":" a way of "},{"text":"presenting and using","bold":true},{"text":" costs for control and decision making; it can be applied with any method."}]}]},{"type":"paragraph","text":[{"text":"Costing methods:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Job costing:","bold":true},{"text":" each job or order is costed separately (printing, car repairs, furniture repairs)."}]},{"text":[{"text":"Batch costing:","bold":true},{"text":" a batch of identical items is costed as one job, then cost per unit = batch cost ÷ units (bread, shoes, medicines)."}]},{"text":[{"text":"Contract costing:","bold":true},{"text":" large, long jobs at a site, often over a year (building a bridge, roads, shipbuilding)."}]},{"text":[{"text":"Process costing:","bold":true},{"text":" continuous production through stages; output of one process is input of the next (refineries, cement, soap, beverages)."}]},{"text":[{"text":"Unit (single or output) costing:","bold":true},{"text":" one uniform product made continuously; cost per unit = total cost ÷ units (brick making, coal mining, flour milling, quarrying)."}]},{"text":[{"text":"Operating (service) costing:","bold":true},{"text":" costing services rather than goods (hospitals, hotels, transport, electricity, canteen, a factory's boiler house)."}]},{"text":[{"text":"Multiple (composite) costing:","bold":true},{"text":" a combination of methods for complex assembled products (cars, motorcycles)."}]}]},{"type":"paragraph","text":[{"text":"Costing techniques:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Marginal costing"}]},{"text":[{"text":"Absorption costing"}]},{"text":[{"text":"Standard costing"}]},{"text":[{"text":"Historical costing"}]},{"text":[{"text":"Budgetary control"}]},{"text":[{"text":"Uniform costing"}]},{"text":[{"text":"Direct costing"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Biggest trap: "},{"text":"standard costing is a technique, not a method","bold":true},{"text":"; "},{"text":"job costing is a method, not a technique","bold":true},{"text":". \"Output costing\" is another name for unit costing, so it "},{"text":"is","bold":true},{"text":" a method."}]},{"text":[{"text":"Match industry to method: a private hospital in Lagos, steam from a boiler house, a bus company, a hotel = "},{"text":"operating (service)","bold":true},{"text":" costing. Brick making and coal mining = "},{"text":"unit (output)","bold":true},{"text":" costing. Building a bridge = "},{"text":"contract","bold":true},{"text":" costing. Printing and furniture repairs = "},{"text":"job","bold":true},{"text":" costing."}]}]}]},{"number":"2.6","title":"Elements of cost and the cost sheet build-up","mustKnow":[{"type":"paragraph","text":[{"text":"Cost sheet layout (memorise the order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Raw materials consumed = Opening stock + Purchases − Closing stock"}]},{"text":[{"text":"Prime cost","bold":true},{"text":" = Direct materials consumed + Direct labour + Direct expenses"}]},{"text":[{"text":"Add production (factory) overhead; add opening WIP, less closing WIP"}]},{"text":[{"text":"= "},{"text":"Factory (works) cost","bold":true},{"text":" (also called net works cost)"}]},{"text":[{"text":"Add administration overhead = "},{"text":"Cost of production","bold":true}]},{"text":[{"text":"Add opening stock of finished goods, less closing stock of finished goods = "},{"text":"Cost of goods sold","bold":true}]},{"text":[{"text":"Add selling and distribution overhead = "},{"text":"Total cost (cost of sales)","bold":true}]},{"text":[{"text":"Add profit = "},{"text":"Selling price","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Conversion cost:","bold":true},{"text":" the cost of converting raw materials into finished goods = Direct labour + Direct expenses + Production overhead (= Factory cost − Direct materials)."}]},{"text":[{"text":"Profit as a "},{"text":"margin","bold":true},{"text":" (percentage of selling price): Profit = Total cost × m ÷ (100 − m), where m is the percentage. Selling price = Total cost ÷ (1 − m/100)."}]},{"text":[{"text":"Profit as a "},{"text":"mark-up","bold":true},{"text":" (percentage of cost): Profit = Total cost × mark-up %."}]},{"text":[{"text":"Items of a purely financial nature are "},{"text":"left out","bold":true},{"text":" of the cost sheet: interest paid, dividends, income tax, donations, goodwill written off, profit or loss on sale of assets, cash discounts."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 9, $study_guide$:[{"text":"Worked example.","bold":true},{"text":" An Aba shoe factory made 4,000 pairs. Opening raw materials ₦40,000; purchases ₦300,000; closing raw materials ₦50,000; direct labour ₦180,000; royalty per pair ₦30,000 in total; factory overhead ₦120,000; opening WIP ₦25,000; closing WIP ₦45,000; administration overhead ₦80,000; opening finished goods ₦34,000; closing finished goods ₦51,000; selling and distribution overhead ₦57,000. Profit is 20% of selling price."}],"blocks":[{"type":"table","header":[[],[{"text":"₦"}]],"rows":[[[{"text":"Opening raw materials"}],[{"text":"40,000"}]],[[{"text":"Add purchases"}],[{"text":"300,000"}]],[[{"text":"Less closing raw materials"}],[{"text":"(50,000)"}]],[[{"text":"Direct materials consumed"}],[{"text":"290,000"}]],[[{"text":"Direct labour"}],[{"text":"180,000"}]],[[{"text":"Direct expenses (royalty)"}],[{"text":"30,000"}]],[[{"text":"Prime cost","bold":true}],[{"text":"500,000","bold":true}]],[[{"text":"Factory overhead"}],[{"text":"120,000"}]],[[{"text":"Add opening WIP"}],[{"text":"25,000"}]],[[{"text":"Less closing WIP"}],[{"text":"(45,000)"}]],[[{"text":"Factory cost","bold":true}],[{"text":"600,000","bold":true}]],[[{"text":"Administration overhead"}],[{"text":"80,000"}]],[[{"text":"Cost of production","bold":true},{"text":" (₦170 per pair)"}],[{"text":"680,000","bold":true}]],[[{"text":"Add opening finished goods"}],[{"text":"34,000"}]],[[{"text":"Less closing finished goods"}],[{"text":"(51,000)"}]],[[{"text":"Cost of goods sold","bold":true}],[{"text":"663,000","bold":true}]],[[{"text":"Selling and distribution overhead"}],[{"text":"57,000"}]],[[{"text":"Total cost (cost of sales)","bold":true}],[{"text":"720,000","bold":true}]],[[{"text":"Profit (20% of selling price)"}],[{"text":"180,000"}]],[[{"text":"Selling price","bold":true}],[{"text":"900,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost of production per pair = ₦680,000 ÷ 4,000 = ₦170."}]},{"text":[{"text":"Profit: selling price = ₦720,000 ÷ 0.80 = ₦900,000, so profit = ₦180,000 (that is ₦720,000 × 20 ÷ 80). A 25% mark-up on cost gives the same ₦180,000."}]},{"text":[{"text":"Conversion cost = ₦180,000 + ₦30,000 + ₦120,000 = ₦330,000."}]}]}]},{"text":[{"text":"Margin trap.","bold":true},{"text":" Total cost ₦10,000, profit 25% of selling price: profit = ₦10,000 × 25 ÷ 75 = ₦3,333.33, about "},{"text":"₦3,333","bold":true},{"text":" (selling price ₦13,333). ₦2,500 would be 25% of "},{"text":"cost","bold":true},{"text":", which is a mark-up, not a margin."}]},{"text":[{"text":"Purchased vs consumed trap.","bold":true},{"text":" Prime cost uses materials "},{"text":"consumed","bold":true},{"text":", never materials purchased. With materials purchased ₦100,000, consumed ₦90,000, direct labour ₦60,000, direct expenses ₦20,000 and manufacturing overhead ₦30,000, prime cost = ₦90,000 + ₦60,000 + ₦20,000 = "},{"text":"₦170,000","bold":true},{"text":" (overhead is not part of prime cost)."}]},{"text":[{"text":"\"Already adjusted\" trap.","bold":true},{"text":" If a question gives \"net works cost after adjusting for WIP\", do "},{"text":"not","bold":true},{"text":" adjust for WIP again. Example: net works cost ₦200,000; administration ₦100,000 gives cost of production ₦300,000; less closing finished goods ₦30,000 (no opening stock) gives cost of goods sold ₦270,000; add selling overhead ₦10,000 gives cost of sales "},{"text":"₦280,000","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost classification = arranging costs in logical groups by nature or purpose; its main aim is to help management in various decision areas."}]},{"text":[{"text":"Bases: element, function, behaviour, traceability, controllability, relevance, normality, product vs period, time."}]},{"text":[{"text":"Elements of cost = materials, labour, expenses; each direct or indirect. Direct expenses = chargeable expenses (royalty per unit, special equipment hire)."}]},{"text":[{"text":"Fixed: constant in total, falls per unit. Variable: constant per unit, rises in total. Semi-variable: electricity, telephone, salesman's pay. Stepped: jumps at set levels."}]},{"text":[{"text":"Sunk costs are past and irrelevant; relevant costs are future, incremental and differ between options; notional costs have no cash outflow."}]},{"text":[{"text":"Uncontrollable costs cannot be influenced by the specified manager; a profit centre manager answers for costs and revenues."}]},{"text":[{"text":"Methods (job, batch, contract, process, unit, operating, multiple) vs techniques (marginal, absorption, standard, historical, budgetary control, uniform)."}]},{"text":[{"text":"Cost sheet: prime cost, factory cost, cost of production, cost of goods sold, total cost, selling price. Conversion cost = direct labour + direct expenses + production overhead."}]}]}],"theory":{"itemId":"5fdb5b63-9f86-5c5e-ad3e-5577d9bdfd25","question":[{"type":"paragraph","text":[{"text":"Ikorodu Furniture Ltd gives you: direct materials consumed ₦250,000; direct labour ₦150,000; direct expenses ₦40,000; factory overhead ₦110,000; administration overhead ₦60,000. Calculate (a) prime cost, (b) conversion cost, (c) factory cost and (d) cost of production."}]}]}}},{"kind":"note","itemId":"ab6793e0-9f85-5d0f-b9b9-639252bd81b6","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Cost Estimation and the High-Low Method","body":"What cost estimation is; the cost function Y = a + bx; the five estimation methods with their advantages and disadvantages; the five high-low steps; high-low with inflation, stepped fixed costs and percentage activity levels; regression (least squares); limitations.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"What cost estimation is; the cost function Y = a + bx; the five estimation methods with their advantages and disadvantages; the five high-low steps; high-low with inflation, stepped fixed costs and percentage activity levels; regression (lea$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 10, $study_guide$st squares); limitations."}],"lessons":[{"number":"3.1","title":"Cost estimation and the cost function","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost estimation:","bold":true},{"text":" the measurement of historical cost with a view to helping in the prediction of future cost for management decision making. In short, historical information is analysed to provide estimates on which to base future expectations."}]},{"text":[{"text":"Semi-variable (mixed) cost:","bold":true},{"text":" a cost with a fixed part and a variable part, e.g. electricity (standing charge plus a rate per unit used), telephone, machine maintenance."}]},{"text":[{"text":"Cost separation:","bold":true},{"text":" breaking a mixed cost down into its variable and fixed elements. You must do this before you can estimate, because the two parts behave differently when activity changes."}]},{"text":[{"text":"The cost function:","bold":true},{"text":" Y = a + bx, where:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Y","bold":true},{"text":" = total cost (the dependent variable)"}]},{"text":[{"text":"a","bold":true},{"text":" = total fixed cost"}]},{"text":[{"text":"b","bold":true},{"text":" = variable cost per unit (of output, machine hour, square metre or whatever drives the cost)"}]},{"text":[{"text":"x","bold":true},{"text":" = number of units (level of activity)"}]}]}]},{"text":[{"text":"On a graph (cost on the Y axis, activity on the X axis): "},{"text":"a","bold":true},{"text":" is where the line cuts the cost axis (the intercept); "},{"text":"b","bold":true},{"text":" is the slope of the line."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Once you know a and b you can predict total cost at any activity level by putting the new x into Y = a + bx. Every computation in this topic ends this way."}]},{"text":[{"text":"Example: an Aba shoe factory finds its factory running cost is Y = ₦250,000 + ₦1,200x, where x is pairs made. For 900 pairs next month: Y = 250,000 + (1,200 × 900) = 250,000 + 1,080,000 = "},{"text":"₦1,330,000","bold":true},{"text":"."}]},{"text":[{"text":"Stepped fixed cost:","bold":true},{"text":" a fixed cost that stays flat over a range of activity, then jumps to a new level, e.g. hiring an extra supervisor once output passes a limit. In the cost function you simply add the jump to a when activity crosses the trigger point (see Lesson 3.4)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a is "},{"text":"total","bold":true},{"text":" fixed cost (not per unit); b is variable cost "},{"text":"per unit","bold":true},{"text":" (not total). Total variable cost = b × x."}]}]}]},{"number":"3.2","title":"The five cost estimation methods","mustKnow":[{"type":"paragraph","text":[{"text":"There are "},{"text":"five main methods","bold":true},{"text":" of predicting future figures from the analysis of past data:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The engineering method","bold":true},{"text":" (also called the "},{"text":"work measurement","bold":true},{"text":" method)"}]},{"text":[{"text":"The account analysis method","bold":true},{"text":" (accounting method)"}]},{"text":[{"text":"The scatter diagram approach","bold":true},{"text":" (scattergraph, visual fit)"}]},{"text":[{"text":"The high and low method","bold":true},{"text":" (high-low or "},{"text":"range","bold":true},{"text":" method)"}]},{"text":[{"text":"The regression analysis technique","bold":true},{"text":" (also called the "},{"text":"least squares","bold":true},{"text":" technique)"}]}]},{"type":"table","header":[[{"text":"Method"}],[{"text":"How it works"}],[{"text":"Main strength"}],[{"text":"Main weakness"}]],"rows":[[[{"text":"Engineering"}],[{"text":"Engineers estimate physical inputs (materials, labour hours, machine hours) per operation; prices and rates are then applied"}],[{"text":"Good for repetitive processes with a clear input-output relationship"}],[{"text":"Time consuming; hard with many products, joint costs or unknown mix"}]],[[{"text":"Account analysis"}],[{"text":"Ledger accounts are classified as fixed, variable or semi-variable from the accountant's experience"}],[{"text":"Fast, cheap, simple"}],[{"text":"Subjective, arbitrary separation"}]],[[{"text":"Scatter diagram"}],[{"text":"Plot total cost against activity for each period; fit a straight line by eye"}],[{"text":"Simple, convenient, uses all points"}],[{"text":"Line of best fit is subjective"}]],[[{"text":"High-low"}],[{"text":"Uses the highest and lowest activity points in Y = a + bx"}],[{"text":"Simple, objective, quick"}],[{"text":"Uses only two extreme points"}]],[[{"text":"Regression"}],[{"text":"Statistical line of best fit through all points by formula"}],[{"text":"Most accurate; gives confidence in goodness of fit"}],[{"text":"Needs more calculation"}]]]},{"type":"paragraph","text":[{"text":"Account analysis: advantages (3)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It is fast and inexpensive."}]},{"text":[{"text":"It is simple and easy to understand."}]},{"text":[{"text":"It is flexible, as it can be revised regularly."}]}]},{"type":"paragraph","text":[{"text":"Account analysis: disadvantages (4)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It relies on a single observation to determine the cost function."}]},{"text":[{"text":"It is based on past cost."}]},{"text":[{"text":"Separation of mixed cost is arbitrary."}]},{"text":[{"text":"The initial classification is subjective."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Engineering method in practice:","bold":true},{"text":" a Kano flour mill engineer works out that one 50kg bag of flour needs 52kg of wheat, 0.1 labour hours and 0.05 machine hours. The accountant then prices each: wheat at ₦900 per kg, labour at ₦2,000 per hour, machine time at ₦6,000 per hour. Cost per bag = (52 × 9$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 11, $study_guide$00) + (0.1 × 2,000) + (0.05 × 6,000) = 46,800 + 200 + 300 = "},{"text":"₦47,300","bold":true},{"text":". It looks forward from physical facts, not from past ledger figures."}]},{"text":[{"text":"Scatter diagram:","bold":true},{"text":" total cost on the Y axis, activity on the X axis, one dot per period. You draw the straight line that seems to pass closest to the dots. Where it cuts the cost axis is the fixed cost. Accuracy is doubtful because two people may draw different lines, and the data are past costs."}]},{"text":[{"text":"High-low","bold":true},{"text":" is described as an "},{"text":"objective","bold":true},{"text":" way of separating mixed costs; account analysis and the scatter diagram are "},{"text":"subjective","bold":true},{"text":"."}]},{"text":[{"text":"Exam trap:","bold":true},{"text":" options such as \"highest square method\" are invented. The real list is engineering, account analysis (accounting), scatter diagram, high-low (range), regression (least squares). Do not confuse \"least squares\" with \"highest square\". Break-even analysis, marginal costing and weighted average are "},{"text":"not","bold":true},{"text":" estimation methods either."}]}]}]},{"number":"3.3","title":"The high-low method step by step","mustKnow":[{"type":"paragraph","text":[{"text":"High-low method:","bold":true},{"text":" a technique which uses the highest and lowest activity levels to separate a mixed cost into its variable and fixed parts, using extreme data points in Y = a + bx."}]},{"type":"paragraph","text":[{"text":"The 5 steps","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Select the "},{"text":"highest","bold":true},{"text":" activity level and the "},{"text":"lowest","bold":true},{"text":" activity level."}]},{"text":[{"text":"Determine the cost associated with each. These costs may "},{"text":"not","bold":true},{"text":" necessarily be the highest and lowest costs."}]},{"text":[{"text":"Variable cost per unit: b = (Total cost at high activity − Total cost at low activity) ÷ (Units at high activity − Units at low activity)"}]},{"text":[{"text":"Fixed cost from the cost function: a = Y − bx (fixed cost = total cost − (activity level × variable cost per unit)), using either the high or the low point."}]},{"text":[{"text":"Predict future cost using Y = a + bx."}]}]},{"type":"paragraph","text":[{"text":"Advantages (3):","bold":true},{"text":" simple to operate; not subjective; quick and not expensive."}]},{"type":"paragraph","text":[{"text":"Disadvantages (2):","bold":true},{"text":" not fully representative, as it uses only the extreme values; gives an abnormal cost function when the extreme points are not typical."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example A (two points).","bold":true},{"text":" Bojuboju Limited's maintenance cost at its highest and lowest machine hours (7,400 and 5,000 hours) is ₦2,040 and ₦1,680."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"b = (2,040 − 1,680) ÷ (7,400 − 5,000) = 360 ÷ 2,400 = "},{"text":"₦0.15 per machine hour","bold":true}]},{"text":[{"text":"a = 2,040 − (0.15 × 7,400) = 2,040 − 1,110 = "},{"text":"₦930","bold":true}]},{"text":[{"text":"Check with the low point: 930 + (0.15 × 5,000) = 930 + 750 = ₦1,680. Correct."}]},{"text":[{"text":"Cost function: "},{"text":"MC = ₦930 + ₦0.15x","bold":true}]}]},{"type":"paragraph","text":[{"text":"Example B (predict).","bold":true},{"text":" Lonpe Plc: total cost ₦50,000 at 5,000 units and ₦70,000 at 10,000 units. Total cost at 15,000 units?"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"b = (70,000 − 50,000) ÷ (10,000 − 5,000) = 20,000 ÷ 5,000 = ₦4"}]},{"text":[{"text":"a = 70,000 − (4 × 10,000) = ₦30,000"}]},{"text":[{"text":"Y = 30,000 + (4 × 15,000) = "},{"text":"₦90,000","bold":true}]}]},{"type":"paragraph","text":[{"text":"Example C.","bold":true},{"text":" Product XYZ costs ₦240,000 for 5,000 units and ₦296,000 for 7,000 units. Budgeted cost of 9,500 units?"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"b = 56,000 ÷ 2,000 = ₦28; a = 296,000 − (28 × 7,000) = 296,000 − 196,000 = ₦100,000"}]},{"text":[{"text":"Y = 100,000 + (28 × 9,500) = 100,000 + 266,000 = "},{"text":"₦366,000","bold":true}]},{"text":[{"text":"Trap: ₦100,000 is only the fixed cost and ₦266,000 only the variable cost. The answer is the total."}]}]},{"type":"paragraph","text":[{"text":"Example D.","bold":true},{"text":" A department's total cost was ₦82,200 at 420 units and ₦90,275 at 515 units."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"b = 8,075 ÷ 95 = ₦85; a = 82,200 − (85 × 420) = 82,200 − 35,700 = ₦46,500"}]},{"text":[{"text":"Model: "},{"text":"TC = ₦46,500 + ₦85V","bold":true},{"text":". (₦8,075 is the cost difference, not the fixed cost.)"}]}]},{"type":"paragraph","text":[{"text":"Example E (pick by activity, not cost).","bold":true},{"text":" Six months' output and total cost: 7,000 units ₦250,000; 8,000 ₦230,000; 6,200 ₦194,000; 7,700 ₦222,000; 8,200 ₦229,000; 7,800 ₦212,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Highest "},{"text":"activity","bold":true},{"text":" is 8,200 units (₦229,000), not month 1 with the highest cost of ₦250,000. Lowest activity is 6,200 units (₦194,000)."}]},{"text":[{"text":"b = (229,000 − 194,000) ÷ (8,200 − 6,200) = 35,000 ÷ 2,000 = ₦17.50"}]},{"text":[{"text":"a = 229,000 − (17.50 × 8,200) = 229,000 − 143,500 = ₦85,500"}]},{"text":[{"text":"Y = ₦85,500 + ₦17.50x","bold":true}]}]},{"type":"paragraph","text":[{"text":"Example F.","bold":true},{"text":" DG's output and cost: 65,000 units ₦145,000; 80,000 ₦162,000; 90,000 ₦170,000; 60,000 ₦140,000; 75,000 ₦160,000. Expected cost at 85,000 units?"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"High 90,000 (₦170,000); low 60,000 (₦140,000). b = 30,000 ÷ 30,000 = ₦1"}]},{"text":[{"text":"a = 170,000 − 90,000 = ₦80,000. Y = 80,000 + 85,000 = "},{"text":"₦165,000","bold":true}]}]},{"type":"paragraph"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 12, $study_guide$,"text":[{"text":"Example G (power cost, machine hours).","bold":true},{"text":" Eight weeks: 8,000 hrs ₦3,600; 9,000 ₦3,950; 6,000 ₦3,050; 7,400 ₦3,380; 8,600 ₦3,870; 9,200 ₦4,020; 3,700 ₦2,095; 7,800 ₦3,530. Week 9 at 7,200 hours?"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"High 9,200 hrs (₦4,020); low 3,700 hrs (₦2,095)"}]},{"text":[{"text":"b = 1,925 ÷ 5,500 = ₦0.35 per machine hour; a = 4,020 − (0.35 × 9,200) = 4,020 − 3,220 = ₦800"}]},{"text":[{"text":"Y = 800 + (0.35 × 7,200) = 800 + 2,520 = "},{"text":"₦3,320","bold":true},{"text":" (₦2,520 alone forgets the fixed cost)"}]},{"text":[{"text":"The same pattern with costs a thousand times larger and four times the hours (high 36,800 hrs ₦4,020,000; low 14,800 hrs ₦2,095,000): b = 1,925,000 ÷ 22,000 = ₦87.50 per hour; a = 4,020,000 − 3,220,000 = ₦800,000; at 28,800 hours, Y = 800,000 + 2,520,000 = "},{"text":"₦3,320,000","bold":true},{"text":"."}]}]}]},{"number":"3.4","title":"High-low with inflation, stepped costs and percentage activity","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Inflation:","bold":true},{"text":" where inflation makes costs in each period impossible to compare, adjust all costs to the same price level using a price level index before applying high-low."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost at base prices = Actual cost × (Base index ÷ Index of that year)"}]},{"text":[{"text":"Future cost at future prices = Cost at base prices × (Future index ÷ Base index)"}]}]}]},{"text":[{"text":"Stepped fixed cost:","bold":true},{"text":" if a known fixed-cost increase is already inside one observed figure, "},{"text":"remove it first","bold":true},{"text":", apply high-low, then "},{"text":"add it back","bold":true},{"text":" only for activity levels above the trigger."}]},{"text":[{"text":"Percentage activity levels:","bold":true},{"text":" treat each percentage point as x; b = cost change per 1% of activity."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example H (inflation).","bold":true},{"text":" Risk Free Associates:"}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Output"}],[{"text":"Total cost ₦"}],[{"text":"Index"}],[{"text":"Cost at index 100 ₦"}]],"rows":[[[{"text":"2005"}],[{"text":"97,500"}],[{"text":"362,500"}],[{"text":"100"}],[{"text":"362,500 × 100/100 = 362,500"}]],[[{"text":"2006"}],[{"text":"120,000"}],[{"text":"448,000"}],[{"text":"112"}],[{"text":"448,000 × 100/112 = 400,000"}]],[[{"text":"2007"}],[{"text":"135,000"}],[{"text":"522,750"}],[{"text":"123"}],[{"text":"522,750 × 100/123 = 425,000"}]],[[{"text":"2008"}],[{"text":"90,000"}],[{"text":"504,000"}],[{"text":"144"}],[{"text":"504,000 × 100/144 = 350,000"}]],[[{"text":"2009"}],[{"text":"112,500"}],[{"text":"620,000"}],[{"text":"160"}],[{"text":"620,000 × 100/160 = 387,500"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"High 135,000 (₦425,000); low 90,000 (₦350,000). b = 75,000 ÷ 45,000 = ₦1.6667 per unit (exactly 5/3)"}]},{"text":[{"text":"a = 425,000 − (5/3 × 135,000) = 425,000 − 225,000 = ₦200,000 (at 2005 prices)"}]},{"text":[{"text":"2010 at 115,000 units: base-price cost = 200,000 + (5/3 × 115,000) = 200,000 + 191,666.67 = ₦391,666.67. At index 180: 391,666.67 × 180/100 = "},{"text":"₦705,000","bold":true}]},{"text":[{"text":"At 180,000 units: 200,000 + 300,000 = ₦500,000 × 1.8 = "},{"text":"₦900,000","bold":true}]},{"text":[{"text":"Comment: 115,000 units lies inside the observed range (90,000 to 135,000), so ₦705,000 is reasonably reliable. 180,000 units lies far outside it; this is extrapolation, and fixed costs may step up or the variable rate may change, so ₦900,000 is much less reliable."}]},{"text":[{"text":"Trap: ₦391,667 forgets to re-inflate to the 2010 index."}]}]},{"type":"paragraph","text":[{"text":"Example I (stepped fixed cost, step outside the data).","bold":true},{"text":" A cleaning firm in Lekki: overheads ₦73,950 at 12,750 m² and ₦83,585 at 15,100 m². Above 15,500 m² another supervisor is needed and fixed cost rises by ₦21,675. Estimate overheads at 16,000 m²."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Both observations are below 15,500, so neither contains the extra supervisor."}]},{"text":[{"text":"b = (83,585 − 73,950) ÷ (15,100 − 12,750) = 9,635 ÷ 2,350 = ₦4.10 per m²"}]},{"text":[{"text":"a = 83,585 − (4.10 × 15,100) = 83,585 − 61,910 = ₦21,675"}]},{"text":[{"text":"At 16,000 m²: 21,675 + 21,675 (step) + (4.10 × 16,000 = 65,600) = "},{"text":"₦108,950","bold":true}]},{"text":[{"text":"Trap: ₦87,275 forgets the extra supervisor."}]}]},{"type":"paragraph","text":[{"text":"Example J (step already inside one observation).","bold":true},{"text":" Total cost ₦125,250 at 6,500 units and ₦203,500 at 11,000 units. Above 9,500 units an extra ₦40,000 fixed cost is needed, and it is included in the 11,000-unit figure."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Remove the step: 203,500 − 40,000 = ₦163,500 at 11,000 units"}]},{"text":[{"text":"b = (163,500 − 125,250) ÷ (11,000 − 6,500) = 38,250 ÷ 4,500 = ₦8.50"}]},{"text":[{"text":"a = 125,250 − (8.50 × 6,500) = 125,250 − 55,250 = ₦70,000 (fixed cost up to 9,500 units)"}]},{"text":[{"text":"(i) 10,000 units: 70,000 + 40,000 + 85,000 = "},{"text":"₦195,000","bold":true}]},{"text":[{"text":"(ii) 8,500 units: 70,000 + 72,250 = "},{"text":"₦142,250","bold":true},{"text":" (below the trigger, no step)"}]},{"text":[{"text":"(iii) 12,000 units: 70,000 + 40,000 + 102,000 = "},{"text":"₦212,000","bold":true}]},{"text":[{"text":"Trap: using the raw figures gives b = ₦17.39 (rounded) and ₦186,111 at 10,000 units. That is wrong because the step distorts the slope."}]}]},{"type":"paragraph","text":[{"text":"Example K (percentage activity).","bold":true},{"text":" A manufacturer's flexible budget:"}]},{"type":"table","header":[[{"text":"Cost"}],[{"text":"60%"}],[{"text":"70%"}],[{"text":"80%"}]],"rows":[[[{"text":"Direct materials"}],[{"text":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 13, $study_guide$120,000"}],[{"text":"140,000"}],[{"text":"160,000"}]],[[{"text":"Direct labour"}],[{"text":"90,000"}],[{"text":"105,000"}],[{"text":"120,000"}]],[[{"text":"Production overheads"}],[{"text":"54,000"}],[{"text":"58,000"}],[{"text":"62,000"}]],[[{"text":"Other overheads"}],[{"text":"40,000"}],[{"text":"40,000"}],[{"text":"40,000"}]],[[{"text":"Total"}],[{"text":"304,000"}],[{"text":"343,000"}],[{"text":"382,000"}]]]},{"type":"paragraph","text":[{"text":"Estimate total cost at 77%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"b = (382,000 − 304,000) ÷ (80 − 60) = 78,000 ÷ 20 = ₦3,900 per 1%"}]},{"text":[{"text":"a = 382,000 − (3,900 × 80) = 382,000 − 312,000 = ₦70,000"}]},{"text":[{"text":"At 77%: 70,000 + (3,900 × 77) = 70,000 + 300,300 = "},{"text":"₦370,300","bold":true}]},{"text":[{"text":"Check by element: materials 2,000 × 77 = 154,000; labour 1,500 × 77 = 115,500; production overheads are semi-variable: 400 per 1% plus 30,000 fixed = 30,000 + 30,800 = 60,800; other overheads 40,000 (fixed). Total = ₦370,300. Correct."}]}]}]},{"number":"3.5","title":"Regression analysis and the limits of estimation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Regression analysis (least squares technique):","bold":true},{"text":" a statistical method of estimating cost using historical data from a number of previous periods, in the form Y = a + bx. It gets a line of best fit and tells the user the confidence level that can be put on the goodness of that line. It shows the nature of the relationship between a dependent variable (cost) and an independent variable (activity)."}]},{"text":[{"text":"Formulas (n = number of observations):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"b = (nΣxy − ΣxΣy) ÷ (nΣx² − (Σx)²)"}]},{"text":[{"text":"a = Σy ÷ n − b(Σx ÷ n)"}]}]}]},{"text":[{"text":"Limitations of cost estimation from past data:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Past costs may not reflect future conditions (new prices, technology, methods)."}]},{"text":[{"text":"Inflation distorts comparisons unless costs are indexed."}]},{"text":[{"text":"The straight-line (linear) assumption holds only within the relevant range of activity."}]},{"text":[{"text":"Fixed costs may step up outside the observed range, so extrapolation is risky."}]},{"text":[{"text":"One activity measure may not explain all of the cost."}]},{"text":[{"text":"Abnormal periods (strikes, breakdowns) distort the data, especially for high-low."}]}]}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example L.","bold":true},{"text":" A manufacturer's output and total cost: July 80 units ₦10,200; August 90 ₦10,900; September 100 ₦12,100; October 80 ₦10,800; November 120 ₦13,700; December 110 ₦12,500. Estimate the regression equation."}]},{"type":"table","header":[[{"text":"x"}],[{"text":"y"}],[{"text":"xy"}],[{"text":"x²"}]],"rows":[[[{"text":"80"}],[{"text":"10,200"}],[{"text":"816,000"}],[{"text":"6,400"}]],[[{"text":"90"}],[{"text":"10,900"}],[{"text":"981,000"}],[{"text":"8,100"}]],[[{"text":"100"}],[{"text":"12,100"}],[{"text":"1,210,000"}],[{"text":"10,000"}]],[[{"text":"80"}],[{"text":"10,800"}],[{"text":"864,000"}],[{"text":"6,400"}]],[[{"text":"120"}],[{"text":"13,700"}],[{"text":"1,644,000"}],[{"text":"14,400"}]],[[{"text":"110"}],[{"text":"12,500"}],[{"text":"1,375,000"}],[{"text":"12,100"}]],[[{"text":"Σx = 580"}],[{"text":"Σy = 70,200"}],[{"text":"Σxy = 6,890,000"}],[{"text":"Σx² = 57,400"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"b = (6 × 6,890,000 − 580 × 70,200) ÷ (6 × 57,400 − 580²) = (41,340,000 − 40,716,000) ÷ (344,400 − 336,400) = 624,000 ÷ 8,000 = "},{"text":"₦78","bold":true}]},{"text":[{"text":"a = 70,200 ÷ 6 − 78 × (580 ÷ 6) = 11,700 − 7,540 = "},{"text":"₦4,160","bold":true}]},{"text":[{"text":"Y = ₦4,160 + ₦78x","bold":true},{"text":". At 130 units: 4,160 + 10,140 = ₦14,300."}]},{"text":[{"text":"Here two months share the lowest output (80 units) at different costs, which shows why two extreme points can mislead; regression uses every month."}]},{"text":[{"text":"Choosing a method:","bold":true},{"text":" when a question says \"using any method you feel is suitable\", high-low is acceptable and fastest; regression gives the closest estimate. Always state the method you used."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost estimation analyses historical cost to predict future cost for decisions."}]},{"text":[{"text":"Mixed costs must be separated (cost separation) using Y = a + bx: a = total fixed cost, b = variable cost per unit, x = units, Y = total cost."}]},{"text":[{"text":"Five methods: engineering (work measurement), account analysis, scatter diagram, high-low (range), regression (least squares)."}]},{"text":[{"text":"Account analysis: 3 advantages (fast/cheap, simple, flexible), 4 disadvantages (single observation, past cost, arbitrary separation, subjective classification)."}]},{"text":[{"text":"High-low: pick highest and lowest "},{"text":"activity","bold":true},{"text":" (not cost); b = cost difference ÷ activity difference; a = Y − bx; then predict."}]},{"text":[{"text":"High-low advantages: simple, not subjective, quick and cheap. Disadvantages: uses only extremes; abnormal if extremes are untypical."}]},{"text":[{"text":"Inflation: deflate costs to one index, then re-inflate the forecast."}]},{"text":[{"text":"Stepped fixed costs: strip the step out before high-low, add it back above the trigger."}]},{"text":[{"text":"Regression: b = (nΣxy − ΣxΣy) ÷ (nΣx² − (Σx)²); a = Σy/n − bΣx/n."}]},{"text":[{"text":"Forecasts outside the observed range are extrapolations and less reliable."}]}]}],"theory":{"itemId":"29bc3936-4966-5f30-8f11-373037920532","question":[{"type":"paragraph","text":[{"text":"A Kano flour mill records electricity cost against machine hours: January 1,200 hours ₦96,000; February 1,500 hours ₦112,500; March 1,700 h$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 14, $study_guide$ours ₦129,000; April 1,800 hours ₦126,000. Using the high-low method, find the cost function and estimate the electricity cost for 1,600 machine hours."}]}]}}},{"kind":"note","itemId":"ce429907-3795-5ede-b654-b65b736972dc","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Materials Costing and Control","body":"What materials and inventory control are; the purchasing, receiving, inspection, storage and issue procedures and their documents; bin card vs stores ledger; perpetual inventory, continuous stocktaking and discrepancies; pricing issues by FIFO, LIFO and average methods and their effect on profit; maximum, minimum, re-order and average stock levels; the EOQ model and its costs.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What materials and inventory control are; the purchasing, receiving, inspection, storage and issue procedures and their documents; bin card vs stores ledger; perpetual inventory, continuous stocktaking and discrepancies; pricing issues by FIFO, LIFO and average methods and their effect on profit; maximum, minimum, re-order and average stock levels; the EOQ model and its costs."}],"lessons":[{"number":"4.1","title":"Materials, inventory control and purchasing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Materials:","bold":true},{"text":" all the tangible material assets of an organisation "},{"text":"other than its fixed assets","bold":true},{"text":": raw materials, components, consumable stores, work-in-progress and finished goods."}]},{"text":[{"text":"Inventory (stock) control:","bold":true},{"text":" the system used to control the investment in stock items, with the overall objective of "},{"text":"minimising the total associated costs","bold":true},{"text":" (purchase, ordering and holding costs) while avoiding stock-outs."}]},{"text":[{"text":"3 motives for holding stock:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Transaction:","bold":true},{"text":" to meet normal day-to-day production and sales needs."}]},{"text":[{"text":"Precautionary:","bold":true},{"text":" a buffer against unexpected demand or late deliveries."}]},{"text":[{"text":"Speculative:","bold":true},{"text":" holding stock to profit from an expected "},{"text":"increase in its price","bold":true},{"text":" in the future."}]}]}]},{"text":[{"text":"Purchasing procedure (in order):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Purchase requisition:","bold":true},{"text":" a "},{"text":"written request to initiate purchases","bold":true},{"text":", sent by the storekeeper or user department to the purchasing department."}]},{"text":[{"text":"Purchasing department finds sources of supply, compares quotations and selects a supplier."}]},{"text":[{"text":"Purchase order:","bold":true},{"text":" the formal order sent to the supplier, signed by the purchasing officer (in a tertiary institution, the "},{"text":"Procurement Director","bold":true},{"text":" issues purchase orders)."}]},{"text":[{"text":"Receiving:","bold":true},{"text":" goods arrive with the supplier's "},{"text":"delivery note","bold":true},{"text":" (waybill); the receiving section counts them."}]},{"text":[{"text":"Inspection:","bold":true},{"text":" quality and specification are checked; rejected items go back with a returns note."}]},{"text":[{"text":"Goods received note (GRN):","bold":true},{"text":" records the details of materials received from suppliers: date, supplier's name, purchase order number, description and quantity."}]},{"text":[{"text":"Accounts matches "},{"text":"purchase order, GRN and invoice","bold":true},{"text":" before paying the supplier."}]}]}]},{"text":[{"text":"Functions of the purchasing department:","bold":true},{"text":" receiving purchase requisitions; finding sources of supply; negotiating prices and terms; preparing and following up purchase orders; dealing with rejects and returns. "},{"text":"Accounting for materials received is NOT a purchasing function","bold":true},{"text":" (it belongs to the cost/stores accounts section)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: purchase "},{"text":"requisition","bold":true},{"text":" = internal request (stores to purchasing). Purchase "},{"text":"order","bold":true},{"text":" = external order (purchasing to supplier). An "},{"text":"invoice","bold":true},{"text":" is the supplier's bill; a "},{"text":"proforma invoice","bold":true},{"text":" is a quotation-style invoice sent before goods are supplied; a "},{"text":"waybill","bold":true},{"text":" travels with the goods; a "},{"text":"stores requisition note","bold":true},{"text":" draws goods out of stores, not in."}]},{"text":[{"text":"A Kano flour mill's storekeeper sees wheat falling to the re-order level, raises a purchase requisition; the purchasing manager sends a purchase order to a supplier in Funtua; the lorry arrives with a waybill; the quality lab inspects the grain; the receiving clerk prepares a GRN; accounts pays only when order, GRN and invoice agree."}]},{"text":[{"text":"ABC analysis","bold":true},{"text":" groups stock by value so control effort goes where the money is:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A items:","bold":true},{"text":" few in quantity (roughly 10% of items) but "},{"text":"high in value","bold":true},{"text":" (roughly 70% of value). Tightest control."}]},{"text":[{"text":"B items:","bold":true},{"text":" middle group (roughly 20% of items, 20% of value)."}]},{"text":[{"text":"C items:","bold":true},{"text":" many in quantity (roughly 70% of items) but low in value (roughly 10%). Simple control."}]}]}]}]}]},{"number":"4.2","title":"Storage, issue, stores records and discrepancies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Duties of the storekeeper:","bold":true},{"text":" "},{"text":"receiving","bold":true},{"text":", storing$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 15, $study_guide$ safely, "},{"text":"recording","bold":true},{"text":" (bin cards) and "},{"text":"issuing","bold":true},{"text":" stock; keeping stock within its levels; raising purchase requisitions. "},{"text":"Selling stock items is NOT a storekeeper's duty.","bold":true}]},{"text":[{"text":"Materials (stores) requisition note:","bold":true},{"text":" authorises the storekeeper to issue materials to a department or job. Also: "},{"text":"materials returned note","bold":true},{"text":" (unused materials back to stores) and "},{"text":"materials transfer note","bold":true},{"text":" (from one job to another)."}]},{"text":[{"text":"Bin card:","bold":true},{"text":" a "},{"text":"quantity-only","bold":true},{"text":" record of materials received, issued and in balance, kept by the storekeeper at the bin."}]},{"text":[{"text":"Stores ledger:","bold":true},{"text":" a record of "},{"text":"both quantity and value","bold":true},{"text":" of materials received, issued and in balance, kept by the cost/stores accounts office."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Bin card"}],[{"text":"Stores ledger"}]],"rows":[[[{"text":"Kept by"}],[{"text":"Storekeeper"}],[{"text":"Cost (stores) accountant"}]],[[{"text":"Kept where"}],[{"text":"In the store, at the bin"}],[{"text":"In the accounts office"}]],[[{"text":"Shows"}],[{"text":"Quantity only"}],[{"text":"Quantity and value"}]],[[{"text":"Posted"}],[{"text":"As each movement happens"}],[{"text":"From the documents, after the movement"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Perpetual inventory:","bold":true},{"text":" a system of recording stores balances "},{"text":"after every receipt and issue","bold":true},{"text":", so the balance of every item is always known from the records (bin cards and stores ledger)."}]},{"text":[{"text":"Continuous stocktaking:","bold":true},{"text":" "},{"text":"physically counting","bold":true},{"text":" a few items every day on a rota (and at random, without warning) so every item is checked several times a year. Perpetual inventory is the "},{"text":"records","bold":true},{"text":"; continuous stocktaking is the "},{"text":"physical check","bold":true},{"text":" of those records. (Periodic stocktaking counts everything once or twice a year, usually at year end.)"}]},{"text":[{"text":"Treatment of discrepancies","bold":true},{"text":" (physical count differs from records):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investigate the cause (clerical error, theft, evaporation, breakage, wrong issue)."}]},{"text":[{"text":"Correct clerical errors in the records."}]},{"text":[{"text":"Normal","bold":true},{"text":" (unavoidable) losses: written off to "},{"text":"production overhead","bold":true},{"text":", so they are absorbed into the cost of good output."}]},{"text":[{"text":"Abnormal","bold":true},{"text":" losses (beyond the normal level): "},{"text":"written off to the costing profit and loss account","bold":true},{"text":", never added to product cost."}]},{"text":[{"text":"Adjust the bin card and stores ledger to the physical count and tighten controls."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages of perpetual inventory with continuous stocktaking: errors and fraud found early; production is not stopped for an annual count; interim accounts can be prepared without a full count; stock is kept between its maximum and minimum levels; correct data for insurance claims; a moral check on stores staff."}]},{"text":[{"text":"Worked example: the bin card at a Lagos bakery shows 520 bags of sugar; the physical count finds 505. Shortage = 520 − 505 = 15 bags. At ₦2,000 a bag, value = 15 × ₦2,000 = ₦30,000. If normal loss is 5 bags (₦10,000), that goes to production overhead; the other 10 bags (₦20,000) are abnormal and go to the costing profit and loss account. Both records are reduced to 505."}]},{"text":[{"text":"Trap: abnormal wastage is "},{"text":"not","bold":true},{"text":" added to product cost and "},{"text":"not","bold":true},{"text":" shared; it is written off to the costing profit and loss account."}]}]}]},{"number":"4.3","title":"Pricing issues: FIFO, LIFO and average methods","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pricing issues:","bold":true},{"text":" deciding the cost charged to production for materials issued; the same choice fixes the value of closing stock."}]},{"text":[{"text":"FIFO (First In, First Out):","bold":true},{"text":" issues are priced at the prices of the "},{"text":"first (earliest) batches received","bold":true},{"text":" into the store. Closing stock is at the "},{"text":"latest","bold":true},{"text":" prices."}]},{"text":[{"text":"LIFO (Last In, First Out):","bold":true},{"text":" assumes stocks are issued in the "},{"text":"reverse order of receipt","bold":true},{"text":": issues are priced at the "},{"text":"latest","bold":true},{"text":" batches. Closing stock is at the "},{"text":"earliest","bold":true},{"text":" prices."}]},{"text":[{"text":"Simple average:","bold":true},{"text":" issue price = sum of the unit prices of the lots in stock ÷ number of lots (ignores quantities)."}]},{"text":[{"text":"Weighted average (perpetual):","bold":true},{"text":" after "},{"text":"each receipt","bold":true},{"text":", Average price = Total value in stock ÷ Total units in stock. Issues are priced at that average until the next receipt."}]},{"text":[{"text":"EOQ is NOT a pricing method","bold":true},{"text":"; it decides how much to order."}]},{"text":[{"text":"Check for any method:","bold":true},{"text":" Value of issues + Value of closing stock = Opening stock + Purchases."}]}]},{"type":"paragraph","text":[{"text":"Effect on profit","bold":true},{"text":" (cost of sales is lower when issues are cheaper, so profit is higher):"}]},{"type":"table","header":[[{"text":"Prices rising"}],[{"text":"Cost of issues"}],[{"text":"Closing stock"}],[{"text":"Profit"}]$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 16, $study_guide$],"rows":[[[{"text":"FIFO"}],[{"text":"Lowest"}],[{"text":"Highest","bold":true}],[{"text":"Highest","bold":true}]],[[{"text":"Weighted average"}],[{"text":"Middle"}],[{"text":"Middle"}],[{"text":"Middle"}]],[[{"text":"LIFO"}],[{"text":"Highest"}],[{"text":"Lowest","bold":true}],[{"text":"Lowest","bold":true}]]]},{"type":"paragraph","text":[{"text":"When prices are falling, the order reverses (FIFO gives the lowest profit). IAS 2 does not allow LIFO in published financial statements, but it is still used and examined for cost records."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (all three methods, perpetual).","bold":true},{"text":" An Aba shoe factory's leather record: Mar 1 received 1,000 units for ₦3,000 in total (unit price = ₦3,000 ÷ 1,000 = ₦3.00); Mar 8 received 3,000 units at ₦3.50; Mar 12 issued 2,500 units; Mar 20 issued 1,000 units."}]},{"type":"paragraph","text":[{"text":"Mar 1 and Mar 8 are the same under every method: Mar 1 balance ₦3,000; Mar 8 amount received = 3,000 × ₦3.50 = ₦10,500; balance = ₦3,000 + ₦10,500 = ₦13,500 (4,000 units)."}]},{"type":"paragraph","text":[{"text":"LIFO:","italic":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Mar 12 issue 2,500 from the latest lot: 2,500 × ₦3.50 = ₦8,750. Balance = ₦13,500 − ₦8,750 = ₦4,750 (500 at ₦3.50 + 1,000 at ₦3.00)."}]},{"text":[{"text":"Mar 20 issue 1,000: 500 × ₦3.50 = ₦1,750 plus 500 × ₦3.00 = ₦1,500; amount ₦3,250 (two prices used). Balance = 500 × ₦3.00 = ₦1,500."}]}]},{"type":"paragraph","text":[{"text":"FIFO:","italic":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Mar 12 issue 2,500: 1,000 × ₦3.00 = ₦3,000 plus 1,500 × ₦3.50 = ₦5,250; amount ₦8,250. Balance = 1,500 × ₦3.50 = ₦5,250."}]},{"text":[{"text":"Mar 20 issue 1,000 × ₦3.50 = ₦3,500. Balance = 500 × ₦3.50 = ₦1,750."}]}]},{"type":"paragraph","text":[{"text":"Weighted average:","italic":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"After Mar 8: ₦13,500 ÷ 4,000 = ₦3.375."}]},{"text":[{"text":"Mar 12 issue 2,500 × ₦3.375 = ₦8,437.50; balance 1,500 × ₦3.375 = ₦5,062.50."}]},{"text":[{"text":"Mar 20 issue 1,000 × ₦3.375 = ₦3,375; balance 500 × ₦3.375 = ₦1,687.50."}]}]},{"type":"table","header":[[],[{"text":"Total issues"}],[{"text":"Closing stock"}],[{"text":"Check"}]],"rows":[[[{"text":"FIFO"}],[{"text":"₦11,750"}],[{"text":"₦1,750"}],[{"text":"₦13,500"}]],[[{"text":"Weighted average"}],[{"text":"₦11,812.50"}],[{"text":"₦1,687.50"}],[{"text":"₦13,500"}]],[[{"text":"LIFO"}],[{"text":"₦12,000"}],[{"text":"₦1,500"}],[{"text":"₦13,500"}]]]},{"type":"paragraph","text":[{"text":"Prices rose (₦3.00 to ₦3.50), so FIFO has the highest closing stock and profit, LIFO the lowest."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (weighted average with rounding, receipt after issues).","bold":true},{"text":" A Kano flour mill: Jun 3 received 600 bags at ₦40 (₦24,000); Jun 10 received 800 bags at ₦46 (₦36,800); Jun 14 issued 500 bags; Jun 22 received 700 bags at ₦50 (₦35,000)."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"After Jun 10: 1,400 bags, ₦60,800. Average = ₦60,800 ÷ 1,400 = ₦43.428571..., rounded to 2 decimal places ₦43.43."}]},{"text":[{"text":"Jun 14 issue (using the rounded price, nearest naira): 500 × ₦43.43 = ₦21,715."}]},{"text":[{"text":"Balance 900 bags; carrying the average unrounded, value = 900 × ₦43.428571 = ₦39,085.71."}]},{"text":[{"text":"After Jun 22: 1,600 bags, ₦39,085.71 + ₦35,000 = ₦74,085.71. New average = ₦74,085.71 ÷ 1,600 = ₦46.30 (2 decimal places)."}]}]},{"type":"paragraph","text":[{"text":"Always follow the rounding the question states; it changes the last digits."}]},{"type":"paragraph","text":[{"text":"Worked example 3 (simple average).","bold":true},{"text":" If 600 bags at ₦40 and 800 at ₦46 are in stock, simple average price = (₦40 + ₦46) ÷ 2 = ₦43, even though there are more ₦46 bags. Weighted average gives ₦43.43."}]},{"type":"paragraph","text":[{"text":"Worked example 4 (FIFO for finished goods).","bold":true},{"text":" Opening stock 400 units valued at ₦1,800; 8,000 units produced at ₦48,000; closing stock 900 units. Under FIFO the oldest units are sold first, so closing stock comes from this period's production: unit cost = ₦48,000 ÷ 8,000 = ₦6; closing stock = 900 × ₦6 = ₦5,400."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Method for any long question: draw a stores ledger with columns Date | Receipts (qty, price, ₦) | Issues (qty, price, ₦) | Balance (qty, ₦). Under FIFO and LIFO, list the balance as separate lots so you can see which prices are left. If the business is new, there is no opening stock."}]}]}]},{"number":"4.4","title":"Stock control levels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Re-order level (ROL):","bold":true},{"text":" the stock level at which a new order is placed."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"ROL = Maximum consumption × Maximum re-order period (lead time)","bold":true}]},{"text":[{"text":"With a safety stock: "},{"text":"ROL = (Average usage × Lead time) + Safety stock","bold":true}]}]}]},{"text":[{"text":"Minimum stock level:","bold":true},{"text":" the level below which stock should not normally fall, to prevent running out; it is the allowance (buffer) that covers errors in forecasting the lead time or demand during the lead time."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Minimum level = ROL − (Average consumption × Average re-order period)","bold":true}]}]}]},{"text":[{"text":"Maximum stock level:","bold":true},{"text":" the level above which stock should not normally rise."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Maximum level = ROL + Re-order quantity − (Minimum consumption × Minimum re-order period)","bold":true}]}]}]},{"text":[{"text":"Average stock level = Minimum level + ½ Re-order quantity","bold":true},{"text":" (alternative: $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 17, $study_guide$(Maximum level + Minimum level) ÷ 2)."}]},{"text":[{"text":"Average re-order period = (Minimum lead time + Maximum lead time) ÷ 2.","bold":true},{"text":" Average consumption, if not given = (Minimum + Maximum consumption) ÷ 2."}]},{"text":[{"text":"Danger level = Average consumption × Maximum re-order period for emergency purchases","bold":true},{"text":"; at this level emergency buying starts."}]},{"text":[{"text":"Re-order quantity (ROQ):","bold":true},{"text":" the amount ordered each time, normally the "},{"text":"EOQ","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example (Lagos bakery, flour bags).","bold":true},{"text":" Usage: minimum 30, average 50, maximum 70 bags a day. Lead time 10 to 16 days. EOQ 600 bags."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"ROL = 70 × 16 = "},{"text":"1,120 bags","bold":true},{"text":"."}]},{"text":[{"text":"Average lead time = (10 + 16) ÷ 2 = 13 days. Minimum level = 1,120 − (50 × 13) = 1,120 − 650 = "},{"text":"470 bags","bold":true},{"text":"."}]},{"text":[{"text":"Maximum level = 1,120 + 600 − (30 × 10) = 1,720 − 300 = "},{"text":"1,420 bags","bold":true},{"text":"."}]},{"text":[{"text":"Re-order quantity = EOQ = "},{"text":"600 bags","bold":true},{"text":"."}]},{"text":[{"text":"Average stock = 470 + ½ × 600 = "},{"text":"770 bags","bold":true},{"text":" (the alternative formula gives (1,420 + 470) ÷ 2 = 945 bags; use the formula the question signals, and show it)."}]}]},{"type":"paragraph","text":[{"text":"Safety stock version:","bold":true},{"text":" usage 80 units a day, lead time 7 days, safety stock 200 units. ROL = (80 × 7) + 200 = 560 + 200 = "},{"text":"760 units","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Mixed units:","bold":true},{"text":" consumption 150 to 300 units per "},{"text":"week","bold":true},{"text":", delivery 21 to 35 "},{"text":"days","bold":true},{"text":". Convert days to weeks: 35 ÷ 7 = 5 weeks. ROL = 300 × 5 = "},{"text":"1,500 units","bold":true},{"text":". Always put usage and lead time in the same unit first."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: maximum consumption × maximum period is the "},{"text":"ROL","bold":true},{"text":", not the maximum level. The maximum level formula "},{"text":"adds","bold":true},{"text":" ROQ and "},{"text":"subtracts","bold":true},{"text":" minimum × minimum. The re-order quantity is the EOQ, not the ROL."}]}]}]},{"number":"4.5","title":"Economic order quantity (EOQ)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"EOQ (Economic Order Quantity):","bold":true},{"text":" the order size that "},{"text":"minimises the total of ordering and carrying (holding) costs","bold":true},{"text":". At the EOQ, annual ordering cost and annual carrying cost are "},{"text":"equal","bold":true},{"text":", and their total is at its "},{"text":"minimum","bold":true},{"text":"."}]},{"text":[{"text":"Ordering costs:","bold":true},{"text":" cost of placing and receiving an order: clerical and stationery costs, telephone, transport, inspection of goods received. They "},{"text":"fall","bold":true},{"text":" as order size rises (fewer orders)."}]},{"text":[{"text":"Carrying (holding) costs:","bold":true},{"text":" cost of keeping stock: warehousing/storage, insurance, interest on capital tied up, deterioration, obsolescence, theft. They "},{"text":"rise","bold":true},{"text":" as order size rises."}]},{"text":[{"text":"Symbols: D = annual demand (units); Co = cost per order; Cc (or Ch) = carrying cost per unit per year; Q = order quantity; P = purchase price per unit."}]},{"text":[{"text":"EOQ = √(2 × D × Co ÷ Cc)","bold":true}]},{"text":[{"text":"Annual ordering cost = D × Co ÷ Q","bold":true},{"text":" (number of orders D ÷ Q, times Co)."}]},{"text":[{"text":"Annual carrying cost = Q × Cc ÷ 2","bold":true},{"text":" (average stock Q ÷ 2, times Cc)."}]},{"text":[{"text":"Number of orders a year = D ÷ EOQ.","bold":true},{"text":" "},{"text":"Interval between orders = Days in the year ÷ Number of orders.","bold":true}]},{"text":[{"text":"Total annual cost = (D × P) + (D ÷ Q × Co) + (Q ÷ 2 × Cc).","bold":true}]},{"text":[{"text":"Rearranged for demand: D = EOQ² × Cc ÷ (2 × Co).","bold":true}]},{"text":[{"text":"Assumptions:","bold":true},{"text":" demand and lead time known and constant; Co and Cc constant; price constant (no discounts); no stock-outs; whole order delivered at once."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (carrying cost as a %).","bold":true},{"text":" A paint dealer in Ikorodu sells 24,000 tins a year. Cost per order ₦300; price ₦400 a tin; carrying cost 10% of price a year."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cc = 10% × ₦400 = ₦40 per tin per year."}]},{"text":[{"text":"EOQ = √(2 × 24,000 × 300 ÷ 40) = √360,000 = "},{"text":"600 tins","bold":true},{"text":"."}]},{"text":[{"text":"Orders a year = 24,000 ÷ 600 = "},{"text":"40","bold":true},{"text":"."}]},{"text":[{"text":"With 360 working days: interval = 360 ÷ 40 = "},{"text":"every 9 days","bold":true},{"text":"."}]},{"text":[{"text":"Ordering cost = 40 × ₦300 = ₦12,000; carrying cost = 600 ÷ 2 × ₦40 = ₦12,000 (equal, as expected). Total ordering and carrying cost = "},{"text":"₦24,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Convert demand to a year first.","bold":true},{"text":" Demand given per month: × 12 (1,500 a month = 18,000 a year). Per quarter: × 4. Per six months: × 2. Carrying cost must be "},{"text":"per unit per year","bold":true},{"text":". Round EOQ to whole units (state \"approximately\")."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (finding demand).","bold":true},{"text":" EOQ is 400 units, Co = ₦50, Cc = ₦5. D = 400² × 5 ÷ (2 × 50) = 160,000 × 5 ÷ 100 = "},{"text":"8,000 units","bold":true},{"text":"; orders = 8,000 ÷ 400 = 20."}]},{"type":"paragraph","text":[{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 18, $study_guide$"Worked example 3 (bulk discount).","bold":true},{"text":" A Kano mill uses 12,000 units a year at ₦20; Co = ₦40; Cc = ₦6 per unit per year (constant). The supplier offers a 2% discount for orders of 2,000 units."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"EOQ = √(2 × 12,000 × 40 ÷ 6) = √160,000 = 400 units."}]},{"text":[{"text":"At EOQ: purchases 12,000 × ₦20 = ₦240,000; ordering (12,000 ÷ 400) × ₦40 = 30 × ₦40 = ₦1,200; carrying 400 ÷ 2 × ₦6 = ₦1,200. Total "},{"text":"₦242,400","bold":true},{"text":"."}]},{"text":[{"text":"At 2,000 units: price ₦20 × 98% = ₦19.60; purchases 12,000 × ₦19.60 = ₦235,200; ordering 6 × ₦40 = ₦240; carrying 2,000 ÷ 2 × ₦6 = ₦6,000. Total "},{"text":"₦241,440","bold":true},{"text":"."}]},{"text":[{"text":"Difference = ₦242,400 − ₦241,440 = ₦960, so the discount is cheaper here. Always compare "},{"text":"total","bold":true},{"text":" cost including purchases; EOQ alone ignores discounts, so it does not always give the lowest total cost. Buying the whole year in one order means average stock = D ÷ 2 and one order cost."}]},{"text":[{"text":"Traps: the EOQ formula has "},{"text":"2","bold":true},{"text":" in the numerator and "},{"text":"Cc","bold":true},{"text":" in the denominator; D × Co ÷ Q is ordering cost, Q × Cc ÷ 2 is carrying cost. Warehousing cost is a "},{"text":"carrying","bold":true},{"text":" cost, not an ordering cost."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Materials = tangible assets other than fixed assets; inventory control minimises total stock costs."}]},{"text":[{"text":"Motives: transaction, precautionary, speculative (price rise)."}]},{"text":[{"text":"Purchase requisition (internal) → purchase order (to supplier) → receiving and inspection → GRN → pay on order, GRN and invoice agreeing."}]},{"text":[{"text":"Bin card = quantity only (storekeeper); stores ledger = quantity and value (accounts)."}]},{"text":[{"text":"Perpetual inventory = records after every movement; continuous stocktaking = daily physical checks. Abnormal losses go to costing profit and loss."}]},{"text":[{"text":"FIFO prices issues at earliest prices; LIFO at latest; weighted average recalculated after each receipt. Rising prices: FIFO highest stock and profit, LIFO lowest."}]},{"text":[{"text":"ROL = Max usage × Max lead time (or average usage × lead time + safety stock)."}]},{"text":[{"text":"Min = ROL − Avg usage × Avg lead time; Max = ROL + ROQ − Min usage × Min lead time; Average stock = Min + ½ ROQ."}]},{"text":[{"text":"EOQ = √(2DCo ÷ Cc); ordering cost = DCo ÷ Q; carrying cost = QCc ÷ 2; equal at EOQ."}]}]}],"theory":{"itemId":"91479601-eefd-5aaa-a523-837cc3e8ad66","question":[{"type":"paragraph","text":[{"text":"A Lagos printing firm uses 8,000 reams of paper a year, bought at ₦500 a ream. Each order costs ₦250 and carrying cost is 20% of the purchase price a year. Calculate (a) the EOQ, (b) the number of orders a year and (c) the total annual ordering and carrying cost at the EOQ."}]}]}}},{"kind":"note","itemId":"97455a51-8de5-57b3-b649-33a271af4c3f","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Labour Costing","body":"Time and output records (clock cards, job cards, time sheets) and the standard hour; time rate, piece rate, guaranteed and differential piece rates and their effect on unit cost; premium bonus schemes (Halsey, Halsey-Weir, Rowan) and time saved; gross pay, payroll preparation, wages analysis and ghost workers; treatment of overtime premium, shift premium and idle time; labour turnover, its causes, costs and the three measurement methods.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"Time and output records (clock cards, job cards, time sheets) and the standard hour; time rate, piece rate, guaranteed and differential piece rates and their effect on unit cost; premium bonus schemes (Halsey, Halsey-Weir, Rowan) and time saved; gross pay, payroll preparation, wages analysis and ghost workers; treatment of overtime premium, shift premium and idle time; labour turnover, its causes, costs and the three measurement methods."}],"lessons":[{"number":"5.1","title":"Labour cost and time and output records","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct labour","bold":true},{"text":" works on the product itself (an Aba shoe factory's stitchers); "},{"text":"indirect labour","bold":true},{"text":" supports production (storekeepers, supervisors) and is an overhead."}]},{"text":[{"text":"Time-keeping","bold":true},{"text":" records "},{"text":"attendance","bold":true},{"text":" (for payroll); "},{"text":"time-booking","bold":true},{"text":" records how that time is "},{"text":"spent","bold":true},{"text":" on jobs (for costing)."}]},{"text":[{"text":"Main records:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Clock card (attendance card):","bold":true},{"text":" stamped by a time-recording clock when the worker arrives and leaves; gives total hours "},{"text":"attended","bold":true},{"text":", the basis for time-rate pay."}]},{"text":[{"text":"Time sheet (daily or weekly):","bold":true},{"text":" the worker's own record of time spent on various jobs."}]},{"text":[{"text":"Job card:","bold":true},{"text":" records the labour time spent on "},{"text":"one job","bold":true},{"text":"; it is then "},{"text":"costed and posted to the job cost sheet","bold":true},{"text":"."}]},{"text":[{"text":"Piece-work ticket (operation card):","bold":true},{"text":" records the "},{"text":"output","bold":true},{"text":" of a piece-rate worker, used to calculate piece-rate pay."}]}]}]},{"text":[{"text":"Standard hour:","bold":true},{"text":" a hypothetical hour representing the "},{"text":"amount of work that should be performed in one hour","bold":true},{"text":" under stated conditions. Output is often measured in standard hours."}]},{"text":[{"text":"Time saved = Time allowed (standard time) − Time taken.","bold":true}]}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 19, $study_guide$,{"text":[{"text":"Idle time = clock-card hours − hours booked to jobs.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The clock card shows how long a worker was "},{"text":"present","bold":true},{"text":"; the job card shows where that time "},{"text":"went","bold":true},{"text":". Bin cards, stores requisitions and goods received notes are materials documents, not labour records."}]},{"text":[{"text":"Standard hour example:","bold":true},{"text":" at 20 units per standard hour, 300 units = 300 ÷ 20 = "},{"text":"15 standard hours","bold":true},{"text":"."}]},{"text":[{"text":"Time saved example:","bold":true},{"text":" standard time 0.75 hour per unit; a labourer works 30 hours and makes 60 units. Time allowed = 60 × 0.75 = 45 hours. Time saved = 45 − 30 = "},{"text":"15 hours","bold":true},{"text":"."}]}]}]},{"number":"5.2","title":"Time rate, piece rate and differential piece rates","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"2 major categories of remuneration:","bold":true},{"text":" "},{"text":"time-based","bold":true},{"text":" systems and "},{"text":"output-based (piece-rate)","bold":true},{"text":" systems. Premium bonus schemes combine the two."}]},{"text":[{"text":"Time rate (day rate):","bold":true},{"text":" pay = "},{"text":"Hours worked × Rate per hour","bold":true},{"text":", whatever the output."}]},{"text":[{"text":"Straight piece rate:","bold":true},{"text":" pay = "},{"text":"Units produced × Rate per unit","bold":true},{"text":"."}]},{"text":[{"text":"Piece rate per unit = Hourly rate ÷ Standard output per hour.","bold":true}]},{"text":[{"text":"Standard output per hour = 60 minutes ÷ Standard minutes per unit.","bold":true}]},{"text":[{"text":"Piece rate with guaranteed day rate (guaranteed minimum):","bold":true},{"text":" the worker receives the "},{"text":"higher","bold":true},{"text":" of time-rate pay and piece-rate earnings."}]},{"text":[{"text":"Taylor's differential piece rate:","bold":true},{"text":" no minimum guarantee; "},{"text":"low rate = 83% of the normal piece rate","bold":true},{"text":" for output "},{"text":"below","bold":true},{"text":" standard, "},{"text":"high rate = 125% of the normal piece rate","bold":true},{"text":" at or above standard. Rewards the efficient and penalises the slow."}]},{"text":[{"text":"Merrick's multiple piece rate:","bold":true},{"text":" efficiency up to 83% = normal piece rate; above 83% up to 100% = "},{"text":"110%","bold":true},{"text":" of normal; above 100% = "},{"text":"120%","bold":true},{"text":" of normal. Slow workers are not penalised."}]},{"text":[{"text":"Efficiency % = Standard time for output ÷ Actual time taken × 100","bold":true},{"text":" (or actual output ÷ standard output × 100)."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Time rate"}],[{"text":"Piece rate"}]],"rows":[[[{"text":"Pay depends on"}],[{"text":"Hours"}],[{"text":"Output"}]],[[{"text":"Labour cost per unit"}],[{"text":"Falls as output rises"}],[{"text":"Constant"}]],[[{"text":"Incentive to produce"}],[{"text":"None"}],[{"text":"Strong"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (standard output, piece rate, effect on unit cost).","bold":true},{"text":" A Lagos plastics factory pays ₦50 per hour; standard time is 12 minutes per unit. In a 40-hour week Bambi makes 66 units, Feranmi 166, Elsie 200 and Tifeh 220."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Standard output per hour = 60 ÷ 12 = "},{"text":"5 units","bold":true},{"text":"."}]},{"text":[{"text":"Piece rate per unit = ₦50 ÷ 5 = "},{"text":"₦10.00","bold":true},{"text":"."}]},{"text":[{"text":"Time-rate pay for each = 40 × ₦50 = ₦2,000."}]}]},{"type":"table","header":[[{"text":"Worker"}],[{"text":"Units"}],[{"text":"Piece pay (× ₦10)"}],[{"text":"Time pay"}],[{"text":"Time-rate cost per unit"}]],"rows":[[[{"text":"Bambi"}],[{"text":"66"}],[{"text":"₦660"}],[{"text":"₦2,000"}],[{"text":"₦30.30"}]],[[{"text":"Feranmi"}],[{"text":"166"}],[{"text":"₦1,660"}],[{"text":"₦2,000"}],[{"text":"₦12.05"}]],[[{"text":"Elsie"}],[{"text":"200"}],[{"text":"₦2,000"}],[{"text":"₦2,000"}],[{"text":"₦10.00"}]],[[{"text":"Tifeh"}],[{"text":"220"}],[{"text":"₦2,200"}],[{"text":"₦2,000"}],[{"text":"₦9.09"}]]]},{"type":"paragraph","text":[{"text":"(Unit costs rounded to 2 decimal places.) Under time rate the cost per unit falls as output rises; under piece rate it stays at ₦10. With a guaranteed day rate, Bambi and Feranmi get ₦2,000 and Tifeh ₦2,200."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (piece rate from a \"units per minutes\" standard).","bold":true},{"text":" Normal day 12 hours, standard output 7 units per 20 minutes, rate ₦42 per hour; a worker makes 4,200 units in 12 hours."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Standard output per hour = 7 × (60 ÷ 20) = "},{"text":"21 units","bold":true},{"text":"."}]},{"text":[{"text":"Piece rate = ₦42 ÷ 21 = "},{"text":"₦2 per unit","bold":true},{"text":"."}]},{"text":[{"text":"Piece-rate pay = 4,200 × ₦2 = "},{"text":"₦8,400","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (guaranteed day rate).","bold":true},{"text":" Bright works 10 hours at ₦360 per hour; standard output is 10 units per 5 minutes; he makes 5,600 units."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Standard output per hour = 10 × (60 ÷ 5) = 120 units; piece rate = ₦360 ÷ 120 = ₦3."}]},{"text":[{"text":"Piece earnings = 5,600 × ₦3 = ₦16,800. Guaranteed time pay = 10 × ₦360 = ₦3,600."}]},{"text":[{"text":"Pay = the higher = "},{"text":"₦16,800","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 4 (Taylor).","bold":true},{"text":" Normal piece rate ₦10; standard 50 units a day. Low rate = 83% × ₦10 = ₦8.30; high rate = 125% × ₦10 = ₦12.50. Musa makes 45 units: 45 × ₦8.30 = "},{"text":"₦373.50","bold":true}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 20, $study_guide$,{"text":". Ngozi makes 55 units: 55 × ₦12.50 = "},{"text":"₦687.50","bold":true},{"text":". Under Merrick, Musa (90% efficiency) gets 45 × ₦11 = "},{"text":"₦495","bold":true},{"text":" and Ngozi (110%) 55 × ₦12 = "},{"text":"₦660","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" a \"units per 20 minutes\" standard must be converted to units per "},{"text":"hour","bold":true},{"text":" before dividing. \"Guaranteed day rate\" means you compare and pay the "},{"text":"higher","bold":true},{"text":", not add the two."}]}]}]},{"number":"5.3","title":"Premium bonus schemes: Halsey, Halsey-Weir and Rowan","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Premium bonus scheme:","bold":true},{"text":" time rate is "},{"text":"guaranteed","bold":true},{"text":" and a bonus is paid for "},{"text":"time saved","bold":true},{"text":"; the gain from time saved is "},{"text":"shared","bold":true},{"text":" between employer and worker."}]},{"text":[{"text":"Halsey (50%):","bold":true},{"text":" Wages = "},{"text":"Time taken × Rate + 50% × Time saved × Rate","bold":true},{"text":"."}]},{"text":[{"text":"Halsey-Weir:","bold":true},{"text":" Wages = "},{"text":"Time taken × Rate + 33⅓% × Time saved × Rate","bold":true},{"text":"."}]},{"text":[{"text":"Rowan:","bold":true},{"text":" Wages = "},{"text":"Time taken × Rate + (Time saved ÷ Time allowed) × Time taken × Rate","bold":true},{"text":"."}]},{"text":[{"text":"Effective hourly rate = Total wages ÷ Time taken.","bold":true}]},{"text":[{"text":"Comparison:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Time saved "},{"text":"less than 50%","bold":true},{"text":" of time allowed: "},{"text":"Rowan","bold":true},{"text":" pays more."}]},{"text":[{"text":"Time saved "},{"text":"exactly 50%","bold":true},{"text":": both pay the "},{"text":"same","bold":true},{"text":"."}]},{"text":[{"text":"Time saved "},{"text":"more than 50%","bold":true},{"text":": "},{"text":"Halsey","bold":true},{"text":" pays more. Rowan's bonus never exceeds time-rate pay."}]}]}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (Halsey).","bold":true},{"text":" Standard time 8 hours, actual 6 hours, rate ₦200."}]},{"type":"paragraph","text":[{"text":"Time saved = 8 − 6 = 2 hours. Wages = 6 × ₦200 + 50% × 2 × ₦200 = ₦1,200 + ₦200 = "},{"text":"₦1,400","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (Halsey, time allowed from output).","bold":true},{"text":" Standard output 21 units per hour (7 per 20 minutes), rate ₦42; a worker makes 4,200 units in 12 hours."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Time allowed = 4,200 ÷ 21 = 200 hours. Time saved = 200 − 12 = 188 hours."}]},{"text":[{"text":"Basic = 12 × ₦42 = ₦504. Bonus = 50% × 188 × ₦42 = ₦3,948."}]},{"text":[{"text":"Gross pay = ₦504 + ₦3,948 = "},{"text":"₦4,452","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (Halsey and Rowan side by side).","bold":true},{"text":" Time allowed 10 hours, rate ₦500."}]},{"type":"table","header":[[{"text":"Time taken"}],[{"text":"Time saved"}],[{"text":"Halsey"}],[{"text":"Rowan"}]],"rows":[[[{"text":"8 hrs (20% saved)"}],[{"text":"2"}],[{"text":"4,000 + 500 = ₦4,500"}],[{"text":"4,000 + (2/10 × 4,000) = ₦4,800"}]],[[{"text":"5 hrs (50% saved)"}],[{"text":"5"}],[{"text":"2,500 + 1,250 = ₦3,750"}],[{"text":"2,500 + (5/10 × 2,500) = ₦3,750"}]],[[{"text":"4 hrs (60% saved)"}],[{"text":"6"}],[{"text":"2,000 + 1,500 = ₦3,500"}],[{"text":"2,000 + (6/10 × 2,000) = ₦3,200"}]]]},{"type":"paragraph","text":[{"text":"Halsey-Weir at 8 hours: 4,000 + ⅓ × 2 × 500 = "},{"text":"₦4,333.33","bold":true},{"text":" (rounded)."}]},{"type":"paragraph","text":[{"text":"Worked example 4 (working back from a Rowan effective rate).","bold":true},{"text":" A worker is allowed 60 hours, guaranteed ₦10 per hour, and earns an effective ₦12 per hour under Rowan. What would Halsey pay for the same time saved?"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Under Rowan, effective rate = Rate × (1 + Time saved ÷ Time allowed). So 12 = 10 × (1 + S ÷ 60), giving S ÷ 60 = 0.2 and "},{"text":"S = 12 hours","bold":true},{"text":"; time taken = 60 − 12 = 48 hours."}]},{"text":[{"text":"Check: Rowan = 480 + (12/60) × 480 = ₦576; ₦576 ÷ 48 = ₦12."}]},{"text":[{"text":"Halsey = 48 × ₦10 + 50% × 12 × ₦10 = ₦480 + ₦60 = "},{"text":"₦540","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" Rowan's fraction multiplies "},{"text":"time taken × rate","bold":true},{"text":", not time saved × rate. ₦576 is the Rowan figure, not Halsey."}]}]}]},{"number":"5.4","title":"Payroll, wages analysis, overtime, shift premium and idle time","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Gross pay = Basic wages + all allowances","bold":true},{"text":" (plus overtime, bonuses and premiums earned)."}]},{"text":[{"text":"Net pay = Gross pay − Deductions.","bold":true},{"text":" Statutory deductions include "},{"text":"PAYE","bold":true},{"text":" income tax and the employee's "},{"text":"pension contribution","bold":true},{"text":"; voluntary ones include union dues, cooperative savings and loan repayments."}]},{"text":[{"text":"Payroll preparation:","bold":true},{"text":" collect clock cards and output records; compute gross pay, deductions and net pay; prepare the payroll and payslips; pay after authorisation, with a separate person checking."}]},{"text":[{"text":"Wages analysis:","bold":true},{"text":" sorting gross wages by job, department and type so that "},{"text":"direct labour","bold":true},{"text":" is charged to jobs or work-in-progress and "},{"text":"indirect labour","bold":true},{"text":" to production overhead."}]},{"text":[{"text":"Ghost workers:","bold":true},{"text":" employ$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 21, $study_guide$ees who "},{"text":"do not exist but whose salaries are being paid","bold":true},{"text":". Controls: verified staff records, surprise headcounts, separate hiring, timekeeping and paying duties."}]},{"text":[{"text":"Overtime premium:","bold":true},{"text":" the amount paid "},{"text":"above the normal rate","bold":true},{"text":" for hours worked beyond normal working time. Overtime pay = basic rate part + premium part."}]},{"text":[{"text":"Shift premium:","bold":true},{"text":" extra pay above the basic rate for working unsocial shifts (e.g. nights)."}]},{"text":[{"text":"Idle time:","bold":true},{"text":" time paid for but not productive. "},{"text":"Idle time ratio = Idle hours ÷ Total hours paid × 100.","bold":true}]}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"Treatment"}]],"rows":[[[{"text":"Overtime premium, general pressure of work"}],[{"text":"Production overhead (spread over all jobs)"}]],[[{"text":"Overtime premium, at a "},{"text":"customer's request","bold":true},{"text":" (early delivery)"}],[{"text":"Charged "},{"text":"directly to that customer's job","bold":true}]],[[{"text":"Overtime premium, abnormal (e.g. poor planning)"}],[{"text":"Overhead or costing profit and loss account"}]],[[{"text":"Shift premium"}],[{"text":"Production overhead, unless one job requires the shift"}]],[[{"text":"Normal","bold":true},{"text":" idle time"}],[{"text":"Production overhead (or built into an inflated hourly rate)"}]],[[{"text":"Abnormal","bold":true},{"text":" idle time"}],[{"text":"Costing profit and loss account","bold":true},{"text":" (not product cost)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Normal idle time (unavoidable):","bold":true},{"text":" walking from the factory gate to the work station, time between finishing one job and starting the next, tea and lunch breaks, tool setting, adjusting machines."}]},{"text":[{"text":"Abnormal idle time (avoidable/controllable):","bold":true},{"text":" "},{"text":"machine breakdowns","bold":true},{"text":", power failure, "},{"text":"non-availability of raw materials","bold":true},{"text":", poor supervision, strikes and lockouts, lack of demand."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (overtime).","bold":true},{"text":" A Lagos company pays ₦200 per hour, overtime at time and a half (₦300 per overtime hour)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Diablo works 42 hours "},{"text":"including","bold":true},{"text":" 20 overtime hours: normal 22 × ₦200 = ₦4,400; overtime 20 × ₦300 = ₦6,000; total "},{"text":"₦10,400","bold":true},{"text":"."}]},{"text":[{"text":"Samson works 38 normal hours "},{"text":"plus","bold":true},{"text":" 12 overtime hours: 38 × ₦200 = ₦7,600; 12 × ₦300 = ₦3,600; total "},{"text":"₦11,200","bold":true},{"text":"."}]},{"text":[{"text":"Diablo's overtime premium = 20 × ₦100 = ₦2,000. Read \"including\" against \"plus\" carefully: it changes the normal hours."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (idle time).","bold":true},{"text":" A Kano flour mill operative attends 45 hours at ₦400 per hour; job cards show 38 hours. Idle 7 hours: 3 hours normal (breaks, setting), 4 hours because wheat did not arrive. Direct labour = 38 × ₦400 = ₦15,200; overhead = 3 × ₦400 = ₦1,200; costing profit and loss = 4 × ₦400 = "},{"text":"₦1,600","bold":true},{"text":". Idle time ratio = 7 ÷ 45 × 100 = 15.56% (rounded)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Control of idle time:","bold":true},{"text":" plan production, order materials on time, maintain machines and report idle time by cause."}]},{"text":[{"text":"Traps:","bold":true},{"text":" gross pay adds allowances to basic; subtracting deductions gives net pay. Abnormal idle time is neither direct cost nor factory overhead."}]}]}]},{"number":"5.5","title":"Labour turnover","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Labour turnover:","bold":true},{"text":" the rate of change in the composition of a firm's workforce over a period; the rate at which workers leave and are replaced."}]},{"text":[{"text":"3 measurement methods","bold":true},{"text":" (average workforce = (opening + closing) ÷ 2):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Separation method","bold":true},{"text":" = Separations ÷ Average workforce × 100 (separations = leavers + discharged)."}]},{"text":[{"text":"Replacement method","bold":true},{"text":" = Replacements ÷ Average workforce × 100. This is the classic \"labour turnover rate\"."}]},{"text":[{"text":"Flux method","bold":true},{"text":" = (Separations + Accessions) ÷ Average workforce × 100 (accessions = all new recruits, including replacements). Some versions use (Separations + Replacements)."}]}]}]},{"text":[{"text":"3 groups of causes:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Personal:","bold":true},{"text":" a better job elsewhere, retirement through ill health or old age, domestic and family problems, discontent with the job."}]},{"text":[{"text":"Unavoidable:","bold":true},{"text":" seasonal business, shortage of raw materials or slack market, change of plant location, "},{"text":"disability making a worker unfit for work","bold":true},{"text":", disciplinary dismissal, marriage."}]},{"text":[{"text":"Avoidable:","bold":true},{"text":" dissatisfaction with the job, pay, hours or conditions; strained relations with management or colleagues; "},{"text":"lack of training","bold":true},{"text":" and promotion; lack of recreational and medical facilities; "},{"text":"low wages and allowances","bold":true},{"text":"."}]}]}]},{"text":[{"text":"2 classes of turnover cost:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Preventive costs","bold":true},{"text":" (keeping workers satisfied): medical services, personnel administration, welfare activities, pension and retireme$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 22, $study_guide$nt schemes. Treated as overhead, apportioned on number of employees."}]},{"text":[{"text":"Replacement costs","bold":true},{"text":" (replacing leavers): recruitment, selection and training, lost output during vacancies, lower output and quality from new workers, scrap and breakages."}]}]}]},{"text":[{"text":"Remedies:","bold":true},{"text":" exit interviews, job analysis, scientific recruitment and promotion, training and grievance procedures, joint committees."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (Chinwe Limited).","bold":true},{"text":" 2,000 workers at the start, 2,100 at the end; 50 terminated, 35 left for unavoidable reasons; 180 employed, 105 of them replacements."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Average workforce = (2,000 + 2,100) ÷ 2 = 2,050. Separations = 50 + 35 = 85."}]},{"text":[{"text":"Separation = 85 ÷ 2,050 × 100 = "},{"text":"4.15%","bold":true},{"text":"."}]},{"text":[{"text":"Replacement = 105 ÷ 2,050 × 100 = 5.12%."}]},{"text":[{"text":"Flux = (85 + 180) ÷ 2,050 × 100 = "},{"text":"12.93%","bold":true},{"text":". (Rates rounded to 2 decimal places.)"}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (Oshodi Manufacturing).","bold":true},{"text":" 500 at the start, 600 at the end; 5 left, 20 discharged, 75 recruited (10 replacements, 65 for expansion)."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Average = 550. Separations = 25."}]},{"text":[{"text":"Replacement = 10 ÷ 550 × 100 = "},{"text":"1.82%","bold":true},{"text":". Separation = 25 ÷ 550 × 100 = "},{"text":"4.55%","bold":true},{"text":". Flux = (25 + 75) ÷ 550 × 100 = 18.18%."}]},{"text":[{"text":"Recruits for "},{"text":"expansion","bold":true},{"text":" are not replacements."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (working backwards, Lagos Textiles).","bold":true},{"text":" Quarterly rates: flux 20%, replacement 10%, separation 6%; 80 workers replaced."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Average workforce = 80 ÷ 10% = 800."}]},{"text":[{"text":"Separations = 6% × 800 = "},{"text":"48","bold":true},{"text":" workers left or were discharged."}]},{"text":[{"text":"Flux: (48 + A) ÷ 800 = 20%, so 48 + A = 160 and "},{"text":"A = 112","bold":true},{"text":" recruited (including replacements)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" use the "},{"text":"average","bold":true},{"text":" workforce, not the opening figure. Disability is an "},{"text":"unavoidable","bold":true},{"text":" cause; low wages and lack of training are avoidable."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Clock card = attendance; job card = time on a job, posted to the job cost sheet; standard hour = work that should be done in one hour."}]},{"text":[{"text":"Pay is time-based or output-based; piece rate = hourly rate ÷ standard output per hour; guaranteed day rate pays the higher."}]},{"text":[{"text":"Taylor: 83% below standard, 125% at or above; Merrick: 100%, 110%, 120%."}]},{"text":[{"text":"Halsey = TT × R + 50% × TS × R; Rowan = TT × R + (TS ÷ TA) × TT × R; Rowan better below 50% saved, Halsey above."}]},{"text":[{"text":"Gross pay = basic + allowances; net pay = gross − deductions; ghost workers are non-existent staff being paid."}]},{"text":[{"text":"Overtime premium: overhead normally, the customer's job if requested; abnormal idle time goes to costing profit and loss."}]},{"text":[{"text":"Turnover: separation, replacement, flux, each over average workforce; costs are preventive and replacement."}]}]}],"theory":{"itemId":"74f14e35-ba13-50b5-a516-cc4edc21cf23","question":[{"type":"paragraph","text":[{"text":"Ada is allowed 12 hours for a job at ₦400 per hour and finishes in 9 hours. Calculate her total wages and effective hourly rate under (a) the Halsey (50%) plan and (b) the Rowan plan."}]}]}}},{"kind":"note","itemId":"e6ce4988-7de0-54b8-8520-1589b29102b0","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Overhead Costing","body":"What overheads are and how they are classified; the main sources of overheads, including depreciation and the fixed asset register; production and service cost centres; allocation, apportionment and the usual bases; re-apportioning service centre costs by the direct, step-down, repeated distribution and algebraic methods; absorption bases and rates (blanket and departmental); predetermined rates; calculating and treating under- and over-absorption.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What overheads are and how they are classified; the main sources of overheads, including depreciation and the fixed asset register; production and service cost centres; allocation, apportionment and the usual bases; re-apportioning service centre costs by the direct, step-down, repeated distribution and algebraic methods; absorption bases and rates (blanket and departmental); predetermined rates; calculating and treating under- and over-absorption."}],"lessons":[{"number":"6.1","title":"Nature, classification and sources of overheads","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Overheads (indirect costs):","bold":true},{"text":" the aggregate of "},{"text":"indirect materials, indirect labour and indirect expenses","bold":true},{"text":". They are all the costs that cannot be traced directly to a cost unit. Overheads are everything except prime cost (direct materials, direct labour, direct expenses)."}]},{"text":[{"text":"Classification by element (3 groups):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Indirect materials:","bold":true},{"text":" lubricating oil, cleaning materials, glue and thread in a shoe factory, small tools."}]},{"text":[{"text":"Indirect labour:","bold":true},{"text":" supervisors, storekeepers, maintenance staff, security, idle time pay, overtime pre$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 23, $study_guide$mium (normally)."}]},{"text":[{"text":"Indirect expenses:","bold":true},{"text":" factory rent, rates, insurance, power and lighting, depreciation, repairs, telephone."}]}]}]},{"text":[{"text":"Classification by function (4 groups):","bold":true},{"text":" production (factory) overheads; administration overheads; selling overheads; distribution overheads."}]},{"text":[{"text":"Classification by behaviour (3 groups):","bold":true},{"text":" fixed (rent, salaries, straight-line depreciation); variable (power for machines, indirect materials that rise with output); semi-variable (telephone, electricity with a standing charge)."}]},{"text":[{"text":"Classification by controllability:","bold":true},{"text":" controllable (can be influenced by the manager of the cost centre) and uncontrollable."}]},{"text":[{"text":"Main sources of overhead figures:","bold":true},{"text":" invoices and the purchase journal (indirect materials and services), stores requisitions (indirect materials), payroll and wages analysis (indirect labour), cash book and petty cash (rent, rates, utilities), and the "},{"text":"fixed asset register","bold":true},{"text":" (depreciation and insurance values)."}]},{"text":[{"text":"Depreciation:","bold":true},{"text":" the share of a fixed asset's cost charged to each period of its useful life. It is an overhead (an indirect expense)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Straight-line depreciation per year = (Cost − Residual value) ÷ Useful life in years."}]},{"text":[{"text":"Reducing balance depreciation = Rate % × Net book value at the start of the year."}]},{"text":[{"text":"Machine hour (production unit) depreciation per hour = (Cost − Residual value) ÷ Total expected machine hours."}]}]}]},{"text":[{"text":"Fixed asset register:","bold":true},{"text":" a detailed record of every fixed asset: description and identification number, location (department or cost centre), date of purchase, cost, supplier, useful life, depreciation method and rate, accumulated depreciation, net book value, insurance value and disposal details."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"fixed overheads\" is a "},{"text":"behaviour","bold":true},{"text":" group, not an element group. Asked which is NOT a group by element, choose fixed overheads; the three element groups are indirect materials, indirect labour and indirect expenses."}]},{"text":[{"text":"Trap: overheads are "},{"text":"all","bold":true},{"text":" indirect costs (materials, labour and expenses), not only factory costs and not only indirect expenses. Prime cost is never overhead."}]},{"text":[{"text":"Why the fixed asset register matters for costing: because it records each asset's "},{"text":"location","bold":true},{"text":" and "},{"text":"value","bold":true},{"text":", it tells you which cost centre to charge depreciation to and gives the value base for apportioning machine insurance and depreciation."}]},{"text":[{"text":"Worked example: a Kano flour mill buys a milling machine for ₦2,000,000, with a residual value of ₦200,000 and a 5-year life (expected to run 36,000 hours in total)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Straight line = (₦2,000,000 − ₦200,000) ÷ 5 = "},{"text":"₦360,000 a year","bold":true},{"text":"."}]},{"text":[{"text":"Reducing balance at 20%: Year 1 = 20% × ₦2,000,000 = "},{"text":"₦400,000","bold":true},{"text":"; NBV = ₦1,600,000; Year 2 = 20% × ₦1,600,000 = "},{"text":"₦320,000","bold":true},{"text":"."}]},{"text":[{"text":"Machine hour = ₦1,800,000 ÷ 36,000 = "},{"text":"₦50 per hour","bold":true},{"text":"; 8,000 hours in a year gives ₦400,000."}]},{"text":[{"text":"The register places the machine in Milling, so the depreciation is "},{"text":"allocated","bold":true},{"text":" to Milling."}]}]}]}]}]},{"number":"6.2","title":"Cost centres, allocation and apportionment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Production cost centre:","bold":true},{"text":" a department where the product is actually made or converted (cutting, stitching, assembly, moulding, milling)."}]},{"text":[{"text":"Service cost centre:","bold":true},{"text":" a department that does not make the product but serves other centres (stores, maintenance, canteen, personnel, power house, quality control, internal transport)."}]},{"text":[{"text":"The overhead process has "},{"text":"3 stages","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Allocation and apportionment","bold":true},{"text":" (primary distribution) of overheads to all cost centres."}]},{"text":[{"text":"Re-apportionment","bold":true},{"text":" (secondary distribution) of service centre costs to production centres."}]},{"text":[{"text":"Absorption","bold":true},{"text":" of production centre overheads into cost units."}]}]}]},{"text":[{"text":"Allocation:","bold":true},{"text":" charging a "},{"text":"whole item of cost","bold":true},{"text":" directly to one cost centre or cost unit, because that centre alone caused it (a storekeeper's salary to Stores; depreciation of a machine located in Cutting)."}]},{"text":[{"text":"Apportionment:","bold":true},{"text":" charging a "},{"text":"proportion of a common item of cost","bold":true},{"text":" to two or more cost centres on some equitable (fair) basis. It is "},{"text":"sharing a common cost","bold":true},{"text":"."}]},{"text":[{"text":"Usual bases of apportionment:","bold":true}]}]},{"type":"table","header":[[{"text":"Overhead"}],[{"text":"Basis"}]],"rows":[[[{"text":"Factory rent, rates, building insurance, lighting, heating, cleaning, building repairs"}],[{"text":"Floor area (or volume) occupied"}]],[[{"text":"Insurance of machinery, depreciation of machinery"}],[{"text":"Value of machinery (plant) in each centre"}]],[[{"text":"Power for machines"}],[{"text":"Kilowatt-hours (or horsepower × machine hours)"}]],[[{"text":"Cante$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 24, $study_guide$en, welfare, personnel department, supervision"}],[{"text":"Number of employees"}]],[[{"text":"Stores department"}],[{"text":"Number (or value) of materials requisitions"}]],[[{"text":"Maintenance department"}],[{"text":"Maintenance hours worked for each centre"}]],[[{"text":"Internal transport"}],[{"text":"Tonne-kilometres or vehicle hours"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: allocation = "},{"text":"whole","bold":true},{"text":" item to one centre; apportionment = "},{"text":"shared","bold":true},{"text":" common cost; absorption = "},{"text":"charging overheads to cost units","bold":true},{"text":" (recovery of overhead). Exams swap these three words freely."}]},{"text":[{"text":"Trap: factory rent goes on "},{"text":"floor space","bold":true},{"text":", not on number of machines or employees. Machinery insurance goes on "},{"text":"value of machines","bold":true},{"text":", not number of machines (a ₦5 million machine needs more cover than a ₦500,000 one). Personnel department cost goes on "},{"text":"number of employees","bold":true},{"text":"."}]},{"text":[{"text":"Worked example (primary distribution): an Aba shoe factory has two production centres (Cutting, Stitching) and two service centres (Stores, Maintenance). Budgeted overheads for the year:"}],"blocks":[{"type":"table","header":[[{"text":"Data"}],[{"text":"Cutting"}],[{"text":"Stitching"}],[{"text":"Stores"}],[{"text":"Maintenance"}],[{"text":"Total"}]],"rows":[[[{"text":"Floor area (m²)"}],[{"text":"4,000"}],[{"text":"5,000"}],[{"text":"2,000"}],[{"text":"1,000"}],[{"text":"12,000"}]],[[{"text":"Value of machinery (₦)"}],[{"text":"400,000"}],[{"text":"300,000"}],[{"text":"50,000"}],[{"text":"50,000"}],[{"text":"800,000"}]],[[{"text":"Employees"}],[{"text":"20"}],[{"text":"30"}],[{"text":"5"}],[{"text":"5"}],[{"text":"60"}]],[[{"text":"Kilowatt-hours"}],[{"text":"5,000"}],[{"text":"2,000"}],[{"text":"500"}],[{"text":"500"}],[{"text":"8,000"}]]]},{"type":"paragraph","text":[{"text":"Overheads: indirect labour (allocated) Cutting ₦60,000, Stitching ₦70,000, Stores ₦40,000, Maintenance ₦20,000; rent ₦240,000; machinery insurance ₦40,000; machinery depreciation ₦80,000; welfare ₦90,000; power ₦80,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Rent ₦240,000 ÷ 12,000 m² = ₦20 per m²: Cutting 4,000 × ₦20 = ₦80,000; Stitching ₦100,000; Stores ₦40,000; Maintenance ₦20,000."}]},{"text":[{"text":"Insurance ₦40,000 ÷ ₦800,000 = 5 kobo per ₦1 of machinery: ₦20,000; ₦15,000; ₦2,500; ₦2,500."}]},{"text":[{"text":"Depreciation ₦80,000 ÷ ₦800,000 = ₦0.10 per ₦1: ₦40,000; ₦30,000; ₦5,000; ₦5,000."}]},{"text":[{"text":"Welfare ₦90,000 ÷ 60 = ₦1,500 per employee: ₦30,000; ₦45,000; ₦7,500; ₦7,500."}]},{"text":[{"text":"Power ₦80,000 ÷ 8,000 kWh = ₦10 per kWh: ₦50,000; ₦20,000; ₦5,000; ₦5,000."}],"blocks":[{"type":"table","header":[[{"text":"Overhead (₦)"}],[{"text":"Basis"}],[{"text":"Cutting"}],[{"text":"Stitching"}],[{"text":"Stores"}],[{"text":"Maintenance"}],[{"text":"Total"}]],"rows":[[[{"text":"Indirect labour"}],[{"text":"Allocated"}],[{"text":"60,000"}],[{"text":"70,000"}],[{"text":"40,000"}],[{"text":"20,000"}],[{"text":"190,000"}]],[[{"text":"Rent"}],[{"text":"Floor area"}],[{"text":"80,000"}],[{"text":"100,000"}],[{"text":"40,000"}],[{"text":"20,000"}],[{"text":"240,000"}]],[[{"text":"Machinery insurance"}],[{"text":"Machine value"}],[{"text":"20,000"}],[{"text":"15,000"}],[{"text":"2,500"}],[{"text":"2,500"}],[{"text":"40,000"}]],[[{"text":"Machinery depreciation"}],[{"text":"Machine value"}],[{"text":"40,000"}],[{"text":"30,000"}],[{"text":"5,000"}],[{"text":"5,000"}],[{"text":"80,000"}]],[[{"text":"Welfare"}],[{"text":"Employees"}],[{"text":"30,000"}],[{"text":"45,000"}],[{"text":"7,500"}],[{"text":"7,500"}],[{"text":"90,000"}]],[[{"text":"Power"}],[{"text":"kWh"}],[{"text":"50,000"}],[{"text":"20,000"}],[{"text":"5,000"}],[{"text":"5,000"}],[{"text":"80,000"}]],[[{"text":"Total","bold":true}],[],[{"text":"280,000","bold":true}],[{"text":"280,000","bold":true}],[{"text":"100,000","bold":true}],[{"text":"60,000","bold":true}],[{"text":"720,000","bold":true}]]]}]}]},{"type":"paragraph","text":[{"text":"Always check the column totals add back to ₦720,000."}]}]}]}]},{"number":"6.3","title":"Re-apportionment of service centre costs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Re-apportionment (secondary distribution):","bold":true},{"text":" moving the total overhead of each service centre to the production centres, because cost units pass only through production centres and can absorb overhead only there."}]},{"text":[{"text":"4 methods:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Direct (one-step) method:","bold":true},{"text":" service costs go "},{"text":"straight to production centres only","bold":true},{"text":"; any services that service centres give each other are ignored."}]},{"text":[{"text":"Step-down (elimination, step) method:","bold":true},{"text":" the service centre that serves the most other centres (or has the largest cost) is closed first, to production centres "},{"text":"and","bold":true},{"text":" the remaining service centres; then the next service centre is closed to production centres and any centres not yet closed; once a centre is closed nothing comes back to it. The last service centre goes to production centres only."}]},{"text":[{"text":"Repeated distribution (continuous allotment) method:","bold":true},{"text":" each service centre's overhead is re-apportioned to "},{"text":"both production centres and other service centres","bold":true},{"text":" that use its services, again and again, until the amounts left are insignificant; the small remainder then goes to production centres."}]},{"text":[{"text":"Algebraic (simultaneous equation) method:","bold":true},{"text":" the total cost of each service centre (its own cost plus its share of the other's) is found with sim$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 25, $study_guide$ultaneous equations, then shared out once."}]}]}]},{"text":[{"text":"Methods 3 and 4 are the "},{"text":"reciprocal service","bold":true},{"text":" methods: they fully recognise that service centres serve each other, and they give the same answer (apart from rounding)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: repeated distribution is a "},{"text":"re-apportionment","bold":true},{"text":" method, "},{"text":"not","bold":true},{"text":" a method of absorption."}]},{"text":[{"text":"Continue the shoe factory: Stores (₦100,000) serves Cutting 50%, Stitching 30%, Maintenance 20%. Maintenance (₦60,000) serves Cutting 40%, Stitching 40%, Stores 20%."}]},{"text":[{"text":"Direct method:","bold":true},{"text":" ignore the 20% each service centre gives the other. Stores is shared in the ratio 50:30 and Maintenance in the ratio 40:40."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stores: Cutting ₦100,000 × 50/80 = ₦62,500; Stitching ₦100,000 × 30/80 = ₦37,500."}]},{"text":[{"text":"Maintenance: Cutting ₦60,000 × 40/80 = ₦30,000; Stitching ₦30,000."}]},{"text":[{"text":"Cutting = ₦280,000 + ₦62,500 + ₦30,000 = "},{"text":"₦372,500","bold":true},{"text":"; Stitching = ₦280,000 + ₦37,500 + ₦30,000 = "},{"text":"₦347,500","bold":true},{"text":". Check: ₦720,000."}]}]}]},{"text":[{"text":"Step-down method","bold":true},{"text":" (close Stores first, because it gives more to Maintenance than Maintenance gives to it):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stores ₦100,000: Cutting ₦50,000; Stitching ₦30,000; Maintenance ₦20,000."}]},{"text":[{"text":"Maintenance now = ₦60,000 + ₦20,000 = ₦80,000, shared 40:40 (Stores is closed): Cutting ₦40,000; Stitching ₦40,000."}]},{"text":[{"text":"Cutting = ₦280,000 + ₦50,000 + ₦40,000 = "},{"text":"₦370,000","bold":true},{"text":"; Stitching = ₦280,000 + ₦30,000 + ₦40,000 = "},{"text":"₦350,000","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Repeated distribution method","bold":true},{"text":" (₦):"}],"blocks":[{"type":"table","header":[[{"text":"Step"}],[{"text":"Cutting"}],[{"text":"Stitching"}],[{"text":"Stores"}],[{"text":"Maintenance"}]],"rows":[[[{"text":"Primary totals"}],[{"text":"280,000"}],[{"text":"280,000"}],[{"text":"100,000"}],[{"text":"60,000"}]],[[{"text":"Stores (50/30/20)"}],[{"text":"50,000"}],[{"text":"30,000"}],[{"text":"(100,000)"}],[{"text":"20,000"}]],[[{"text":"Maintenance (40/40/20)"}],[{"text":"32,000"}],[{"text":"32,000"}],[{"text":"16,000"}],[{"text":"(80,000)"}]],[[{"text":"Stores"}],[{"text":"8,000"}],[{"text":"4,800"}],[{"text":"(16,000)"}],[{"text":"3,200"}]],[[{"text":"Maintenance"}],[{"text":"1,280"}],[{"text":"1,280"}],[{"text":"640"}],[{"text":"(3,200)"}]],[[{"text":"Stores"}],[{"text":"320"}],[{"text":"192"}],[{"text":"(640)"}],[{"text":"128"}]],[[{"text":"Maintenance"}],[{"text":"51.20"}],[{"text":"51.20"}],[{"text":"25.60"}],[{"text":"(128)"}]],[[{"text":"Stores remainder (50:30 to production only)"}],[{"text":"16"}],[{"text":"9.60"}],[{"text":"(25.60)"}],[{"text":"0"}]],[[{"text":"Total","bold":true}],[{"text":"371,667.20","bold":true}],[{"text":"348,332.80","bold":true}],[{"text":"0"}],[{"text":"0"}]]]},{"type":"paragraph","text":[{"text":"Rounded: Cutting "},{"text":"₦371,667","bold":true},{"text":", Stitching "},{"text":"₦348,333","bold":true},{"text":"."}]}]},{"text":[{"text":"Algebraic method:","bold":true},{"text":" let S = total Stores cost and M = total Maintenance cost."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"S = 100,000 + 0.2M and M = 60,000 + 0.2S."}]},{"text":[{"text":"Substitute: S = 100,000 + 0.2(60,000 + 0.2S) = 112,000 + 0.04S, so 0.96S = 112,000 and S = ₦116,666.67."}]},{"text":[{"text":"M = 60,000 + 0.2 × 116,666.67 = ₦83,333.33."}]},{"text":[{"text":"Cutting = 280,000 + 0.5 × 116,666.67 + 0.4 × 83,333.33 = "},{"text":"₦371,666.67","bold":true},{"text":"; Stitching = 280,000 + 0.3 × 116,666.67 + 0.4 × 83,333.33 = "},{"text":"₦348,333.33","bold":true},{"text":" (to 2 decimal places). The same as repeated distribution."}]}]}]},{"text":[{"text":"Direct method with different bases","bold":true},{"text":" (a typical exam set-up): Ifeoma Limited has production centres Molding (₦920,000) and Assembly (₦1,080,000), and service centres Administrative (₦160,000, apportioned on employees) and Maintenance (₦240,000, apportioned on machine hours). Employees: Molding 2,500, Assembly 1,000, Maintenance 500. Machine hours: Molding 6,000, Assembly 12,000, Administrative 200, Maintenance 300."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct method uses "},{"text":"production centres' figures only","bold":true},{"text":", so ignore Maintenance's 500 employees and the service centres' machine hours."}]},{"text":[{"text":"Admin: Molding ₦160,000 × 2,500/3,500 = ₦114,286; Assembly ₦160,000 × 1,000/3,500 = ₦45,714 (to the nearest naira)."}]},{"text":[{"text":"Maintenance: Molding ₦240,000 × 6,000/18,000 = ₦80,000; Assembly ₦240,000 × 12,000/18,000 = ₦160,000."}]},{"text":[{"text":"Molding = ₦920,000 + ₦114,286 + ₦80,000 = "},{"text":"₦1,114,286","bold":true},{"text":"; Assembly = ₦1,080,000 + ₦45,714 + ₦160,000 = "},{"text":"₦1,285,714","bold":true},{"text":". Check: ₦2,400,000."}]},{"text":[{"text":"Trap: options such as ₦194,286 or ₦205,714 are only the "},{"text":"service costs received","bold":true},{"text":"; the question asks for the department's "},{"text":"total","bold":true},{"text":" overhead."}]}]}]}]}]},{"number":"6.4","title":"Absorption bases and rates","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Overhead absorption (recovery):","bold":true},{"text":" charging overheads to cost units, so each product or job carries a fair share. It is the costing technique for sharing production overheads among different products on a fair basis, reflecting the volume of output and effort each product uses."}]},{"text":[{"text":"Overhead absorpti$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 26, $study_guide$on rate (OAR)","bold":true},{"text":" = Budgeted overhead ÷ Budgeted level of the absorption base."}]},{"text":[{"text":"6 methods (bases) of absorption:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Percentage of direct material cost","bold":true},{"text":" = Overhead ÷ Direct material cost × 100."}]},{"text":[{"text":"Percentage of direct labour (wages) cost","bold":true},{"text":" = Overhead ÷ Direct labour cost × 100."}]},{"text":[{"text":"Percentage of prime cost","bold":true},{"text":" = Overhead ÷ Prime cost × 100."}]},{"text":[{"text":"Cost unit (rate per unit of output)","bold":true},{"text":" = Overhead ÷ Units produced. Suitable only when all units are identical."}]},{"text":[{"text":"Direct labour hour rate","bold":true},{"text":" = Overhead ÷ Direct labour hours. Best for labour-intensive departments."}]},{"text":[{"text":"Machine hour rate","bold":true},{"text":" = Overhead ÷ Machine hours. Best for machine-intensive departments."}]}]}]},{"text":[{"text":"Blanket (single, plant-wide) rate:","bold":true},{"text":" one overhead absorption rate used for the "},{"text":"whole factory","bold":true},{"text":"."}]},{"text":[{"text":"Departmental (separate) rates:","bold":true},{"text":" a different rate for each production centre, on the base that suits it. They are more accurate when products spend different amounts of time in different departments."}]},{"text":[{"text":"Non-production overheads:","bold":true},{"text":" administration overheads are commonly absorbed as a "},{"text":"percentage of works (factory) cost","bold":true},{"text":"; selling and distribution overheads as a percentage of "},{"text":"sales value","bold":true},{"text":" or of works cost or cost of production, or a rate per unit sold."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (six bases): a Lagos bakery budgets production overhead of ₦600,000, direct materials ₦1,200,000, direct labour ₦800,000 (prime cost ₦2,000,000), 20,000 units, 40,000 direct labour hours and 15,000 machine hours."}],"blocks":[{"type":"table","header":[[{"text":"Base"}],[{"text":"Calculation"}],[{"text":"Rate"}]],"rows":[[[{"text":"% of direct materials"}],[{"text":"600,000 ÷ 1,200,000 × 100"}],[{"text":"50%"}]],[[{"text":"% of direct labour"}],[{"text":"600,000 ÷ 800,000 × 100"}],[{"text":"75%"}]],[[{"text":"% of prime cost"}],[{"text":"600,000 ÷ 2,000,000 × 100"}],[{"text":"30%"}]],[[{"text":"Per unit"}],[{"text":"600,000 ÷ 20,000"}],[{"text":"₦30 per unit"}]],[[{"text":"Direct labour hour"}],[{"text":"600,000 ÷ 40,000"}],[{"text":"₦15 per DLH"}]],[[{"text":"Machine hour"}],[{"text":"600,000 ÷ 15,000"}],[{"text":"₦40 per MH"}]]]},{"type":"paragraph","text":[{"text":"An order of 500 units uses DM ₦30,000, DL ₦20,000, 900 DLH and 300 MH. Overhead charged: 50% × ₦30,000 = ₦15,000; 75% × ₦20,000 = ₦15,000; 30% × ₦50,000 = ₦15,000; 500 × ₦30 = ₦15,000; 900 × ₦15 = ₦13,500; 300 × ₦40 = ₦12,000. The base chosen changes the cost, so pick the one that best reflects what drives the overhead. Time-based rates (hours) are generally preferred because most overheads build up with time."}]}]},{"text":[{"text":"Working out the hours first:","bold":true},{"text":" products A and B use the same equipment. A: 5,000 units × 1 hour = 5,000 DLH; B: 7,000 units × 2 hours = 14,000 DLH; total 19,000 DLH. Overhead ₦285,000 ÷ 19,000 = "},{"text":"₦15 per DLH","bold":true},{"text":". Trap: dividing by 12,000 units (₦23.75) ignores that B takes twice as long."}]},{"text":[{"text":"Blanket versus departmental:","bold":true},{"text":" in the shoe factory (direct method totals), Cutting ₦372,500 is absorbed on 18,625 machine hours = "},{"text":"₦20 per MH","bold":true},{"text":"; Stitching ₦347,500 on 27,800 DLH = "},{"text":"₦12.50 per DLH","bold":true},{"text":". Cutting also uses 8,200 DLH, so a blanket rate = ₦720,000 ÷ (8,200 + 27,800) = ₦720,000 ÷ 36,000 = "},{"text":"₦20 per DLH","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A pair of boots needs 10 MH and 1 DLH in Cutting and 4 DLH in Stitching."}]},{"text":[{"text":"Departmental: 10 × ₦20 + 4 × ₦12.50 = ₦200 + ₦50 = "},{"text":"₦250","bold":true},{"text":"."}]},{"text":[{"text":"Blanket: (1 + 4) DLH × ₦20 = "},{"text":"₦100","bold":true},{"text":". The blanket rate badly under-costs this machine-heavy product."}]}]}]},{"text":[{"text":"Administration as % of works cost:","bold":true},{"text":" budgeted administration overhead ₦150,000 and budgeted works cost ₦3,000,000 give 5%. A job with works cost ₦40,000 is charged ₦2,000 administration overhead, so its cost of production is ₦42,000."}]}]}]},{"number":"6.5","title":"Predetermined rates, under- and over-absorption","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Predetermined overhead absorption rate:","bold":true},{"text":" the rate determined "},{"text":"before","bold":true},{"text":" the accounting period from estimated (budgeted) overheads and the budgeted level of the chosen absorption basis."}]},{"text":[{"text":"Why predetermined rather than actual rates:","bold":true},{"text":" actual overheads and activity are known only at the end of the period; jobs need costing and pricing (quotations) as they are done; actual rates swing from month to month with seasonal costs and output; predetermined rates smooth this out."}]},{"text":[{"text":"Overhead absorbed","bold":true},{"text":" = Predetermined OAR × "},{"text":"Actual","bold":true},{"text":" level of the base."}]},{"text":[{"text":"Under- or over-absorption","bold":true},{"text":" = Overhead absorbed − Actual overhead."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Over-absorbed","bold":true},{"text":" (over-recovered): absorbed overheads "},{"text":"exceed","bold":true},{"text":" actual overheads. Too much was charged; profit is understated, so the over-absorption is "},{"text":"added","bold":true},{"text":" t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 27, $study_guide$o profit."}]},{"text":[{"text":"Under-absorbed","bold":true},{"text":" (under-recovered): actual overheads "},{"text":"exceed","bold":true},{"text":" absorbed overheads. Too little was charged; the under-absorption is "},{"text":"deducted","bold":true},{"text":" from profit."}]}]}]},{"text":[{"text":"2 causes","bold":true},{"text":" (alone or together): actual overhead differs from budgeted overhead; actual activity (hours or units) differs from budgeted activity."}]},{"text":[{"text":"3 treatments:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Write off to the costing profit and loss account","bold":true},{"text":" when the amount is small or arises from abnormal causes (normal treatment)."}]},{"text":[{"text":"Supplementary rate:","bold":true},{"text":" when the amount is "},{"text":"significant","bold":true},{"text":", adjust the cost of jobs (cost of sales), work in progress and finished goods with a supplementary rate (positive for under-absorption, negative for over-absorption)."}]},{"text":[{"text":"Carry forward","bold":true},{"text":" to the next period when the difference is only seasonal within the year (interim accounts); it should even out by the year end."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: over- and under-absorption compare "},{"text":"absorbed","bold":true},{"text":" with "},{"text":"actual","bold":true},{"text":" overhead. Budgeted overhead is used only to set the rate."}]},{"text":[{"text":"Worked example 1: machine hours budgeted 11,250 with overhead ₦258,750; actual 10,980 hours and overhead ₦254,692."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"OAR = ₦258,750 ÷ 11,250 = ₦23 per machine hour."}]},{"text":[{"text":"Absorbed = 10,980 × ₦23 = ₦252,540."}]},{"text":[{"text":"₦252,540 − ₦254,692 = −₦2,152: "},{"text":"under-absorbed by ₦2,152","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Worked example 2: Daramola Enterprises budgets ₦270,000 for 30,000 machine hours; actual ₦400,000 and 40,000 hours."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"OAR = ₦270,000 ÷ 30,000 = ₦9 per MH; absorbed = 40,000 × ₦9 = ₦360,000."}]},{"text":[{"text":"₦360,000 − ₦400,000 = "},{"text":"₦40,000 under-absorbed","bold":true},{"text":". Trap: ₦60,000 compares the wrong figures."}]}]}]},{"text":[{"text":"Worked example 3 (working backwards): Mary Nigeria Limited has actual overhead ₦300,000, actual activity 120,000 direct labour hours and over-absorption ₦60,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Absorbed = Actual + Over-absorption = ₦300,000 + ₦60,000 = ₦360,000."}]},{"text":[{"text":"OAR = ₦360,000 ÷ 120,000 = "},{"text":"₦3 per direct labour hour","bold":true},{"text":" (the base is hours, so the rate is per DLH, not per unit)."}]},{"text":[{"text":"For under-absorption you would use Absorbed = Actual − Under-absorption."}]}]}]},{"text":[{"text":"Worked example 4 (shoe factory): Cutting worked 19,200 MH with actual overhead ₦375,000: absorbed 19,200 × ₦20 = ₦384,000, so "},{"text":"₦9,000 over-absorbed","bold":true},{"text":". Stitching worked 26,000 DLH with actual overhead ₦352,000: absorbed 26,000 × ₦12.50 = ₦325,000, so "},{"text":"₦27,000 under-absorbed","bold":true},{"text":"."}]},{"text":[{"text":"Supplementary rate: suppose Stitching's ₦27,000 is significant and the ₦325,000 absorbed sits in cost of sales ₦227,500 (70%), finished goods ₦65,000 (20%) and work in progress ₦32,500 (10%)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Supplementary rate = ₦27,000 ÷ ₦325,000 = 8.31% of overhead absorbed (to 2 decimal places)."}]},{"text":[{"text":"Add ₦27,000 × 70% = ₦18,900 to cost of sales, ₦5,400 to finished goods and ₦2,700 to work in progress."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Overheads = indirect materials + indirect labour + indirect expenses; \"fixed overheads\" is a behaviour group, not an element."}]},{"text":[{"text":"Depreciation is an indirect expense; the fixed asset register gives each asset's location and value."}]},{"text":[{"text":"Allocation = whole cost to one centre; apportionment = common cost shared on a fair basis; absorption = charging overheads to cost units."}]},{"text":[{"text":"Rent on floor area; machinery insurance and depreciation on machine value; personnel and canteen on employees; power on kWh."}]},{"text":[{"text":"Re-apportionment: direct (production only), step-down (close one by one), repeated distribution and algebraic (full reciprocal service)."}]},{"text":[{"text":"Absorption bases: % of materials, % of labour, % of prime cost, per unit, labour hour, machine hour. Blanket rate = one rate for the whole factory."}]},{"text":[{"text":"Administration overhead is commonly absorbed as a % of works cost."}]},{"text":[{"text":"OAR = Budgeted overhead ÷ Budgeted base; Absorbed = OAR × Actual base."}]},{"text":[{"text":"Absorbed > Actual = over-absorbed; Actual > Absorbed = under-absorbed."}]},{"text":[{"text":"Small differences go to costing profit and loss; significant ones use a supplementary rate; seasonal ones are carried forward."}]}]}],"theory":{"itemId":"9a8ac7c5-7c69-57dc-a8d7-e48a41c4e8b7","question":[{"type":"paragraph","text":[{"text":"An Ibadan furniture maker budgets production overhead of ₦480,000 and 24,000 machine hours for the year. Actual results were 25,500 machine hours and overhead of ₦498,000. Calculate (a) the overhead absorption rate, (b) the overhead absorbed and (c) the under- or over-absorption, and say how a small difference is treated."}]}]}}},{"kind":"note","itemId":"6f62fa64-3533-56c5-9fc2-18f5d59d5512","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Job and Batch Costing","body":"What job costing is and where it is used; the documents that feed a job; the job cost sheet built from direct materials, direct labour (including idle time), direct expenses $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 28, $study_guide$and overheads; quotations, mark-up and margin; time and materials pricing; batch costing, cost per unit in a batch and the economic batch quantity.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What job costing is and where it is used; the documents that feed a job; the job cost sheet built from direct materials, direct labour (including idle time), direct expenses and overheads; quotations, mark-up and margin; time and materials pricing; batch costing, cost per unit in a batch and the economic batch quantity."}],"lessons":[{"number":"7.1","title":"The nature of job costing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job costing:","bold":true},{"text":" a specific order costing method in which the elements of cost are collected separately for each job (work order) undertaken. It applies where work is done to "},{"text":"customer order","bold":true},{"text":", usually inside a "},{"text":"factory or workshop","bold":true},{"text":", and each order is of "},{"text":"short duration","bold":true},{"text":". The job is the cost unit."}]},{"text":[{"text":"Job:","bold":true},{"text":" a single order, product, unit, batch or service that can be separately identified and must be separately costed."}]},{"text":[{"text":"Purpose:","bold":true},{"text":" to bring together all the costs of completing a job, so that its profit or loss can be found and quotations for similar work can be given."}]}]},{"type":"paragraph","text":[{"text":"Features of job costing:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Work is done against specific customer orders, to the customer's own specification."}]},{"text":[{"text":"Each job is different from others, so each is costed separately."}]},{"text":[{"text":"Direct costs are charged straight to the job because they can be traced to it."}]},{"text":[{"text":"Overheads are charged to the job on a suitable basis, usually a predetermined absorption rate."}]},{"text":[{"text":"Each job has its own number and its own job cost sheet."}]},{"text":[{"text":"Production is not continuous; work in progress may or may not exist at the end of a period."}]},{"text":[{"text":"Closer supervision and control are needed because standard controls are hard to apply."}]}]},{"type":"paragraph","text":[{"text":"Where it is used:","bold":true},{"text":" printing presses, furniture makers, tailors, repair workshops and garages, engineering firms, auditing and consulting firms, building repairs."}]},{"type":"paragraph","text":[{"text":"Main documents:","bold":true}]},{"type":"table","header":[[{"text":"Document"}],[{"text":"What it records"}]],"rows":[[[{"text":"Production (job) order"}],[{"text":"Authority to start the job: job number, customer, quantity, specification"}]],[[{"text":"Materials requisition note"}],[{"text":"Issue of direct material from stores "},{"text":"to a specific job","bold":true},{"text":" (job number on it)"}]],[[{"text":"Materials returned note"}],[{"text":"Surplus material sent back from the job to stores (reduces the job's material cost)"}]],[[{"text":"Materials transfer note"}],[{"text":"Material moved from one job to another"}]],[[{"text":"Job card / time sheet"}],[{"text":"Labour time spent on each job, later costed and posted to the job cost sheet"}]],[[{"text":"Job cost sheet (job account)"}],[{"text":"Running record of all costs charged to the job"}]]]},{"type":"paragraph","text":[{"text":"Job vs other methods:","bold":true}]},{"type":"table","header":[[{"text":"Method"}],[{"text":"Used where"}]],"rows":[[[{"text":"Job costing"}],[{"text":"Customer orders, inside a factory or workshop, short duration"}]],[[{"text":"Batch costing"}],[{"text":"A group of identical units made together as one job"}]],[[{"text":"Contract costing"}],[{"text":"Large jobs, usually on site, lasting a long time (often over a year), e.g. building a bridge"}]],[[{"text":"Process costing"}],[{"text":"Continuous production of identical units through processes, e.g. a Kano flour mill"}]],[[{"text":"Unit (output) costing"}],[{"text":"A single standard product made continuously, e.g. a block-moulding yard"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exams ask \"which method applies where work is done to customer order, usually inside a factory or workshop, and each order is of short duration?\" The answer is "},{"text":"job costing","bold":true},{"text":". Contract costing is the trap: it is also order-based, but contracts are long and usually on site. Process costing is for continuous, identical output."}]},{"text":[{"text":"The "},{"text":"materials requisition note","bold":true},{"text":" records the issue of direct material to a specific job. A purchase requisition is a different document: it asks the buying department to order goods from a supplier."}]},{"text":[{"text":"Batch costing is a form of job costing.","bold":true},{"text":" The job costing method can be applied to batches: the batch is treated as the job."}]},{"text":[{"text":"Advantages:","bold":true},{"text":" shows which jobs are profitable; gives cost records for future quotations; helps control because spoilage and defective work can be traced to a job; suits cost-plus pricing."}]},{"text":[{"text":"Limitations:","bold":true},{"text":" detailed record-keeping makes it time-consuming and expensive; costs of past jobs go out of date when prices change; inefficiencies may be charged to a job that did not cause them."}]},{"text":[{"text":"Example: a Yaba print shop receives an order for 2,000 wedding programmes. It opens Job 318, records paper issued on requisitions marked \"318\", records operators' hours on job cards marked \"318\", and adds overheads at its predetermined rate. When the job is finished the cost sheet shows the total cost and the profit on the job."}]}]}]},{"number":"7.2","title":"The job cost sheet: materials, labour, expenses and overheads","mustKnow":[{"type":"paragraph","text":[{"text":"Job cost$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 29, $study_guide$ sheet layout:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Direct materials (issues less returns)"}]},{"text":[{"text":"Direct labour (hours × rate, per department)"}]},{"text":[{"text":"Direct expenses (e.g. hire of special equipment for this job)"}]},{"text":[{"text":"= Prime cost","bold":true}]},{"text":[{"text":"Production overheads absorbed (predetermined rate × actual base)"}]},{"text":[{"text":"= Production (factory) cost","bold":true}]},{"text":[{"text":"Administration, selling and distribution overheads (often a % of production cost)"}]},{"text":[{"text":"= Total cost","bold":true}]},{"text":[{"text":"Profit"}]},{"text":[{"text":"= Selling price","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A typical job cost contains "},{"text":"actual","bold":true},{"text":" costs for direct material and direct labour, but production overheads are "},{"text":"absorbed at a predetermined rate","bold":true},{"text":" (predetermined rate × actual hours), "},{"text":"not","bold":true},{"text":" actual overheads; "},{"text":"non-production overheads are often added as a percentage of total production cost","bold":true},{"text":". So the statement \"a typical job cost contains actual costs for material, labour and production overheads\" is "},{"text":"false","bold":true},{"text":"."}]},{"text":[{"text":"Production overhead absorbed","bold":true},{"text":" = Predetermined rate × Actual base (machine hours, labour hours or % of direct labour cost)."}]},{"text":[{"text":"Idle time:","bold":true},{"text":" paid hours in which no work is done. If idle time is a % of hours "},{"text":"paid","bold":true},{"text":": Hours paid = Productive hours ÷ (1 − idle %). If idle time is a % of "},{"text":"productive","bold":true},{"text":" hours: Hours paid = Productive hours × (1 + idle %)."}]},{"text":[{"text":"Labour cost of a job","bold":true},{"text":" = Hours paid × Rate per hour paid. "},{"text":"Rate per hour paid","bold":true},{"text":" = Total labour cost ÷ Hours paid."}]},{"text":[{"text":"Overtime premium:","bold":true},{"text":" charged to the job only if the customer asked for the rush work; otherwise it is a production overhead. Normal idle time is built into the job's labour cost or treated as overhead; abnormal idle time goes to costing profit and loss."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (full job cost sheet).","bold":true},{"text":" An Ikeja furniture workshop completes Job 47, a boardroom table."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Materials issued ₦185,000; surplus returned to stores ₦12,000."}]},{"text":[{"text":"Labour: Cutting 40 hours at ₦1,500; Finishing 25 hours at ₦1,200."}]},{"text":[{"text":"Hire of a special spray machine for this job: ₦8,000."}]},{"text":[{"text":"Overheads: Cutting ₦800 per machine hour (job used 30 machine hours); Finishing 50% of direct labour cost."}]},{"text":[{"text":"Administration and selling: 20% of production cost. Profit: 25% on total cost."}]}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"₦"}]],"rows":[[[{"text":"Direct materials (185,000 − 12,000)"}],[{"text":"173,000"}]],[[{"text":"Direct labour: Cutting 40 × 1,500"}],[{"text":"60,000"}]],[[{"text":"Direct labour: Finishing 25 × 1,200"}],[{"text":"30,000"}]],[[{"text":"Direct expenses (spray machine hire)"}],[{"text":"8,000"}]],[[{"text":"Prime cost","bold":true}],[{"text":"271,000","bold":true}]],[[{"text":"Overhead: Cutting 30 × 800"}],[{"text":"24,000"}]],[[{"text":"Overhead: Finishing 50% × 30,000"}],[{"text":"15,000"}]],[[{"text":"Production cost","bold":true}],[{"text":"310,000","bold":true}]],[[{"text":"Admin and selling 20% × 310,000"}],[{"text":"62,000"}]],[[{"text":"Total cost","bold":true}],[{"text":"372,000","bold":true}]],[[{"text":"Profit 25% × 372,000"}],[{"text":"93,000"}]],[[{"text":"Selling price","bold":true}],[{"text":"465,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Note: materials returned reduce the job's cost; the machine-hour rate is applied to machine hours, not labour hours."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (idle time as a % of hours paid).","bold":true},{"text":" A job needs 1,800 productive hours. Idle time is expected to be 10% of hours paid. The rate is ₦1,000 per hour paid."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Productive hours are 90% of hours paid, so hours paid = 1,800 ÷ 0.90 = "},{"text":"2,000 hours","bold":true},{"text":"."}]},{"text":[{"text":"Labour cost = 2,000 × ₦1,000 = "},{"text":"₦2,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Working backwards: if you are told the budgeted labour cost is ₦2,000,000 and asked the rate per hour paid, divide by hours "},{"text":"paid","bold":true},{"text":": ₦2,000,000 ÷ 2,000 = "},{"text":"₦1,000","bold":true},{"text":". Dividing by productive hours (₦2,000,000 ÷ 1,800 = ₦1,111.11) gives the cost per productive hour, not the rate paid."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (idle time as a % of productive hours).","bold":true},{"text":" Same job, but idle time is 25% "},{"text":"of productive hours","bold":true},{"text":". Hours paid = 1,800 × 1.25 = 2,250; cost at ₦1,000 = ₦2,250,000. Read the wording carefully: \"25% of hours paid\" means divide by 0.75; \"25% of productive hours\" means multiply by 1.25."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: do not charge general overtime premium to whichever job happened to be worked in the evening; it is an overhead spread over all jobs. Do not include indirect materials (glue, sandpaper) on the requisition for a job; they are overheads absorbed through the rate."}]},{"text":[{"text":"Work in progress:","bold":true},{"text":" at the period end, the cost sheets of unfinished jobs give the value of work in progress. On completion the job's cost is transferred to finished goods (or cost of sales), and profit on the job =$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 30, $study_guide$ selling price − total cost."}]}]}]},{"number":"7.3","title":"Quotations, mark-up and margin","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Quotation (estimate):","bold":true},{"text":" the price offered to a customer "},{"text":"before","bold":true},{"text":" the job is done, built from estimated costs on a job cost sheet plus the profit required."}]},{"text":[{"text":"Mark-up (profit on cost):","bold":true},{"text":" Selling price = Total cost × (1 + mark-up %). Total cost = Selling price ÷ (1 + mark-up %)."}]},{"text":[{"text":"Margin (profit on sales):","bold":true},{"text":" Selling price = Total cost ÷ (1 − margin %). Total cost = Selling price × (1 − margin %)."}]},{"text":[{"text":"Mark-up 25% = margin 20%; mark-up 33⅓% = margin 25%. Margin % = Mark-up % ÷ (1 + mark-up %)."}]},{"text":[{"text":"Prime cost","bold":true},{"text":" = Total cost − Overheads (when total cost = prime cost + overheads)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 4 (mark-up vs margin on the same cost).","bold":true},{"text":" Estimated total cost of a job is ₦80,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"25% mark-up on cost: price = 80,000 × 1.25 = "},{"text":"₦100,000","bold":true},{"text":" (profit ₦20,000)."}]},{"text":[{"text":"25% margin on sales: price = 80,000 ÷ 0.75 = "},{"text":"₦106,666.67","bold":true},{"text":" (profit ₦26,666.67, rounded to kobo). Check: 26,666.67 ÷ 106,666.67 = 25%."}]}]},{"type":"paragraph","text":[{"text":"Worked example 5 (working back to prime cost).","bold":true},{"text":" An Aba shoe factory prices jobs by adding overheads to prime cost and then adding 30% of total cost as profit. Job K12 sold for ₦2,600 and was charged overheads of ₦450."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Price = Total cost × 1.30, so total cost = 2,600 ÷ 1.30 = "},{"text":"₦2,000","bold":true},{"text":"."}]},{"text":[{"text":"Prime cost = Total cost − Overheads = 2,000 − 450 = "},{"text":"₦1,550","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Trap: treating the 30% as a margin gives total cost = 2,600 × 0.70 = ₦1,820 and prime cost ₦1,370, which is wrong here because the profit is a percentage of "},{"text":"cost","bold":true},{"text":". Another trap is taking 30% off the selling price as if the profit were ₦780 and then forgetting to remove overheads. Always ask: \"30% of what?\""}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A quotation that is too high loses the order; one too low wins work that makes a loss. That is why accurate past job cost sheets matter."}]},{"text":[{"text":"Quotations normally use "},{"text":"predetermined","bold":true},{"text":" overhead rates, because actual overheads are not known until the period ends."}]}]}]},{"number":"7.4","title":"Time and materials pricing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Time and materials pricing:","bold":true},{"text":" a pricing method used mainly by service and repair businesses (mechanics, plumbers, electricians, generator repairers). The customer is charged:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"a "},{"text":"labour (time) charge","bold":true},{"text":" = hours worked × charge-out rate per hour, where the rate covers wages, overheads and profit; plus"}]},{"text":[{"text":"a "},{"text":"materials charge","bold":true},{"text":" = cost of parts and materials used + a materials "},{"text":"handling (loading) mark-up","bold":true},{"text":" covering ordering, storage and profit on materials."}]}]}]},{"text":[{"text":"Price","bold":true},{"text":" = (Hours × Charge-out rate) + Materials cost × (1 + handling %)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 6.","bold":true},{"text":" A generator repair shop in Surulere charges ₦3,000 per labour hour and adds 15% to the cost of parts. A repair takes 6 hours and uses parts costing ₦40,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Time charge = 6 × ₦3,000 = ₦18,000."}]},{"text":[{"text":"Materials charge = ₦40,000 × 1.15 = ₦46,000."}]},{"text":[{"text":"Price = 18,000 + 46,000 = "},{"text":"₦64,000","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The charge-out rate is higher than the wage rate because it also recovers overheads and profit; the mechanic may earn only ₦1,000 an hour."}]},{"text":[{"text":"Strength: easy to explain and fair when the time needed is uncertain. Weakness: a slow worker raises the bill, so customers often ask for an estimate first."}]}]}]},{"number":"7.5","title":"Batch costing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Batch:","bold":true},{"text":" a separate, readily identifiable group of identical units that keeps its identity throughout production."}]},{"text":[{"text":"Batch costing:","bold":true},{"text":" a form of job costing in which the "},{"text":"batch is treated as the job (cost unit)","bold":true},{"text":". Costs are collected on a batch cost sheet with a batch number, then:"}]},{"text":[{"text":"Cost per unit","bold":true},{"text":" = Total batch cost ÷ Number of units in the batch."}]},{"text":[{"text":"Used in:","bold":true},{"text":" garments, toys, shoes, tyres, drugs and tablets, printed exercise books, biscuits."}]}]},{"type":"paragraph","text":[{"text":"Features:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identical units are made together, and costing each unit separately is uneconomical."}]},{"text":[{"text":"Each batch gets a number; materials, labour and overheads are recorded batch by batch."}]},{"text":[{"text":"Set-up costs","bold":true},{"text":" are incurred once per batch, whatever its size, so bigger batches spread them over more units."}]}]},{"type":"table","header":[[{"text":"Job costing"}],[{"text":"Batch costing"}]],"rows":[[[{"text":"Cost unit is o$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 31, $study_guide$ne job"}],[{"text":"Cost unit is a batch of identical units"}]],[[{"text":"Each job is different"}],[{"text":"Units in a batch are identical"}]],[[{"text":"Cost found per job"}],[{"text":"Cost found per batch, then per unit"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Economic batch quantity (EBQ):","bold":true},{"text":" the batch size that minimises set-up plus holding cost. In its simplest form (the whole batch goes into stock at once), EBQ = √(2 × D × S ÷ H), where D = annual demand, S = set-up cost per batch, H = holding cost per unit per year."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 7 (batch cost sheet).","bold":true},{"text":" A Lagos printer makes a batch of 500 branded exercise books: materials ₦150,000, direct labour ₦60,000, machine set-up ₦15,000, design ₦25,000. Production overhead is 40% of direct labour; admin and selling are 10% of production cost; profit is 20% of selling price."}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"₦"}]],"rows":[[[{"text":"Materials + labour + set-up + design"}],[{"text":"250,000"}]],[[{"text":"Production overhead 40% × 60,000"}],[{"text":"24,000"}]],[[{"text":"Production cost","bold":true}],[{"text":"274,000","bold":true}]],[[{"text":"Admin and selling 10%"}],[{"text":"27,400"}]],[[{"text":"Total cost of batch","bold":true}],[{"text":"301,400","bold":true}]],[[{"text":"Selling price = 301,400 ÷ 0.80"}],[{"text":"376,750"}]]]},{"type":"paragraph","text":[{"text":"Cost per book = 301,400 ÷ 500 = "},{"text":"₦602.80","bold":true},{"text":"; price per book = 376,750 ÷ 500 = "},{"text":"₦753.50","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 8 (scaling a typical batch).","bold":true},{"text":" A typical batch of 100 bags costs: materials ₦6,000, labour ₦2,000, set-up ₦1,500 (once per batch). Design ₦3,000 is once per order. A customer orders 600 bags made in one run. Overhead is 20% of labour; admin 5% of production cost; profit 25% of sales."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Materials 6 × 6,000 = 36,000; labour 6 × 2,000 = 12,000; set-up 1,500 (one run); design 3,000. Prime cost = "},{"text":"₦52,500","bold":true},{"text":"."}]},{"text":[{"text":"Overhead 20% × 12,000 = 2,400; production cost = 54,900."}]},{"text":[{"text":"Admin 5% × 54,900 = 2,745; total cost = "},{"text":"₦57,645","bold":true},{"text":"."}]},{"text":[{"text":"Price = 57,645 ÷ 0.75 = "},{"text":"₦76,860","bold":true},{"text":", i.e. ₦128.10 a bag."}]}]},{"type":"paragraph","text":[{"text":"Trap: multiplying the whole typical-batch cost by 6 (₦75,000 prime cost) wrongly repeats set-up and design."}]},{"type":"paragraph","text":[{"text":"Worked example 9 (EBQ).","bold":true},{"text":" A Kano biscuit factory sells 36,000 packs a year. Each set-up costs ₦5,000; holding cost is ₦40 per pack per year."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"EBQ = √(2 × 36,000 × 5,000 ÷ 40) = √9,000,000 = "},{"text":"3,000 packs","bold":true},{"text":"."}]},{"text":[{"text":"Batches a year = 36,000 ÷ 3,000 = 12; set-up cost = 12 × ₦5,000 = ₦60,000; holding cost = 3,000 ÷ 2 × ₦40 = ₦60,000. They are equal at the EBQ, as with EOQ."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job costing: customer order, inside a factory or workshop, short duration; each job costed separately. Contract costing is long and on site."}]},{"text":[{"text":"Materials requisition note = direct material issued to a specific job; job cards record labour time."}]},{"text":[{"text":"Job cost sheet: direct materials + direct labour + direct expenses = prime cost; + production overhead = production cost; + non-production overhead (often % of production cost) = total cost; + profit = price."}]},{"text":[{"text":"Idle time % of hours paid: hours paid = productive hours ÷ (1 − idle %); rate per hour paid = labour cost ÷ hours paid."}]},{"text":[{"text":"Mark-up: price = cost × (1 + %). Margin: price = cost ÷ (1 − %). Prime cost = total cost − overheads."}]},{"text":[{"text":"Time and materials: hours × charge-out rate + materials × (1 + handling %)."}]},{"text":[{"text":"Batch costing is job costing applied to batches; cost per unit = batch cost ÷ units. Set-up is once per batch."}]},{"text":[{"text":"EBQ = √(2DS ÷ H)."}]}]}],"theory":{"itemId":"ef506dd6-c5ac-592d-9802-fed3e4a82792","question":[{"type":"paragraph","text":[{"text":"A Lekki tailoring workshop is quoting for Job 92: materials ₦45,000; 120 labour hours at ₦500 an hour; production overhead ₦300 per labour hour; administration overhead 10% of production cost. The workshop wants a profit of 20% of the selling price. Calculate the quoted price."}]}]}}},{"kind":"note","itemId":"b180e6e0-bd35-5bca-8455-4c73fba6d2b1","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Marginal and Absorption Costing","body":"Marginal cost and marginal (variable) costing; absorption (full) costing; contribution and how to compute it per unit and in total; the distinction between the two techniques; how each values stock; preparing marginal and absorption profit statements, including under- and over-absorption; reconciling the two profits.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"Marginal cost and marginal (variable) costing; absorption (full) costing; contribution and how to compute it per unit and in total; the distinction between the two techniques; how each values stock; preparing marginal and absorption profit statements, including under- and over-absorption; reconciling the two profits."}],"lessons":[{"number":"8.1","title":"Nature of marginal and absorption costing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marginal cost:","bold":true},{"text":" the variable cost of one unit of a product or service, which would be avoided if that unit were not produced. In the cost accountant's sense, marginal production cost per unit = direct materials + direct l$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 32, $study_guide$abour + direct expenses + variable production overhead per unit (that is, prime cost + variable overhead); any variable selling cost per unit is added to this to give the full marginal cost used for contribution."}]},{"text":[{"text":"Marginal costing:","bold":true},{"text":" a costing technique in which only "},{"text":"variable costs","bold":true},{"text":" are charged to cost units (products). "},{"text":"Fixed costs","bold":true},{"text":" are treated as "},{"text":"period costs","bold":true},{"text":" and written off in full against the contribution of the period in which they arise. Marginal costing is also known as "},{"text":"variable costing","bold":true},{"text":" (and as "},{"text":"direct costing","bold":true},{"text":")."}]},{"text":[{"text":"Absorption costing:","bold":true},{"text":" a costing technique in which "},{"text":"all production costs, fixed and variable","bold":true},{"text":", are charged to cost units. Fixed production overhead is absorbed into units using a predetermined overhead absorption rate. Absorption costing is also known as "},{"text":"full costing","bold":true},{"text":" (or total costing)."}]},{"text":[{"text":"Contribution:","bold":true},{"text":" the difference between sales and the marginal (variable) cost of sales. It \"contributes\" first to covering fixed costs and then to profit."}]},{"text":[{"text":"Basic marginal costing equation:","bold":true},{"text":" Sales − Variable cost = Contribution = Fixed cost + Profit (or − Loss)."}]},{"text":[{"text":"Features of marginal costing:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Costs are split into fixed and variable (semi-variable costs are separated, for example by the high-low method)."}]},{"text":[{"text":"Only variable costs are charged to products and included in stock values."}]},{"text":[{"text":"Fixed costs are period costs, charged in full to the period's profit and loss."}]},{"text":[{"text":"Stock (work-in-progress and finished goods) is valued at marginal (variable) production cost."}]},{"text":[{"text":"Profitability of products is judged by their "},{"text":"contribution","bold":true},{"text":"."}]},{"text":[{"text":"Marginal costing is a "},{"text":"technique","bold":true},{"text":", not a method: it can be used alongside job, batch or process costing."}]}]}]},{"text":[{"text":"Advantages of marginal costing:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Simple to understand and operate; no arbitrary apportionment of fixed costs to products."}]},{"text":[{"text":"Profit moves with "},{"text":"sales","bold":true},{"text":", not with production, so profit cannot be inflated by building up stock."}]},{"text":[{"text":"No under- or over-absorption of fixed overheads."}]},{"text":[{"text":"Contribution helps decisions: product mix, make or buy, special orders, pricing, shutting down a product, break-even."}]},{"text":[{"text":"Helps cost control, because fixed and variable costs are reported separately."}]}]}]},{"text":[{"text":"Limitations of marginal costing:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Splitting costs into fixed and variable is difficult and sometimes arbitrary."}]},{"text":[{"text":"Stock is undervalued, since fixed production overhead is left out; not acceptable for published financial statements (IAS 2 requires production overheads to be included in stock)."}]},{"text":[{"text":"Ignores fixed costs in pricing, which can lead to prices that fail to cover total cost in the long run."}]},{"text":[{"text":"Fixed costs are not always fixed, and variable costs do not always vary in a straight line."}]},{"text":[{"text":"Less useful where fixed costs form most of total cost (for example, highly automated factories)."}]}]}]},{"text":[{"text":"Advantages of absorption costing:","bold":true},{"text":" complies with IAS 2 for financial reporting; recognises that fixed production costs are part of making a product; avoids showing big losses in seasonal businesses that build stock before the selling season; full cost is a sound base for long-run pricing."}]},{"text":[{"text":"Limitations of absorption costing:","bold":true},{"text":" apportionment and absorption of fixed overhead are arbitrary; profit can be raised simply by producing more than is sold; under- or over-absorption arises; full cost per unit changes with the level of output, which misleads decisions."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The word \"marginal\" in economics means the cost of one extra unit. In cost accounting, marginal cost per unit is the "},{"text":"variable cost per unit","bold":true},{"text":", because producing one more unit adds only variable cost; fixed cost stays the same."}]},{"text":[{"text":"Trap: marginal costing is also known as "},{"text":"variable costing","bold":true},{"text":", not absorption costing or full costing (those two are the same thing as each other), and not standard costing (a separate technique, Topic 10)."}]},{"text":[{"text":"Trap: \"the variable cost of one unit which would be avoided if that unit were not produced\" defines "},{"text":"marginal cost","bold":true},{"text":", not average total cost (which includes fixed cost) and not sunk cost (a past cost that cannot be recovered)."}]},{"text":[{"text":"Both techniques treat "},{"text":"non-production costs","bold":true},{"text":" (administration, selling and distribution) as period costs. The only cost that is treated differently is "},{"text":"fixed production overhead","bold":true},{"text":"."}]},{"text":[{"text":"Variable selling costs (for example, sales commission per unit) are part of marginal cost for working out contribution, but they are "},{"text":"never","bold":true},{"text":" included in stock values, under either technique, because they arise only when goods are sold."}]}]}]},{"number":"8.2","title":"Contribution and profit$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 33, $study_guide$ under marginal costing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Contribution per unit = Selling price per unit − Variable cost per unit.","bold":true}]},{"text":[{"text":"Total contribution = Sales − Total variable cost = Contribution per unit × Units sold.","bold":true}]},{"text":[{"text":"Profit = Total contribution − Fixed costs.","bold":true}]},{"text":[{"text":"Contribution to sales (C/S) ratio = Contribution ÷ Sales × 100%","bold":true},{"text":" (also called the profit-volume or P/V ratio; used fully in Topic 9)."}]},{"text":[{"text":"Contribution per unit stays "},{"text":"constant","bold":true},{"text":" at every level of activity (as long as selling price and variable cost per unit do not change); profit per unit does "},{"text":"not","bold":true},{"text":", because fixed cost per unit falls as output rises."}]},{"text":[{"text":"Fixed costs are "},{"text":"excluded","bold":true},{"text":" when computing contribution."}]}]},{"type":"table","header":[[{"text":"Item"}],[{"text":"Marginal costing view"}]],"rows":[[[{"text":"Variable cost per unit"}],[{"text":"Constant"}]],[[{"text":"Total variable cost"}],[{"text":"Rises with output"}]],[[{"text":"Fixed cost in total"}],[{"text":"Constant (for the period)"}]],[[{"text":"Fixed cost per unit"}],[{"text":"Falls as output rises"}]],[[{"text":"Contribution per unit"}],[{"text":"Constant"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1: contribution per unit.","bold":true},{"text":" 100,000 units of product JIG were produced and sold. Sales ₦500,000; variable production cost ₦175,000; fixed production cost ₦75,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Total contribution = Sales − Variable cost = ₦500,000 − ₦175,000 = ₦325,000."}]},{"text":[{"text":"Contribution per unit = ₦325,000 ÷ 100,000 = "},{"text":"₦3.25","bold":true},{"text":"."}]},{"text":[{"text":"Check by unit figures: selling price = ₦500,000 ÷ 100,000 = ₦5.00; variable cost = ₦175,000 ÷ 100,000 = ₦1.75; contribution = ₦5.00 − ₦1.75 = ₦3.25."}]},{"text":[{"text":"Profit = ₦325,000 − ₦75,000 = ₦250,000 (₦2.50 per unit)."}]}]},{"type":"paragraph","text":[{"text":"Traps: ₦5 is the selling price, not the contribution. ₦2.50 is profit per unit (it deducts fixed cost). Never deduct fixed cost when asked for contribution."}]},{"type":"paragraph","text":[{"text":"Worked example 2: profit under marginal costing.","bold":true},{"text":" Eko Plastics Ltd: fixed cost ₦500,000 for the quarter; variable cost ₦10 per unit; selling price ₦15 per unit; output and sales 150,000 units."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Contribution per unit = ₦15 − ₦10 = ₦5."}]},{"text":[{"text":"Total contribution = 150,000 × ₦5 = ₦750,000."}]},{"text":[{"text":"Profit = ₦750,000 − ₦500,000 = "},{"text":"₦250,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"In statement form:"}]},{"type":"table","header":[[],[{"text":"₦"}]],"rows":[[[{"text":"Sales (150,000 × ₦15)"}],[{"text":"2,250,000"}]],[[{"text":"Less variable cost (150,000 × ₦10)"}],[{"text":"(1,500,000)"}]],[[{"text":"Contribution"}],[{"text":"750,000"}]],[[{"text":"Less fixed cost"}],[{"text":"(500,000)"}]],[[{"text":"Profit"}],[{"text":"250,000"}]]]},{"type":"paragraph","text":[{"text":"C/S ratio = 750,000 ÷ 2,250,000 × 100% = 33.33% (rounded to two decimal places). Traps: ₦750,000 is contribution, not profit; ₦1,750,000 wrongly adds instead of deducting."}]},{"type":"paragraph","text":[{"text":"Why contribution guides decisions.","bold":true},{"text":" If Eko Plastics sold one extra unit, profit would rise by exactly ₦5 (its contribution), because fixed cost does not change. Under absorption costing, a \"full cost\" per unit of ₦10 + (₦500,000 ÷ 150,000) = ₦13.33 (rounded) makes the extra unit seem to earn only ₦1.67, which is wrong for a short-term decision."}]}]},{"number":"8.3","title":"Distinction between the two techniques and stock valuation","mustKnow":[{"type":"table","header":[[{"text":"Point"}],[{"text":"Marginal (variable) costing"}],[{"text":"Absorption (full) costing"}]],"rows":[[[{"text":"Costs charged to products"}],[{"text":"Variable production costs only"}],[{"text":"All production costs, fixed and variable"}]],[[{"text":"Fixed production overhead"}],[{"text":"Period cost: written off in full in the period incurred"}],[{"text":"Product cost: absorbed into units using a predetermined rate"}]],[[{"text":"Stock valuation"}],[{"text":"At variable (marginal) production cost"}],[{"text":"At full production cost (variable + absorbed fixed production overhead)"}]],[[{"text":"Key profit measure"}],[{"text":"Contribution, then net profit"}],[{"text":"Gross profit, then net profit"}]],[[{"text":"Under/over-absorption"}],[{"text":"Does not arise"}],[{"text":"Arises and must be adjusted in the profit statement"}]],[[{"text":"Profit depends on"}],[{"text":"Sales volume only"}],[{"text":"Sales "},{"text":"and","bold":true},{"text":" production volume"}]],[[{"text":"Use"}],[{"text":"Internal decision-making and control"}],[{"text":"Financial reporting (IAS 2), long-run pricing"}]],[[{"text":"Presentation of costs"}],[{"text":"By behaviour (variable, then fixed)"}],[{"text":"By function (production, administration, selling)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Fixed production overhead absorption rate (OAR) = Budgeted fixed production overhead ÷ Budgeted (normal) production volume.","bold":true}]},{"text":[{"text":"Stock value under marginal costing = Units in stock × Variable production cost per unit.","bold":true}]},{"text":[{"text":"Stock value under absorption costing = Units in stock × (Variable production cost per unit + Fixed OAR).","bold":true}]},{"text":[{"text":"Difference in stock values = Units in stock × Fixed OAR.","bold":true}]},{"text":[{"text":"Fixed overhead absorbed = Actual production × OAR.","bold":true}]},{"text":[{"text":"Under-absorption:","bold":true$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 34, $study_guide$},{"text":" absorbed < actual fixed overhead; added to cost of sales (reduces profit). "},{"text":"Over-absorption:","bold":true},{"text":" absorbed > actual fixed overhead; deducted from cost of sales (increases profit)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 3: stock valuation.","bold":true},{"text":" A Kano flour mill makes 50 kg bags of flour. Variable production cost is ₦18,000 a bag (wheat, direct labour, variable milling overhead). Fixed production overhead is budgeted at ₦6,000,000 a month for a normal output of 4,000 bags. At month end, 500 bags are unsold."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"OAR = ₦6,000,000 ÷ 4,000 = ₦1,500 a bag."}]},{"text":[{"text":"Full production cost a bag = ₦18,000 + ₦1,500 = ₦19,500."}]},{"text":[{"text":"Closing stock, marginal costing = 500 × ₦18,000 = "},{"text":"₦9,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Closing stock, absorption costing = 500 × ₦19,500 = "},{"text":"₦9,750,000","bold":true},{"text":"."}]},{"text":[{"text":"Difference = 500 × ₦1,500 = ₦750,000 of fixed overhead \"carried forward\" in stock under absorption costing."}]}]},{"type":"paragraph","text":[{"text":"Under- and over-absorption.","bold":true},{"text":" Suppose the mill actually produced 4,400 bags and actual fixed overhead was exactly ₦6,000,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Absorbed = 4,400 × ₦1,500 = ₦6,600,000."}]},{"text":[{"text":"Over-absorbed = ₦6,600,000 − ₦6,000,000 = "},{"text":"₦600,000","bold":true},{"text":" (deduct from cost of sales)."}]}]},{"type":"paragraph","text":[{"text":"If actual fixed overhead had been ₦6,300,000 instead, over-absorption = ₦6,600,000 − ₦6,300,000 = ₦300,000. Under- or over-absorption therefore comes from two causes: actual production differing from normal production (volume), and actual fixed overhead differing from budget (expenditure)."}]},{"type":"paragraph","text":[{"text":"Traps: selling and administration costs (fixed or variable) and variable selling costs are "},{"text":"never","bold":true},{"text":" included in stock. The only reason stock values differ between the two techniques is fixed production overhead."}]}]},{"number":"8.4","title":"Preparing marginal and absorption profit statements","mustKnow":[{"type":"paragraph","text":[{"text":"Marginal costing statement (layout):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sales"}]},{"text":[{"text":"Less variable cost of sales: opening stock (at variable cost) + variable production cost − closing stock (at variable cost)"}]},{"text":[{"text":"= Production contribution (if you wish to show it)"}]},{"text":[{"text":"Less variable selling and distribution costs"}]},{"text":[{"text":"= "},{"text":"Contribution","bold":true}]},{"text":[{"text":"Less fixed costs (fixed production overhead actually incurred, fixed administration, fixed selling)"}]},{"text":[{"text":"= "},{"text":"Net profit","bold":true}]}]},{"type":"paragraph","text":[{"text":"Absorption costing statement (layout):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sales"}]},{"text":[{"text":"Less cost of sales: opening stock (at full cost) + production cost (at full cost) − closing stock (at full cost)"}]},{"text":[{"text":"Add under-absorbed overhead "},{"text":"or","bold":true},{"text":" deduct over-absorbed overhead"}]},{"text":[{"text":"= "},{"text":"Gross profit","bold":true}]},{"text":[{"text":"Less non-production costs (administration, selling and distribution, both variable and fixed)"}]},{"text":[{"text":"= "},{"text":"Net profit","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost of production","bold":true},{"text":" (absorption) = units produced × full production cost per unit; (marginal) = units produced × variable production cost per unit."}]},{"text":[{"text":"Closing stock units = Opening stock + Production − Sales."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 4: full statements for two months.","bold":true},{"text":" An Aba shoe factory makes one style of leather shoe. Data per pair: selling price ₦5,000; direct materials ₦1,200; direct labour ₦500; variable production overhead ₦300; variable selling cost (commission) ₦250 per pair sold. Fixed production overhead ₦3,000,000 a month, budgeted on a normal output of 2,000 pairs. Fixed administration and selling costs ₦1,000,000 a month. Actual fixed costs equal budget. There is no opening stock in Month 1."}]},{"type":"table","header":[[],[{"text":"Month 1"}],[{"text":"Month 2"}]],"rows":[[[{"text":"Production (pairs)"}],[{"text":"2,000"}],[{"text":"1,800"}]],[[{"text":"Sales (pairs)"}],[{"text":"1,600"}],[{"text":"2,100"}]]]},{"type":"paragraph","text":[{"text":"Preliminary workings:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Variable production cost a pair = ₦1,200 + ₦500 + ₦300 = ₦2,000."}]},{"text":[{"text":"OAR = ₦3,000,000 ÷ 2,000 = ₦1,500 a pair."}]},{"text":[{"text":"Full production cost a pair = ₦2,000 + ₦1,500 = ₦3,500."}]},{"text":[{"text":"Stock: Month 1 closing = 0 + 2,000 − 1,600 = 400 pairs. Month 2 closing = 400 + 1,800 − 2,100 = 100 pairs."}]},{"text":[{"text":"Absorption: Month 1 absorbed 2,000 × ₦1,500 = ₦3,000,000 (no under/over). Month 2 absorbed 1,800 × ₦1,500 = ₦2,700,000, so "},{"text":"under-absorbed ₦300,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Marginal costing profit statement","bold":true}]},{"type":"table","header":[[],[{"text":"Month 1 ₦"}],[{"text":"Month 2 ₦"}]],"rows":[[[{"text":"Sales (1,600 / 2,100 × ₦5,000)"}],[{"text":"8,000,000"}],[{"text":"10,500,000"}]],[[{"text":"Opening stock (× ₦2,000)"}],[{"text":"0"}],[{"text":"800,000"}]],[[{"text":"Add variable production cost (2,000 / 1,800 × ₦2,000)"}],[{"text":"4,000,000"}],[{"text":"3,600,000"}]],[[{"text":"Less closing stock (400 / 100 × ₦2,000)"}],[{"text":"(800$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 35, $study_guide$,000)"}],[{"text":"(200,000)"}]],[[{"text":"Variable production cost of sales"}],[{"text":"3,200,000"}],[{"text":"4,200,000"}]],[[{"text":"Add variable selling cost (× ₦250)"}],[{"text":"400,000"}],[{"text":"525,000"}]],[[{"text":"Total variable cost of sales"}],[{"text":"(3,600,000)"}],[{"text":"(4,725,000)"}]],[[{"text":"Contribution","bold":true}],[{"text":"4,400,000"}],[{"text":"5,775,000"}]],[[{"text":"Less fixed production overhead"}],[{"text":"(3,000,000)"}],[{"text":"(3,000,000)"}]],[[{"text":"Less fixed administration and selling"}],[{"text":"(1,000,000)"}],[{"text":"(1,000,000)"}]],[[{"text":"Net profit","bold":true}],[{"text":"400,000","bold":true}],[{"text":"1,775,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Check: contribution per pair sold = ₦5,000 − ₦2,000 − ₦250 = ₦2,750; 1,600 × ₦2,750 = ₦4,400,000 and 2,100 × ₦2,750 = ₦5,775,000."}]},{"type":"paragraph","text":[{"text":"Absorption costing profit statement","bold":true}]},{"type":"table","header":[[],[{"text":"Month 1 ₦"}],[{"text":"Month 2 ₦"}]],"rows":[[[{"text":"Sales"}],[{"text":"8,000,000"}],[{"text":"10,500,000"}]],[[{"text":"Opening stock (× ₦3,500)"}],[{"text":"0"}],[{"text":"1,400,000"}]],[[{"text":"Add production cost (2,000 / 1,800 × ₦3,500)"}],[{"text":"7,000,000"}],[{"text":"6,300,000"}]],[[{"text":"Less closing stock (400 / 100 × ₦3,500)"}],[{"text":"(1,400,000)"}],[{"text":"(350,000)"}]],[[{"text":"Cost of sales at full cost"}],[{"text":"5,600,000"}],[{"text":"7,350,000"}]],[[{"text":"Add under-absorbed fixed overhead"}],[{"text":"0"}],[{"text":"300,000"}]],[[{"text":"Adjusted cost of sales"}],[{"text":"(5,600,000)"}],[{"text":"(7,650,000)"}]],[[{"text":"Gross profit","bold":true}],[{"text":"2,400,000"}],[{"text":"2,850,000"}]],[[{"text":"Less variable selling cost"}],[{"text":"(400,000)"}],[{"text":"(525,000)"}]],[[{"text":"Less fixed administration and selling"}],[{"text":"(1,000,000)"}],[{"text":"(1,000,000)"}]],[[{"text":"Net profit","bold":true}],[{"text":"1,000,000","bold":true}],[{"text":"1,325,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Notice: in Month 1, production exceeded sales and absorption profit was higher. In Month 2, sales exceeded production (stock fell) and marginal profit was higher. Over the two months together, marginal profit = ₦2,175,000 and absorption profit = ₦2,325,000; the gap of ₦150,000 is the fixed overhead in the 100 pairs still in stock (100 × ₦1,500)."}]},{"type":"paragraph","text":[{"text":"Traps: under absorption costing, do "},{"text":"not","bold":true},{"text":" deduct fixed production overhead again below gross profit; it is already in cost of sales through the OAR, corrected by the under/over-absorption line. Under marginal costing, deduct the "},{"text":"actual","bold":true},{"text":" fixed production overhead incurred, not the amount absorbed."}]}]},{"number":"8.5","title":"Reconciling marginal and absorption profits","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Difference in profit = Change in stock units × Fixed production OAR per unit.","bold":true}]},{"text":[{"text":"Equivalently: Difference = (Closing stock units − Opening stock units) × OAR."}]},{"text":[{"text":"Rules:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Stock increases","bold":true},{"text":" (production > sales): "},{"text":"absorption profit is higher","bold":true},{"text":", because some of the period's fixed overhead is carried forward in closing stock."}]},{"text":[{"text":"Stock decreases","bold":true},{"text":" (sales > production): "},{"text":"marginal profit is higher","bold":true},{"text":", because absorption costing releases fixed overhead from earlier periods through opening stock."}]},{"text":[{"text":"No change in stock","bold":true},{"text":" (production = sales): "},{"text":"both profits are the same","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Over the long run (when all stock is sold), total profits under both techniques are equal; the difference is only a matter of "},{"text":"timing","bold":true},{"text":"."}]},{"text":[{"text":"Reconciliation statement:","bold":true},{"text":" Marginal costing profit + (increase in stock × OAR) or − (decrease in stock × OAR) = Absorption costing profit."}]},{"text":[{"text":"If OAR changes between periods, use the fixed overhead "},{"text":"in each stock figure","bold":true},{"text":": Difference = Fixed overhead in closing stock − Fixed overhead in opening stock."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 5: reconciling the Aba shoe factory profits.","bold":true}]},{"type":"table","header":[[],[{"text":"Month 1 ₦"}],[{"text":"Month 2 ₦"}]],"rows":[[[{"text":"Marginal costing profit"}],[{"text":"400,000"}],[{"text":"1,775,000"}]],[[{"text":"Add fixed overhead in closing stock (400 / 100 × ₦1,500)"}],[{"text":"600,000"}],[{"text":"150,000"}]],[[{"text":"Less fixed overhead in opening stock (0 / 400 × ₦1,500)"}],[{"text":"0"}],[{"text":"(600,000)"}]],[[{"text":"Absorption costing profit","bold":true}],[{"text":"1,000,000","bold":true}],[{"text":"1,325,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Short method: Month 1 stock rose by 400 pairs: 400 × ₦1,500 = ₦600,000, absorption higher. Month 2 stock fell by 300 pairs: 300 × ₦1,500 = ₦450,000, marginal higher (₦1,775,000 − ₦1,325,000 = ₦450,000)."}]},{"type":"paragraph","text":[{"text":"Why it happens, in plain words: in Month 1, the shoe factory spent ₦3,000,000 on fixed production overhead. Marginal costing charged all of it to Month 1. Absorption costing charged only the share in the 1,600 pairs sold and parked ₦600,000 in the 400 pairs on the shelf, to be charged in Month 2 when those pairs were sold."}]},{"type":"paragraph","text":[{"text":"Exam traps:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Use the "},{"text":"fixed production","bold":true},{"text":" OAR only; never include variable cost, selling or administration costs in the rec$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 36, $study_guide$onciliation."}]},{"text":[{"text":"Use the change in stock "},{"text":"units","bold":true},{"text":", not the units produced or sold."}]},{"text":[{"text":"The under-absorbed ₦300,000 in Month 2 is "},{"text":"not","bold":true},{"text":" part of the reconciliation figure; it appears in the absorption statement only, and the reconciliation still works on stock change alone."}]},{"text":[{"text":"A manager judged on absorption profit can raise reported profit by over-producing to build stock. This is a key argument for marginal costing in internal reporting."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marginal cost = variable cost of one unit, avoided if that unit is not produced."}]},{"text":[{"text":"Marginal costing (variable or direct costing) charges only variable costs to products; fixed costs are period costs."}]},{"text":[{"text":"Absorption costing (full costing) charges all production costs, fixed and variable, to products."}]},{"text":[{"text":"Contribution = Sales − Variable cost of sales = Fixed cost + Profit; contribution per unit = Selling price − Variable cost per unit."}]},{"text":[{"text":"Profit under marginal costing = Total contribution − Fixed costs."}]},{"text":[{"text":"Stock: marginal at variable production cost; absorption at full production cost. Difference = units × fixed OAR."}]},{"text":[{"text":"OAR = Budgeted fixed production overhead ÷ Normal output; under-absorption adds to cost of sales, over-absorption reduces it."}]},{"text":[{"text":"Profit difference = Change in stock units × OAR: stock up, absorption higher; stock down, marginal higher; no change, equal."}]},{"text":[{"text":"Absorption costing is required for financial reporting (IAS 2); marginal costing is better for decisions."}]}]}],"theory":{"itemId":"6f27d246-6c14-5b9f-a8b6-1b5f761d8f33","question":[{"type":"paragraph","text":[{"text":"A Lagos bakery makes a cake that sells for ₦200. Variable production cost is ₦120 a cake. Fixed production overhead is ₦400,000 a month, absorbed on a normal output of 10,000 cakes. Fixed administration cost is ₦200,000 a month. In the month, 10,000 cakes were produced and 8,000 sold, with no opening stock. Calculate (a) closing stock under each technique, (b) profit under each technique and (c) reconcile the two profits."}]}]}}},{"kind":"note","itemId":"09aaafca-5e2d-5c91-8d7a-330c8c17a941","sourceKey":"guide-topic:9","position":9,"payload":{"title":"Break-even (Cost-Volume-Profit) Analysis","body":"The concept of CVP and break-even; contribution and the C/S (P/V) ratio; break-even point in units and naira; margin of safety; target profit, with and without tax; effect of changes in price and cost; degree of operating leverage; break-even, contribution and profit-volume charts; importance, assumptions and limitations; decision problems (make or buy, indifference point, limiting factor, special orders).","noteType":"guide_topic","number":9,"mustKnow":[{"text":"The concept of CVP and break-even; contribution and the C/S (P/V) ratio; break-even point in units and naira; margin of safety; target profit, with and without tax; effect of changes in price and cost; degree of operating leverage; break-even, contribution and profit-volume charts; importance, assumptions and limitations; decision problems (make or buy, indifference point, limiting factor, special orders)."}],"lessons":[{"number":"9.1","title":"The concept, contribution and the C/S (P/V) ratio","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost-volume-profit (CVP) analysis:","bold":true},{"text":" the study of how changes in cost, selling price and volume of activity affect profit. It rests on the split of costs into fixed and variable (marginal costing)."}]},{"text":[{"text":"Break-even analysis:","bold":true},{"text":" a technique which uses cost behaviour to identify the activity level at which there is "},{"text":"neither profit nor loss","bold":true},{"text":". It is the best-known part of CVP analysis."}]},{"text":[{"text":"Break-even point (BEP):","bold":true},{"text":" the level of activity at which "},{"text":"total revenue equals total cost","bold":true},{"text":". At BEP, profit = 0 and "},{"text":"contribution = fixed cost","bold":true},{"text":"."}]},{"text":[{"text":"Contribution:","bold":true},{"text":" sales minus variable cost. It first \"contributes\" to covering fixed costs; whatever is left is profit."}]}]},{"type":"paragraph","text":[{"text":"Key formulas:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Contribution per unit = Selling price per unit − Variable cost per unit"}]},{"text":[{"text":"Total contribution = Sales − Total variable cost = Fixed cost + Profit"}]},{"text":[{"text":"Profit = Total contribution − Fixed cost"}]},{"text":[{"text":"Sales = Variable cost + Fixed cost + Profit = Variable cost + Contribution"}]},{"text":[{"text":"C/S ratio","bold":true},{"text":" (contribution to sales ratio, also called "},{"text":"P/V ratio","bold":true},{"text":", profit-volume ratio, or contribution margin ratio) = Contribution ÷ Sales (per unit or in total; × 100 for a percentage)"}]},{"text":[{"text":"P/V ratio from two periods = Change in profit ÷ Change in sales"}]},{"text":[{"text":"Fixed cost = (Sales × C/S ratio) − Profit"}]}]},{"type":"paragraph","text":[{"text":"What changes the P/V ratio:"}]},{"type":"table","header":[[{"text":"Change"}],[{"text":"Effect on P/V ratio"}],[{"text":"Effect on BEP"}]],"rows":[[[{"text":"Selling price rises"}],[{"text":"Rises"}],[{"text":"Falls"}]],[[{"text":"Selling price falls"}],[{"text":"Falls"}],[{"text":"Rises"}]],[[{"text":"Variable cost per unit falls"}],[{"text":"Rises"}],[{"text":"Falls"}]],[[{"text":"Variable cost per unit rises"}],[{"text":"Falls"}],[{"text":"Rises"}]],[[{"text":"Fixed cost rises or falls"}],[{"text":"No effect","bold":true}],[{"text":"Rises / falls"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (contribution and C/S ratio$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 37, $study_guide$).","bold":true},{"text":" An Aba shoe factory sells a pair of shoes for ₦5,000. Variable cost is ₦3,000 a pair. Fixed costs are ₦1,200,000 a month and 900 pairs are sold."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Contribution per pair = ₦5,000 − ₦3,000 = "},{"text":"₦2,000","bold":true},{"text":"."}]},{"text":[{"text":"C/S ratio = ₦2,000 ÷ ₦5,000 = "},{"text":"0.40 (40%)","bold":true},{"text":". Every ₦1 of sales brings 40 kobo of contribution."}]},{"text":[{"text":"Total contribution = 900 × ₦2,000 = ₦1,800,000."}]},{"text":[{"text":"Profit = ₦1,800,000 − ₦1,200,000 = "},{"text":"₦600,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Trap:","italic":true},{"text":" if a question also gives \"fixed cost per unit\", ignore it when working out contribution and the C/S ratio. Contribution uses only selling price and variable cost. For example, price ₦4.50, variable cost ₦2.50, fixed cost ₦5 a unit: contribution = ₦2.00 and C/S ratio = 2 ÷ 4.5 = 0.44 (to 2 decimal places). The ₦5 does not enter either figure."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (rearranging the contribution equation).","bold":true},{"text":" A firm earns a profit of ₦45,000. Total contribution is ₦120,000 and variable cost is ₦180,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Fixed cost = Contribution − Profit = ₦120,000 − ₦45,000 = "},{"text":"₦75,000","bold":true},{"text":"."}]},{"text":[{"text":"Sales = Variable cost + Contribution = ₦180,000 + ₦120,000 = "},{"text":"₦300,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Trap:","italic":true},{"text":" the options often include Contribution + Profit or Variable cost + Profit. Stick to the two equations above."}]},{"type":"paragraph","text":[{"text":"Worked example 3 (P/V ratio from two periods, including a loss).","bold":true},{"text":" A Lagos printing firm reports: March sales ₦1,000,000, loss ₦200,000; April sales ₦3,000,000, profit ₦600,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Change in sales = ₦3,000,000 − ₦1,000,000 = ₦2,000,000."}]},{"text":[{"text":"Change in profit = ₦600,000 − (−₦200,000) = ₦800,000. A loss is a negative profit, so moving from a loss to a profit "},{"text":"adds","bold":true},{"text":" the two figures."}]},{"text":[{"text":"P/V ratio = ₦800,000 ÷ ₦2,000,000 = "},{"text":"40%","bold":true},{"text":"."}]},{"text":[{"text":"Fixed cost = (₦3,000,000 × 40%) − ₦600,000 = ₦1,200,000 − ₦600,000 = "},{"text":"₦600,000","bold":true},{"text":"."}]},{"text":[{"text":"Check with March: ₦1,000,000 × 40% = ₦400,000 contribution; ₦400,000 − ₦600,000 = −₦200,000 loss. Correct."}]}]},{"type":"paragraph","text":[{"text":"This works because fixed cost is the same in both periods, so any change in profit is a change in contribution. The same idea answers: \"Sales rise from ₦40,000 to ₦60,000 and profit rises by ₦5,000\": P/V = ₦5,000 ÷ ₦20,000 = 25%."}]}]},{"number":"9.2","title":"Break-even point and margin of safety","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"BEP (units) = Fixed cost ÷ Contribution per unit"}]},{"text":[{"text":"BEP (₦ sales) = Fixed cost ÷ C/S ratio = BEP units × Selling price"}]},{"text":[{"text":"Margin of safety (MOS):","bold":true},{"text":" the difference between actual (or budgeted) sales and break-even sales. It shows how far sales can fall before a loss is made."}]},{"text":[{"text":"MOS (units) = Actual or budgeted units − BEP units"}]},{"text":[{"text":"MOS (₦) = Actual or budgeted sales − BEP sales"}]},{"text":[{"text":"MOS % = MOS ÷ Actual or budgeted sales × 100"}]},{"text":[{"text":"Profit = MOS (₦) × C/S ratio = MOS (units) × Contribution per unit"}]},{"text":[{"text":"Working backwards:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Fixed cost = BEP units × Contribution per unit = BEP sales × C/S ratio"}]},{"text":[{"text":"BEP sales = Actual sales × (1 − MOS %)"}]},{"text":[{"text":"BEP units = BEP sales ÷ Selling price"}]}]}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 4 (BEP and MOS).","bold":true},{"text":" A Kano flour mill sells a bag of flour for ₦40,000. Variable cost is ₦28,000 a bag. Fixed costs are ₦18,000,000 a year. Budgeted sales are 2,000 bags."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Contribution = ₦40,000 − ₦28,000 = ₦12,000; C/S ratio = 12,000 ÷ 40,000 = 30%."}]},{"text":[{"text":"BEP units = ₦18,000,000 ÷ ₦12,000 = "},{"text":"1,500 bags","bold":true},{"text":"."}]},{"text":[{"text":"BEP sales = ₦18,000,000 ÷ 0.30 = "},{"text":"₦60,000,000","bold":true},{"text":" (check: 1,500 × ₦40,000 = ₦60,000,000)."}]},{"text":[{"text":"MOS = 2,000 − 1,500 = "},{"text":"500 bags","bold":true},{"text":", or 500 × ₦40,000 = "},{"text":"₦20,000,000","bold":true},{"text":"."}]},{"text":[{"text":"MOS % = 500 ÷ 2,000 = "},{"text":"25%","bold":true},{"text":"."}]},{"text":[{"text":"Profit = ₦20,000,000 × 30% = ₦6,000,000 (check: 2,000 × ₦12,000 − ₦18,000,000 = ₦6,000,000)."}]}]},{"type":"paragraph","text":[{"text":"When you are given total sales and total variable cost instead of unit figures, find the C/S ratio from the totals. Example: expected sales ₦600,000, variable costs ₦300,000, fixed costs ₦177,500. C/S = (600,000 − 300,000) ÷ 600,000 = 50%; BEP sales = ₦177,500 ÷ 0.5 = "},{"text":"₦355,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 5 (fixed cost given per unit).","bold":true},{"text":" A Port Harcourt paint maker sells a tin for ₦800. Variable production cost is ₦300 and variable selling cost ₦100 a tin. Fixed production cost is ₦150 a tin and fixed selling cost ₦50 a tin, based on budgeted output of 20,000 tins."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Variable cost = ₦300 + ₦100 = ₦400; contribution = ₦800 − ₦400 = ₦400. Variable "},{"text":"selling","bold":true},{"text":" cost is$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 38, $study_guide$ still variable: include it."}]},{"text":[{"text":"Total fixed cost = (₦150 + ₦50) × 20,000 = "},{"text":"₦4,000,000","bold":true},{"text":". Fixed cost per unit is only an average at the budgeted output; turn it into a total first."}]},{"text":[{"text":"BEP = ₦4,000,000 ÷ ₦400 = "},{"text":"10,000 tins","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Trap:","italic":true},{"text":" never deduct fixed cost per unit from price to get \"contribution\". That gives profit per unit at one output only."}]},{"type":"paragraph","text":[{"text":"Worked example 6 (working backwards).","bold":true},{"text":" A firm sells at ₦50 a unit with a C/S ratio of 40%. Weekly break-even sales are ₦45,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"BEP units = ₦45,000 ÷ ₦50 = 900 units."}]},{"text":[{"text":"Contribution per unit = 40% × ₦50 = ₦20."}]},{"text":[{"text":"Fixed cost = ₦45,000 × 40% = ₦18,000 (or 900 × ₦20)."}]},{"text":[{"text":"Profit when 1,500 units are sold = 1,500 × ₦20 − ₦18,000 = ₦12,000 (or MOS 600 units × ₦20)."}]}]},{"type":"paragraph","text":[{"text":"Other backward routes: if BEP is 6,000 units, price ₦90 and variable cost ₦40, then fixed cost = 6,000 × ₦50 = ₦300,000. If sales are ₦5,000,000 and MOS is 30%, BEP sales = ₦5,000,000 × 70% = ₦3,500,000; with a C/S ratio of 40%, profit = ₦1,500,000 × 40% = ₦600,000."}]},{"type":"paragraph","text":[{"text":"Rounding:","italic":true},{"text":" when BEP is not a whole number (e.g. 10,909.09), exam options normally round to the nearest unit (10,909). Strictly, the firm must sell the next whole unit to avoid any loss, so state your rounding."}]}]},{"number":"9.3","title":"Target profit, tax, changes in price and cost, operating leverage","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Units for target profit = (Fixed cost + Target profit) ÷ Contribution per unit"}]},{"text":[{"text":"Sales (₦) for target profit = (Fixed cost + Target profit) ÷ C/S ratio"}]},{"text":[{"text":"Effect of tax:","bold":true},{"text":" CVP formulas need profit "},{"text":"before","bold":true},{"text":" tax. Required profit before tax = Profit after tax ÷ (1 − tax rate). Then units = (Fixed cost + Profit before tax) ÷ Contribution per unit."}]},{"text":[{"text":"Changes in price or cost:","bold":true},{"text":" recompute the new contribution per unit and the new fixed cost, then apply the formulas again. To keep the same profit: new units = (New fixed cost + Original profit) ÷ New contribution per unit."}]},{"text":[{"text":"% change in volume = (New units − Original units) ÷ Original units × 100"}]},{"text":[{"text":"Degree of operating leverage (DOL)","bold":true},{"text":" = Contribution ÷ Operating profit (profit before interest and tax). It also equals 1 ÷ MOS % (as a decimal). A DOL of 2.5 means a 10% rise in sales gives a 25% rise in profit."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 7 (target profit and tax).","bold":true},{"text":" An Ibadan furniture maker sells a chair for ₦60,000. Variable cost is ₦36,000 a chair; fixed costs are ₦4,800,000 a year. Tax rate is 30%."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Contribution = ₦24,000; C/S ratio = 24,000 ÷ 60,000 = 40%."}]},{"text":[{"text":"BEP = ₦4,800,000 ÷ ₦24,000 = 200 chairs."}]},{"text":[{"text":"Target profit ₦2,400,000 (before tax): units = (₦4,800,000 + ₦2,400,000) ÷ ₦24,000 = ₦7,200,000 ÷ ₦24,000 = "},{"text":"300 chairs","bold":true},{"text":"."}]},{"text":[{"text":"Target profit "},{"text":"after tax","bold":true},{"text":" ₦2,100,000: profit before tax = ₦2,100,000 ÷ (1 − 0.30) = ₦3,000,000."}]},{"text":[{"text":"Units = (₦4,800,000 + ₦3,000,000) ÷ ₦24,000 = "},{"text":"325 chairs","bold":true},{"text":"; sales value = ₦7,800,000 ÷ 0.40 = ₦19,500,000 (check: 325 × ₦60,000)."}]}]},{"type":"paragraph","text":[{"text":"Trap:","italic":true},{"text":" dividing ₦2,100,000 by ₦24,000 directly, or multiplying by 1.3 instead of dividing by 0.7, gives a wrong option. ₦2,100,000 × 1.3 = ₦2,730,000, not ₦3,000,000."}]},{"type":"paragraph","text":[{"text":"When the variable cost is given as a list (materials, labour, variable overheads, direct expenses), add them all to get variable cost per unit first. Example: price ₦130; materials ₦22, labour ₦15, variable overheads ₦3, direct expenses ₦10 = ₦50; contribution ₦80; fixed cost ₦1,600,000; target ₦250,000: units = ₦1,850,000 ÷ ₦80 = 23,125."}]},{"type":"paragraph","text":[{"text":"Worked example 8 (changes in price and cost).","bold":true},{"text":" An Abeokuta soap maker sells at ₦500 a carton, variable cost ₦300, fixed cost ₦120 a carton based on budgeted sales of 10,000 cartons."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Original: fixed cost = ₦120 × 10,000 = ₦1,200,000; contribution = ₦200; profit = 10,000 × ₦200 − ₦1,200,000 = ₦800,000. BEP = ₦1,200,000 ÷ ₦200 = 6,000 cartons."}]},{"text":[{"text":"Price rises 10% to ₦550; variable cost rises 5% to ₦315. New contribution = ₦235."}]},{"text":[{"text":"Units to keep profit at ₦800,000 = (₦1,200,000 + ₦800,000) ÷ ₦235 = 8,510.6, about 8,511 cartons."}]},{"text":[{"text":"Change in volume = (8,510.6 − 10,000) ÷ 10,000 = "},{"text":"14.9% decrease","bold":true},{"text":" (to 1 decimal place)."}]},{"text":[{"text":"If fixed cost also rises 20% to ₦1,440,000, new BEP = ₦1,440,000 ÷ ₦235 = 6,127.7, about "},{"text":"6,128 cartons","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Trap:","italic":true},{"text":" apply each percentage only to the item named. A 10% rise in \"variable production cost\" leaves variable selling cost unchanged; a 25% rise in \"fixed production cost\" leaves fixed selling cost unchanged."}]},{"type":"paragraph","text":[{"text":"Worked example 9 (DOL).","bold":true},{"text":" In the original budget of example 8: contribution ₦2,000,000, profit ₦800,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 39, $study_guide${"text":"DOL = ₦2,000,000 ÷ ₦800,000 = "},{"text":"2.5","bold":true},{"text":"."}]},{"text":[{"text":"Check: MOS = (10,000 − 6,000) ÷ 10,000 = 40%; 1 ÷ 0.4 = 2.5."}]},{"text":[{"text":"A 10% rise in volume raises profit by 2.5 × 10% = 25% (₦800,000 to ₦1,000,000). High fixed costs mean high operating leverage and higher risk."}]}]}]},{"number":"9.4","title":"Break-even charts, P/V charts, importance, assumptions and limitations","mustKnow":[{"type":"paragraph","text":[{"text":"Break-even chart (single product):","bold":true},{"text":" a graph showing costs and revenue at different activity levels."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Horizontal axis: activity (units or sales value). Vertical axis: costs and revenue (₦)."}]},{"text":[{"text":"Fixed cost line:","bold":true},{"text":" horizontal, at the level of fixed cost."}]},{"text":[{"text":"Total cost line:","bold":true},{"text":" starts at the fixed cost on the vertical axis and rises with variable cost."}]},{"text":[{"text":"Total revenue (sales) line:","bold":true},{"text":" starts at the origin (zero sales, zero revenue)."}]},{"text":[{"text":"BEP:","bold":true},{"text":" where the revenue line crosses the total cost line. Area to the left = loss; to the right = profit."}]},{"text":[{"text":"Margin of safety:","bold":true},{"text":" the distance on the horizontal axis between BEP and budgeted activity."}]},{"text":[{"text":"Angle of incidence:","bold":true},{"text":" the angle at which the revenue line cuts the total cost line. A wide angle means profit grows fast once BEP is passed."}]}]},{"type":"paragraph","text":[{"text":"Contribution chart:","bold":true},{"text":" like the break-even chart, but the "},{"text":"variable cost line","bold":true},{"text":" is drawn from the origin and fixed cost is added on top, so contribution shows as the gap between revenue and variable cost."}]},{"type":"paragraph","text":[{"text":"Profit-volume (P/V) chart:","bold":true},{"text":" horizontal axis = sales or units; vertical axis = profit (above) and loss (below). One line starts at "},{"text":"−fixed cost","bold":true},{"text":" at zero sales and rises; it crosses the horizontal axis at BEP. The slope of the line is the P/V ratio."}]},{"type":"paragraph","text":[{"text":"Importance (uses) of CVP analysis:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Finds the break-even point and the margin of safety."}]},{"text":[{"text":"Shows the sales needed to earn a target profit."}]},{"text":[{"text":"Shows the effect on profit of changes in price, costs and volume."}]},{"text":[{"text":"Helps pricing decisions and setting selling prices in a downturn."}]},{"text":[{"text":"Helps decisions such as make or buy, special orders, product mix and choosing between production methods."}]},{"text":[{"text":"Helps budgeting and profit planning."}]},{"text":[{"text":"Presents cost and profit relationships simply to managers."}]}]},{"type":"paragraph","text":[{"text":"Assumptions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"All costs can be split into fixed and variable."}]},{"text":[{"text":"Fixed costs stay constant in total over the relevant range."}]},{"text":[{"text":"Variable cost per unit is constant (total variable cost is linear)."}]},{"text":[{"text":"Selling price per unit is constant at all volumes."}]},{"text":[{"text":"Single product, or a constant sales mix."}]},{"text":[{"text":"Production equals sales (no change in stock)."}]},{"text":[{"text":"Efficiency and productivity do not change."}]},{"text":[{"text":"Volume is the only factor that affects costs and revenue."}]}]},{"type":"paragraph","text":[{"text":"Limitations:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Costs are hard to split exactly into fixed and variable; semi-variable costs exist."}]},{"text":[{"text":"Fixed costs may step up at higher output."}]},{"text":[{"text":"Selling price often has to fall to sell more (discounts), so revenue is not a straight line."}]},{"text":[{"text":"Variable cost per unit changes (bulk-buying discounts, overtime)."}]},{"text":[{"text":"Most firms sell several products and the mix changes."}]},{"text":[{"text":"Stock levels change, so production differs from sales."}]},{"text":[{"text":"It is valid only within the relevant range and is short-term."}]},{"text":[{"text":"It ignores other factors such as inflation, technology and capital employed."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 10 (reading a chart).","bold":true},{"text":" For the Kano flour mill in example 4, plot fixed cost at ₦18,000,000 (horizontal line). Total cost starts at ₦18m and at 2,000 bags reaches ₦18m + 2,000 × ₦28,000 = ₦74m. Revenue starts at zero and at 2,000 bags reaches ₦80m. The two lines cross at 1,500 bags (₦60m): the BEP. The gap from 1,500 to 2,000 bags is the MOS. On a P/V chart, the line starts at −₦18m and reaches +₦6m at ₦80m of sales, crossing zero at ₦60m."}]},{"type":"paragraph","text":[{"text":"Traps:","italic":true},{"text":" the revenue line, not the total cost line, starts at the origin. On a P/V chart, the line starts at minus fixed cost, not at zero. A change in fixed cost moves the P/V line up or down without changing its slope; a change in price or variable cost changes the slope."}]}]},{"number":"9.5","title":"Decision-making problems","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basic rule:","bold":true},{"text":" in short-term decisions, compare "},{"text":"contribution","bold":true},{"text":" (or relevant variable cost). Fixed costs that do not change because of the decision are irrelevant."}]},{"text":[{"text":"Make or buy:","bold":true},{"text":" if fixed costs continue either way and there is spare capacity, buying is profitable only when the supplier's price is "},{"text":"lower than the variable (marginal) cost","bold":true},{"text":" of making. C$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 40, $study_guide$ompare with variable cost, not total cost including apportioned fixed overheads."}]},{"text":[{"text":"Indifference (cost) point:","bold":true},{"text":" the activity level at which two options cost the same."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Indifference point = Difference in fixed costs ÷ Difference in variable cost per unit"}]},{"text":[{"text":"Below it, choose the option with lower fixed cost; above it, the one with lower variable cost."}]}]}]},{"text":[{"text":"Limiting (key) factor:","bold":true},{"text":" a scarce resource (labour hours, machine hours, materials) that limits output. Rank products by "},{"text":"contribution per unit of the limiting factor","bold":true},{"text":" and make the best first."}]},{"text":[{"text":"Special order:","bold":true},{"text":" accept if price is above variable cost, there is spare capacity, and regular sales and prices are not affected."}]},{"text":[{"text":"Dropping a product or closing a department:","bold":true},{"text":" keep it while it earns a positive contribution, unless its fixed costs would be saved by closing."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 11 (make or buy).","bold":true},{"text":" An Onitsha factory makes a component: materials ₦900, labour ₦600, variable overhead ₦300, so variable cost ₦1,800. Fixed overhead absorbed is ₦700, giving total cost ₦2,500. A supplier offers ₦2,100. Fixed overhead will not change."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Relevant comparison: variable cost ₦1,800 against buying price ₦2,100."}]},{"text":[{"text":"Making saves ₦2,100 − ₦1,800 = ₦300 a unit. "},{"text":"Make.","bold":true}]},{"text":[{"text":"Trap:","italic":true},{"text":" comparing ₦2,100 with ₦2,500 wrongly suggests buying. The ₦700 is paid either way."}]}]},{"type":"paragraph","text":[{"text":"Worked example 12 (indifference point).","bold":true},{"text":" A Lagos restaurant can buy rice packs from Supplier X at ₦3.50 a unit, or from Supplier Y at ₦3.20 a unit plus a fixed charge of ₦9,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Difference in fixed cost = ₦9,000 − 0 = ₦9,000."}]},{"text":[{"text":"Difference in variable cost = ₦3.50 − ₦3.20 = ₦0.30."}]},{"text":[{"text":"Indifference point = ₦9,000 ÷ ₦0.30 = "},{"text":"30,000 units","bold":true},{"text":". Below 30,000 units choose X; above, choose Y."}]}]},{"type":"paragraph","text":[{"text":"The same formula chooses between production methods. Method A: fixed ₦2,000,000, variable ₦400; Method B: fixed ₦3,500,000, variable ₦250. Point = ₦1,500,000 ÷ ₦150 = 10,000 units (both cost ₦6,000,000 there)."}]},{"type":"paragraph","text":[{"text":"Worked example 13 (limiting factor).","bold":true},{"text":" A firm has 10,000 labour hours. Product A: contribution ₦600, 2 hours, demand 3,000 units. Product B: contribution ₦900, 4 hours, demand 2,000 units."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Contribution per hour: A = ₦600 ÷ 2 = ₦300; B = ₦900 ÷ 4 = ₦225. Rank A first, even though B has the higher contribution per unit."}]},{"text":[{"text":"Make 3,000 A using 6,000 hours. Remaining 4,000 hours ÷ 4 = 1,000 B."}]},{"text":[{"text":"Total contribution = 3,000 × ₦600 + 1,000 × ₦900 = "},{"text":"₦2,700,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 14 (special order).","bold":true},{"text":" A Lagos bakery with spare capacity is offered an order for 2,000 loaves at ₦700. Variable cost is ₦550 and full cost (with fixed overhead) is ₦850. Extra contribution = 2,000 × (₦700 − ₦550) = "},{"text":"₦300,000","bold":true},{"text":", so accept, as long as regular customers do not demand the lower price."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Break-even analysis uses cost behaviour to find the activity level with neither profit nor loss; at BEP, total revenue = total cost and contribution = fixed cost."}]},{"text":[{"text":"Contribution = Sales − Variable cost = Fixed cost + Profit; ignore fixed cost per unit when finding contribution."}]},{"text":[{"text":"C/S (P/V) ratio = Contribution ÷ Sales = Change in profit ÷ Change in sales; it rises if price rises or variable cost falls; fixed cost does not affect it."}]},{"text":[{"text":"BEP units = Fixed cost ÷ Contribution per unit; BEP ₦ = Fixed cost ÷ C/S ratio."}]},{"text":[{"text":"Margin of safety = Actual sales − BEP sales; Profit = MOS × C/S ratio."}]},{"text":[{"text":"Target units = (Fixed cost + Target profit) ÷ Contribution per unit; after-tax target ÷ (1 − tax rate) first."}]},{"text":[{"text":"DOL = Contribution ÷ Operating profit = 1 ÷ MOS %."}]},{"text":[{"text":"Charts: revenue line from origin, total cost from fixed cost; P/V line from −fixed cost, slope = P/V ratio."}]},{"text":[{"text":"Decisions: buy only if price < variable cost of making; indifference point = ΔFixed ÷ ΔVariable; rank by contribution per unit of limiting factor."}]}]}],"theory":{"itemId":"58f639c7-516b-5240-9185-7ba2cff7d48c","question":[{"type":"paragraph","text":[{"text":"An Ilorin water factory sells a pack of bottled water for ₦1,500. Variable cost is ₦900 a pack and fixed costs are ₦3,600,000 a month. Budgeted sales are 9,000 packs a month. The tax rate is 30%. Calculate (a) the C/S ratio, (b) the break-even point in packs and naira, (c) the margin of safety in packs, naira and percentage, and (d) the packs needed to earn a profit after tax of ₦1,680,000."}]}]}}},{"kind":"note","itemId":"fd7ab283-a062-50c4-9824-8eada513ab82","sourceKey":"guide-topic:10","position":10,"payload":{"title":"Standard Costing","body":"What standard costing and a variance are; the four types of standards; how standards are set and recorded on a standard cost card; behavioural aspects; standard costing versus budgets; direct material variances (price, usage, cost) and direct labour variances (rate, idle time, efficiency, cost); when to investiga$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 41, $study_guide$te a variance; reconciling standard cost with actual cost.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"What standard costing and a variance are; the four types of standards; how standards are set and recorded on a standard cost card; behavioural aspects; standard costing versus budgets; direct material variances (price, usage, cost) and direct labour variances (rate, idle time, efficiency, cost); when to investigate a variance; reconciling standard cost with actual cost."}],"lessons":[{"number":"10.1","title":"Nature of standard costing and variances","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Standard cost:","bold":true},{"text":" a predetermined (planned) cost of one unit of product or service, worked out in advance from expected quantities and prices of materials, labour and overheads under stated working conditions."}]},{"text":[{"text":"Standard costing:","bold":true},{"text":" a control technique that uses predetermined standards for costs and revenues, compares them with actual results, and analyses the differences (variances) by cause so that management can act."}]},{"text":[{"text":"Variance:","bold":true},{"text":" the difference between a planned, budgeted or standard cost and the actual cost (and similarly for revenue)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Favourable (F):","bold":true},{"text":" actual cost is "},{"text":"less","bold":true},{"text":" than standard (or actual revenue more than standard). Raises profit."}]},{"text":[{"text":"Adverse (A):","bold":true},{"text":" actual cost is "},{"text":"more","bold":true},{"text":" than standard (or actual revenue less). Reduces profit."}]}]}]},{"text":[{"text":"Variance analysis:","bold":true},{"text":" breaking a total variance into its parts (for example price and usage) to find causes and responsibility."}]},{"text":[{"text":"Management by exception:","bold":true},{"text":" managers give attention only to significant variances (the exceptions); results that match standard need no action."}]},{"text":[{"text":"Standard hour:","bold":true},{"text":" the quantity of work that should be done in one hour at standard performance. Output is often measured in standard hours."}]}]},{"type":"paragraph","text":[{"text":"Steps in a standard costing system","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set standards for each element of cost per unit."}]},{"text":[{"text":"Record actual costs and actual output."}]},{"text":[{"text":"Compare actual cost with the standard cost of actual output."}]},{"text":[{"text":"Calculate and analyse variances by cause."}]},{"text":[{"text":"Report variances to the responsible managers."}]},{"text":[{"text":"Investigate significant variances and take corrective action (or revise the standard)."}]}]},{"type":"paragraph","text":[{"text":"Advantages of standard costing","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Provides a yardstick for measuring performance and efficiency."}]},{"text":[{"text":"Enables control through variance analysis and management by exception."}]},{"text":[{"text":"Fixes responsibility on named managers for named variances."}]},{"text":[{"text":"Simplifies stock valuation and bookkeeping (stock is held at standard cost)."}]},{"text":[{"text":"Helps in budgeting, pricing and quotations."}]},{"text":[{"text":"Makes staff cost-conscious and encourages efficiency."}]}]},{"type":"paragraph","text":[{"text":"Limitations of standard costing","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Setting standards is costly and time-consuming."}]},{"text":[{"text":"Standards go out of date quickly when prices change (for example under high inflation) and need regular revision."}]},{"text":[{"text":"Best suited to standardised, repetitive production; hard to use for one-off jobs."}]},{"text":[{"text":"Variances can be interdependent, so blame may fall on the wrong manager."}]},{"text":[{"text":"Unrealistic standards demotivate staff."}]},{"text":[{"text":"It focuses on cost and may ignore quality, delivery and customer satisfaction."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Standard costing uses predetermined standards for costs and revenues so that control is exercised through variance analysis. Do not confuse it with "},{"text":"marginal costing","bold":true},{"text":" (charges only variable costs to units), "},{"text":"job costing","bold":true},{"text":" (costs each customer order separately) or "},{"text":"historical costing","bold":true},{"text":" (records costs after they happen, with no target to compare against)."}]},{"text":[{"text":"A standard is a "},{"text":"unit","bold":true},{"text":" figure; a budget is a "},{"text":"total","bold":true},{"text":" figure. Standard cost per unit × budgeted output = budgeted cost."}]},{"text":[{"text":"Favourable does not always mean good. A favourable material price variance from buying cheap leather can cause an adverse usage variance through extra wastage (see Lesson 10.4)."}]}]}]},{"number":"10.2","title":"Types of standards, setting standards and the standard cost card","mustKnow":[{"type":"paragraph","text":[{"text":"Four types of standards","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ideal standard:","bold":true},{"text":" assumes perfect conditions: no wastage, no machine breakdown, no idle time, maximum efficiency. Almost never achieved; always gives adverse variances."}]},{"text":[{"text":"Attainable (expected) standard:","bold":true},{"text":" can be achieved under efficient operating conditions, with allowances for normal wastage, normal idle time and normal breakdowns. Most widely used; best for motivation and control."}]},{"text":[{"text":"Basic standard:","bold":true},{"text":" set once and left unaltered over a long period. Useful for showing trends over years; not useful for curre$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 42, $study_guide$nt control, because it becomes out of date."}]},{"text":[{"text":"Current standard:","bold":true},{"text":" based on current working conditions (current wastage, current efficiency, current prices). Set for a short period; realistic but may build current inefficiency into the target."}]}]},{"type":"table","header":[[{"text":"Standard"}],[{"text":"Achievable?"}],[{"text":"Effect on staff"}],[{"text":"Main use"}]],"rows":[[[{"text":"Ideal"}],[{"text":"Rarely"}],[{"text":"Demotivates, constant adverse variances"}],[{"text":"Shows the target of perfection"}]],[[{"text":"Attainable"}],[{"text":"Yes, with effort"}],[{"text":"Motivates best"}],[{"text":"Control, budgeting, stock valuation"}]],[[{"text":"Basic"}],[{"text":"Changes with time"}],[{"text":"Meaningless for control"}],[{"text":"Long-run trend analysis"}]],[[{"text":"Current"}],[{"text":"Yes"}],[{"text":"Little challenge if conditions are poor"}],[{"text":"Short-term control"}]]]},{"type":"paragraph","text":[{"text":"Setting standards (principles)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Material quantity:","bold":true},{"text":" from engineering or technical specifications of the product, with an allowance for normal loss (wastage, evaporation, scrap). Set by engineers and production staff."}]},{"text":[{"text":"Material price:","bold":true},{"text":" from the purchasing department, using expected market prices, quantity discounts, delivery costs and expected inflation for the period."}]},{"text":[{"text":"Labour time:","bold":true},{"text":" from work study (time and motion study) of each operation, with allowance for rest, fatigue and normal idle time. Expressed in standard hours."}]},{"text":[{"text":"Labour rate:","bold":true},{"text":" from the personnel (human resources) department, using agreed wage rates, union agreements and the grade of labour needed."}]},{"text":[{"text":"Overheads:","bold":true},{"text":" from overhead budgets: standard rate = budgeted overhead ÷ budgeted standard hours (or units)."}]}]},{"type":"paragraph","text":[{"text":"Generation of standard cost information:","bold":true},{"text":" standards are drawn from technical specifications, work study, purchasing records and price forecasts, personnel records and wage agreements, past cost records, and overhead budgets. A "},{"text":"standards committee","bold":true},{"text":" (production, purchasing, personnel, engineering and the cost accountant) usually agrees them. They are recorded on a standard cost card and reviewed regularly, at least yearly."}]},{"type":"paragraph","text":[{"text":"Standard cost card:","bold":true},{"text":" a document showing, for one unit, the standard quantity and standard price of each element of cost and the total standard cost. Format: element; quantity; price or rate; ₦ cost."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example: standard cost card.","bold":true},{"text":" An Aba shoe factory makes a standard leather sandal (\"Model A\")."}]},{"type":"table","header":[[{"text":"Element"}],[{"text":"Standard quantity"}],[{"text":"Standard price/rate"}],[{"text":"₦ per pair"}]],"rows":[[[{"text":"Direct material: leather"}],[{"text":"2 sq m"}],[{"text":"₦1,500 per sq m"}],[{"text":"3,000"}]],[[{"text":"Direct labour"}],[{"text":"3 hours"}],[{"text":"₦800 per hour"}],[{"text":"2,400"}]],[[{"text":"Standard prime cost","bold":true}],[],[],[{"text":"5,400","bold":true}]],[[{"text":"Variable production overhead"}],[{"text":"3 hours"}],[{"text":"₦200 per hour"}],[{"text":"600"}]],[[{"text":"Fixed production overhead"}],[{"text":"3 hours"}],[{"text":"₦400 per hour"}],[{"text":"1,200"}]],[[{"text":"Standard production cost","bold":true}],[],[],[{"text":"7,200","bold":true}]]]},{"type":"paragraph","text":[{"text":"Each line is quantity × price: 2 × ₦1,500 = ₦3,000; 3 × ₦800 = ₦2,400; 3 × ₦200 = ₦600; 3 × ₦400 = ₦1,200. Total = ₦3,000 + ₦2,400 + ₦600 + ₦1,200 = ₦7,200. This card is used in Lessons 10.4 to 10.6."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"If the 2 sq m includes a normal-loss allowance (say 1.8 sq m goes into the shoe and 0.2 sq m is normal off-cut), the standard is attainable. An ideal standard would allow only 1.8 sq m."}]},{"text":[{"text":"Traps:","bold":true},{"text":" \"unaltered over a long period\" = basic; \"perfect conditions\" = ideal; \"efficient conditions with allowances\" = attainable; \"present conditions, short period\" = current."}]}]}]},{"number":"10.3","title":"Behavioural aspects; standard costing and budgets","mustKnow":[{"type":"paragraph","text":[{"text":"Behavioural aspects of standard costing","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Participation:","bold":true},{"text":" staff who help set standards accept them more readily and are more motivated to achieve them."}]},{"text":[{"text":"Level of difficulty:","bold":true},{"text":" attainable standards motivate best; ideal standards discourage staff because they can never be met; loose standards give no challenge."}]},{"text":[{"text":"Slack:","bold":true},{"text":" managers asked to set their own standards may pad them (add slack) to look good."}]},{"text":[{"text":"Blame culture:","bold":true},{"text":" using variances to punish people breeds fear, hiding of information and manipulation of records. Variances should be used to help, not to blame."}]},{"text":[{"text":"Controllability:","bold":true},{"text":" managers should be judged only on variances they can control."}]},{"text":[{"text":"Interdependence:","bold":true},{"text":" one manager's action (cheap materials) can cause another's adverse variance (wastage, slow working), causing conflict."}]},{"text":[{"text":"Timely feedback:","bold":true},{"text":" variance reports must be prompt and clear to influence behaviour."}]}]},{"type":"paragraph","text":[{"text":"Standard costing and budgets","bold":true}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Standard costing"}],[{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 43, $study_guide$xt":"Budget"}]],"rows":[[[{"text":"Unit of expression"}],[{"text":"Per unit of product or operation"}],[{"text":"Totals for a department or the whole business"}]],[[{"text":"Scope"}],[{"text":"Mainly production costs"}],[{"text":"All functions: sales, production, cash, administration"}]],[[{"text":"Basis"}],[{"text":"Technical assessment of what cost should be"}],[{"text":"Plan of what is expected to happen"}]],[[{"text":"Use"}],[{"text":"Control and variance analysis, stock valuation"}],[{"text":"Planning, coordination and control"}]],[[{"text":"Can exist without the other?"}],[{"text":"Needs budgets to be fully useful"}],[{"text":"Budgets can exist without standards"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Link:","bold":true},{"text":" Budgeted cost = Standard cost per unit × Budgeted output. Standards are the building blocks of budgets; both are used for control by comparing actual with plan."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"If the factory budgets 1,200 pairs a month, budgeted direct material cost = 1,200 × ₦3,000 = ₦3,600,000. The standard (₦3,000 a pair) is the unit figure; the budget (₦3,600,000) is the total."}]},{"text":[{"text":"Flexing:","bold":true},{"text":" variances compare actual cost with the standard cost of "},{"text":"actual","bold":true},{"text":" output, not with the original budget. Comparing actual cost for 1,000 pairs with a budget for 1,200 pairs would mix up volume with efficiency."}]}]}]},{"number":"10.4","title":"Direct material variances","mustKnow":[{"type":"paragraph","text":[{"text":"Let SQ = standard quantity for actual output, AQ = actual quantity, SP = standard price, AP = actual price."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Material cost variance (total):","bold":true},{"text":" the difference between the standard material cost of the actual production and the actual cost of direct materials used."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Material cost variance = (SQ × SP) − (AQ × AP)"}]}]}]},{"text":[{"text":"Material price variance:","bold":true},{"text":" the part of the cost variance caused by paying a price different from standard."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Material price variance = (SP − AP) × AQ = (AQ × SP) − (AQ × AP)"}]}]}]},{"text":[{"text":"Material usage variance:","bold":true},{"text":" the part caused by using a quantity different from the standard for actual output."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Material usage variance = (SQ − AQ) × SP = (SQ × SP) − (AQ × SP)"}]}]}]},{"text":[{"text":"Check:","bold":true},{"text":" Material cost variance = Price variance + Usage variance."}]},{"text":[{"text":"SQ = Actual output × Standard quantity per unit."}]},{"text":[{"text":"A positive answer is favourable; a negative answer is adverse."}]},{"text":[{"text":"When several materials are mixed, the usage variance can be split further into a "},{"text":"mix variance","bold":true},{"text":" and a "},{"text":"yield variance","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Causes","bold":true}]},{"type":"table","header":[[{"text":"Variance"}],[{"text":"Adverse causes"}],[{"text":"Favourable causes"}]],"rows":[[[{"text":"Price"}],[{"text":"Market price rise, inflation, loss of trade discounts, emergency (rush) buying, buying higher quality, poor negotiation, higher transport cost"}],[{"text":"Bulk discounts, cheaper supplier, lower quality material, market price fall"}]],[[{"text":"Usage"}],[{"text":"Wastage, lower quality material, theft, poor workmanship, faulty machines, unskilled labour"}],[{"text":"Better quality material, more skilled workers, better supervision, less waste"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1.","bold":true},{"text":" The Aba factory (standard: 2 sq m at ₦1,500) made 1,000 pairs. It bought and used 2,100 sq m of leather at ₦1,450 per sq m."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"SQ = 1,000 × 2 = 2,000 sq m. Standard cost of actual output = 2,000 × ₦1,500 = ₦3,000,000."}]},{"text":[{"text":"Actual cost = 2,100 × ₦1,450 = ₦3,045,000."}]},{"text":[{"text":"Price variance = (₦1,500 − ₦1,450) × 2,100 = ₦50 × 2,100 = "},{"text":"₦105,000 F","bold":true},{"text":"."}]},{"text":[{"text":"Usage variance = (2,000 − 2,100) × ₦1,500 = −100 × ₦1,500 = "},{"text":"₦150,000 A","bold":true},{"text":"."}]},{"text":[{"text":"Cost variance = ₦3,000,000 − ₦3,045,000 = "},{"text":"₦45,000 A","bold":true},{"text":". Check: ₦105,000 F − ₦150,000 A = ₦45,000 A."}]}]},{"type":"paragraph","text":[{"text":"Interpretation: the buyer saved ₦50 a sq m by buying cheaper leather, but the cheaper leather tore more easily and 100 extra sq m were used. The two variances are interdependent: the purchasing manager's \"favourable\" variance caused the production manager's adverse one."}]},{"type":"paragraph","text":[{"text":"Worked example 2: price variance at purchase or at usage.","bold":true},{"text":" A Kano flour mill's standard price for wheat is ₦200 per kg. It bought 5,000 kg at ₦210 and used 4,600 kg."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"If stock is held at "},{"text":"standard","bold":true},{"text":" cost, the price variance is calculated on "},{"text":"quantity purchased","bold":true},{"text":": (₦200 − ₦210) × 5,000 = "},{"text":"₦50,000 A","bold":true},{"text":". This is the usual approach because the variance is reported as soon as the buying happens."}]},{"text":[{"text":"If the price variance is calculated on "},{"text":"quantity used","bold":true},{"text":": (₦200 − ₦210) × 4,600 = "},{"text":"₦46,000 A","bold":true},{"text":". The remaining ₦4,000 sits in closing stock of 400 kg."}]},{"text":[{"text":"The usage variance is always based on quantity "},{"text":"used","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 44, $study_guide$example 3: working backwards.","bold":true},{"text":" Standard price ₦90 per kg; standard quantity for actual output 10,000 kg; usage variance ₦36,000 F. Extra or saved quantity = ₦36,000 ÷ ₦90 = 400 kg saved, so AQ = 10,000 − 400 = "},{"text":"9,600 kg","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" price variance uses "},{"text":"actual","bold":true},{"text":" quantity; usage variance uses "},{"text":"standard","bold":true},{"text":" price. The \"standard cost of actual production\" uses SQ for actual output, never the budgeted output. The "},{"text":"cost","bold":true},{"text":" (total) variance compares standard cost of actual production with actual cost; the price and usage variances are its two parts."}]}]}]},{"number":"10.5","title":"Direct labour variances","mustKnow":[{"type":"paragraph","text":[{"text":"Let SH = standard hours for actual output, AH paid = actual hours paid, AH worked = actual hours worked, SR = standard rate, AR = actual rate."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Labour cost variance (total):","bold":true},{"text":" the difference between the standard labour cost of actual production and the actual labour cost."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Labour cost variance = (SH × SR) − (AH paid × AR)"}]}]}]},{"text":[{"text":"Labour rate variance:","bold":true},{"text":" caused by paying a wage rate different from standard."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Labour rate variance = (SR − AR) × AH paid"}]}]}]},{"text":[{"text":"Idle time variance:","bold":true},{"text":" the cost of hours paid for but not worked, valued at standard rate. Always adverse."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Idle time variance = (AH paid − AH worked) × SR"}]}]}]},{"text":[{"text":"Labour efficiency variance:","bold":true},{"text":" caused by working more or fewer hours than standard for the actual output."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Labour efficiency variance = (SH − AH worked) × SR"}]}]}]},{"text":[{"text":"Check:","bold":true},{"text":" Labour cost variance = Rate + Idle time + Efficiency."}]},{"text":[{"text":"SH = Actual output × Standard hours per unit. If there is no idle time, AH worked = AH paid."}]}]},{"type":"paragraph","text":[{"text":"Causes","bold":true}]},{"type":"table","header":[[{"text":"Variance"}],[{"text":"Causes"}]],"rows":[[[{"text":"Rate"}],[{"text":"Wage increase or new union agreement, overtime or shift premium, using a higher (or lower) grade of worker than planned, bonus payments"}]],[[{"text":"Idle time"}],[{"text":"Machine breakdown, shortage of materials, power failure, strikes, illness or injury to workers, waiting for instructions or work, poor production planning"}]],[[{"text":"Efficiency"}],[{"text":"Skill and experience of workers, motivation and morale, quality of materials, condition of machines, quality of supervision, learning effect, wrong grade of labour"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1.","bold":true},{"text":" The Aba factory (standard: 3 hours at ₦800) made 1,000 pairs. Workers were paid for 3,100 hours at ₦850 an hour. A machine breakdown caused 150 idle hours."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"SH = 1,000 × 3 = 3,000 hours. Standard cost of actual output = 3,000 × ₦800 = ₦2,400,000."}]},{"text":[{"text":"Actual cost = 3,100 × ₦850 = ₦2,635,000. AH worked = 3,100 − 150 = 2,950."}]},{"text":[{"text":"Rate variance = (₦800 − ₦850) × 3,100 = "},{"text":"₦155,000 A","bold":true},{"text":"."}]},{"text":[{"text":"Idle time variance = 150 × ₦800 = "},{"text":"₦120,000 A","bold":true},{"text":"."}]},{"text":[{"text":"Efficiency variance = (3,000 − 2,950) × ₦800 = "},{"text":"₦40,000 F","bold":true},{"text":"."}]},{"text":[{"text":"Cost variance = ₦2,400,000 − ₦2,635,000 = "},{"text":"₦235,000 A","bold":true},{"text":". Check: ₦155,000 A + ₦120,000 A − ₦40,000 F = ₦235,000 A."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2: finding standard hours from the efficiency variance.","bold":true},{"text":" 17,500 direct labour hours were worked at a standard rate of ₦6.50 an hour. The efficiency variance was ₦7,800 favourable."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Hours saved = ₦7,800 ÷ ₦6.50 = 1,200 hours."}]},{"text":[{"text":"Favourable means fewer hours were worked than allowed, so SH = 17,500 + 1,200 = "},{"text":"18,700 standard hours","bold":true},{"text":"."}]},{"text":[{"text":"Check: (18,700 − 17,500) × ₦6.50 = ₦7,800 F. (If the variance had been adverse, SH = 17,500 − 1,200 = 16,300.)"}]}]},{"type":"paragraph","text":[{"text":"Worked example 3: finding the actual rate.","bold":true},{"text":" 6,200 hours were paid; standard rate ₦500; rate variance ₦31,000 A. Excess per hour = ₦31,000 ÷ 6,200 = ₦5, so AR = ₦500 + ₦5 = "},{"text":"₦505","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps:","bold":true},{"text":" rate variance uses hours "},{"text":"paid","bold":true},{"text":"; efficiency variance uses hours "},{"text":"worked","bold":true},{"text":"; idle time uses the "},{"text":"standard","bold":true},{"text":" rate. An increase in the wage rate causes a "},{"text":"rate","bold":true},{"text":" variance, not an idle time variance. Illness or injury to workers, machine breakdown and shortage of materials all cause idle time."}]}]}]},{"number":"10.6","title":"Investigating variances and reconciling standard and actual cost","mustKnow":[{"type":"paragraph","text":[{"text":"When to investigate a variance (factors)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Size (materiality):","bold":true},{"text":" investigate if the variance exceeds a set amount or percentage of standard (for example over ₦50,000 or over 5%)."$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 45, $study_guide$}]},{"text":[{"text":"Controllability:","bold":true},{"text":" investigate variances management can act on; uncontrollable ones (a national price rise) may only need the standard revised."}]},{"text":[{"text":"Cost versus benefit:","bold":true},{"text":" investigate only if the expected saving from correcting the cause exceeds the cost of investigating."}]},{"text":[{"text":"Trend:","bold":true},{"text":" a small variance that grows month after month needs investigating even if each one is small."}]},{"text":[{"text":"Type of standard:","bold":true},{"text":" under an ideal standard, adverse variances are expected and less alarming."}]},{"text":[{"text":"Reliability of measurement:","bold":true},{"text":" the variance may come from recording errors or a wrong standard, not real inefficiency."}]},{"text":[{"text":"Interdependence:","bold":true},{"text":" a variance may be caused by another department."}]},{"text":[{"text":"Favourable variances too:","bold":true},{"text":" a large favourable variance may signal a loose standard or a quality cut."}]}]},{"type":"paragraph","text":[{"text":"Possible causes found on investigation:","bold":true},{"text":" measurement or recording error; out-of-date or wrong standard; random (chance) fluctuation; genuine operational inefficiency or efficiency."}]},{"type":"paragraph","text":[{"text":"Reconciliation of standard cost with actual cost","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Actual cost = Standard cost of actual output + Adverse variances − Favourable variances."}]},{"text":[{"text":"The reconciliation (operating) statement starts with the standard cost of actual output, lists each variance (F or A) and ends at actual cost."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example: reconciliation of prime cost for 1,000 pairs (Aba factory).","bold":true}]},{"type":"table","header":[[],[{"text":"F (₦)"}],[{"text":"A (₦)"}],[{"text":"₦"}]],"rows":[[[{"text":"Standard prime cost of actual output (1,000 × ₦5,400)"}],[],[],[{"text":"5,400,000"}]],[[{"text":"Material price variance"}],[{"text":"105,000"}],[],[]],[[{"text":"Material usage variance"}],[],[{"text":"150,000"}],[]],[[{"text":"Labour rate variance"}],[],[{"text":"155,000"}],[]],[[{"text":"Labour idle time variance"}],[],[{"text":"120,000"}],[]],[[{"text":"Labour efficiency variance"}],[{"text":"40,000"}],[],[]],[[{"text":"Totals","bold":true}],[{"text":"145,000"}],[{"text":"425,000"}],[]],[[{"text":"Net adverse variance (₦425,000 − ₦145,000)"}],[],[],[{"text":"280,000"}]],[[{"text":"Actual prime cost","bold":true}],[],[],[{"text":"5,680,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Check: actual materials ₦3,045,000 + actual labour ₦2,635,000 = ₦5,680,000. The figures agree, so the variances are correct. Adverse variances are added because they make actual cost higher than standard; favourable ones are deducted."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Standard cost = predetermined unit cost; standard costing = control through comparing standards with actual and analysing variances."}]},{"text":[{"text":"Variance = standard (or budget) minus actual; favourable if actual cost is lower, adverse if higher."}]},{"text":[{"text":"Four standards: ideal (perfect), attainable (efficient with allowances, motivates best), basic (long-run, unaltered), current (present conditions)."}]},{"text":[{"text":"Standard cost card: quantity × price for each element per unit."}]},{"text":[{"text":"Budgeted cost = standard cost per unit × budgeted output; variances compare actual with the standard cost of "},{"text":"actual","bold":true},{"text":" output."}]},{"text":[{"text":"Material: price = (SP − AP) × AQ; usage = (SQ − AQ) × SP; cost = SQ × SP − AQ × AP."}]},{"text":[{"text":"Labour: rate = (SR − AR) × hours paid; idle time = idle hours × SR (always adverse); efficiency = (SH − hours worked) × SR."}]},{"text":[{"text":"Investigate by size, controllability, cost versus benefit, trend and reliability."}]},{"text":[{"text":"Actual cost = standard cost of actual output + adverse − favourable variances."}]}]}],"theory":{"itemId":"bb278c77-dbf0-5de9-a605-28fc17d76bed","question":[{"type":"paragraph","text":[{"text":"A Lagos paint factory's standard for one tin is 5 kg of material at ₦120 per kg and 2 labour hours at ₦600 an hour. In March it made 800 tins, buying and using 4,200 kg of material for ₦483,000. Labour was paid for 1,700 hours costing ₦1,054,000, of which 60 hours were idle because of a power failure. Calculate the material and labour variances and reconcile standard prime cost with actual prime cost."}]}]}}},{"kind":"note","itemId":"814d72e8-c07c-5aeb-acec-3940ef08e0f9","sourceKey":"guide-topic:11","position":11,"payload":{"title":"Contemporary Issues in Cost Accounting","body":"Activity-based costing and cost drivers; just-in-time and backflush costing; target costing and life-cycle costing; total quality management, the four costs of quality and the characteristics of quality cost information; throughput accounting; how technology changes costing.","noteType":"guide_topic","number":11,"mustKnow":[{"text":"Activity-based costing and cost drivers; just-in-time and backflush costing; target costing and life-cycle costing; total quality management, the four costs of quality and the characteristics of quality cost information; throughput accounting; how technology changes costing."}],"lessons":[{"number":"11.1","title":"Activity-based costing (ABC)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Activity-based costing:","bold":true},{"text":" a method that charges overheads to products according to the "},{"text":"activities","bold":true},{"text":" each product uses, instead of one blanket rate based on labour or machine hours."}]},{"text":[{"text":"Activity:","bold":true},{"text":" a task that consumes resources, e.g. machine set-ups, ordering materials, inspection, despatch."}]},{"text":[{$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 46, $study_guide$"text":"Cost pool:","bold":true},{"text":" the total overhead collected for one activity."}]},{"text":[{"text":"Cost driver:","bold":true},{"text":" the factor that causes the cost of an activity to rise or fall, e.g. number of set-ups, number of purchase orders, number of inspections."}]}]},{"type":"paragraph","text":[{"text":"5 steps in ABC:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify the main activities."}]},{"text":[{"text":"Collect the overhead of each activity into a cost pool."}]},{"text":[{"text":"Identify the cost driver for each activity."}]},{"text":[{"text":"Calculate a cost driver rate: "},{"text":"Cost driver rate = Cost pool ÷ Total number of cost drivers","bold":true},{"text":"."}]},{"text":[{"text":"Charge each product: "},{"text":"Overhead charged = Cost driver rate × Drivers used by the product","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Traditional absorption"}],[{"text":"ABC"}]],"rows":[[[{"text":"One or a few rates (labour or machine hours)"}],[{"text":"One rate per activity"}]],[[{"text":"Assumes overhead varies with volume"}],[{"text":"Recognises costs driven by complexity and batches"}]],[[{"text":"Low-volume products often under-costed"}],[{"text":"More accurate product costs"}]],[[{"text":"Simple and cheap"}],[{"text":"Costly and time-consuming to set up"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example.","italic":true},{"text":" An Ikeja factory makes Standard (10,000 units, 8,000 machine hours) and Deluxe (2,000 units, 2,000 machine hours). Overhead is ₦1,000,000: set-ups ₦600,000 (Standard 10 set-ups, Deluxe 20) and order handling ₦400,000 (Standard 30 orders, Deluxe 50)."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Traditional:","bold":true},{"text":" rate = ₦1,000,000 ÷ 10,000 machine hours = ₦100 an hour. Standard: 8,000 × ₦100 = ₦800,000, so "},{"text":"₦80 a unit","bold":true},{"text":". Deluxe: 2,000 × ₦100 = ₦200,000, so "},{"text":"₦100 a unit","bold":true},{"text":"."}]},{"text":[{"text":"ABC rates:","bold":true},{"text":" set-ups ₦600,000 ÷ 30 = ₦20,000 per set-up; orders ₦400,000 ÷ 80 = ₦5,000 per order."}]},{"text":[{"text":"Standard: (10 × ₦20,000) + (30 × ₦5,000) = ₦350,000 ÷ 10,000 = "},{"text":"₦35 a unit","bold":true},{"text":"."}]},{"text":[{"text":"Deluxe: (20 × ₦20,000) + (50 × ₦5,000) = ₦650,000 ÷ 2,000 = "},{"text":"₦325 a unit","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"The small-batch Deluxe uses far more set-ups and orders per unit, so ABC charges it more. Under the traditional rate the high-volume Standard was subsidising Deluxe."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages:","bold":true},{"text":" more accurate costs, better pricing and product-mix decisions, shows what drives overhead so it can be managed."}]},{"text":[{"text":"Limitations:","bold":true},{"text":" expensive to run, choosing drivers involves judgement, some costs (e.g. the chief executive's salary) have no clear driver."}]},{"text":[{"text":"Trap: the cost driver is the "},{"text":"cause","bold":true},{"text":" of the cost (number of set-ups), not the cost itself (set-up cost)."}]}]}]},{"number":"11.2","title":"Just-in-time (JIT) and backflush costing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Just-in-time:","bold":true},{"text":" a system in which materials are bought and goods are produced only when needed, so that stock is kept close to zero. It is a "},{"text":"pull","bold":true},{"text":" system: customer demand pulls production through the factory."}]},{"text":[{"text":"JIT purchasing:","bold":true},{"text":" small, frequent deliveries arrive just as they are needed."}]},{"text":[{"text":"JIT production:","bold":true},{"text":" each stage produces only what the next stage calls for."}]}]},{"type":"paragraph","text":[{"text":"Features of JIT:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Very low or zero stocks."}]},{"text":[{"text":"Close, long-term relationships with a few reliable suppliers."}]},{"text":[{"text":"Small, frequent deliveries."}]},{"text":[{"text":"High quality (zero defects), since there is no buffer stock to cover faults."}]},{"text":[{"text":"Reliable machines (preventive maintenance) and short set-up times."}]},{"text":[{"text":"A flexible, multi-skilled workforce, often in production cells."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Benefits:","bold":true},{"text":" lower storage and holding costs, less waste and obsolete stock, faster response to customers, better quality."}]},{"text":[{"text":"Problems:","bold":true},{"text":" a late supplier stops production; little protection against sudden demand rises; depends on reliable transport."}]},{"text":[{"text":"Backflush costing:","bold":true},{"text":" a simplified method, used with JIT, that records costs mainly at the "},{"text":"end","bold":true},{"text":" of production (on completion or on sale) and works "},{"text":"backwards","bold":true},{"text":", using standard costs, to charge materials and conversion costs to output."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Backflush suits JIT because there is little work in progress to track; detailed entries for every stage add cost without adding much information."}]},{"text":[{"text":"Example:","italic":true},{"text":" an Aba shoe factory using JIT completes 1,000 pairs. Standard material cost is ₦800 a pair. Instead of recording each issue to work in progress, it records one entry at completion: 1,000 × ₦800 = "},{"text":"₦800,000","bold":true},{"text":" of material charged to finished goods."}]},{"text":[{"text":"In Nigeria, port delays, poor roads and Lagos traffic make strict JIT risky; firms often keep a small safety stock."}]},{"text":[{"text":"Trap: JIT is a "},{"text":"pull","bold":true},{"text":" system, not push. Traditional factories \"p$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 47, $study_guide$ush\" goods into stock regardless of demand."}]}]}]},{"number":"11.3","title":"Target costing and life-cycle costing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Target costing:","bold":true},{"text":" start from the price customers will pay, deduct the profit the firm requires, and the remainder is the cost the product must be made for."}]},{"text":[{"text":"Target cost = Target (market) selling price − Required profit","bold":true}]},{"text":[{"text":"Cost gap = Estimated cost − Target cost.","bold":true},{"text":" The gap is closed by redesign, value engineering, cheaper materials or better methods before production begins."}]},{"text":[{"text":"Life-cycle costing:","bold":true},{"text":" tracking and accumulating "},{"text":"all","bold":true},{"text":" the costs of a product over its whole life, from research and design through production and marketing to withdrawal."}]}]},{"type":"paragraph","text":[{"text":"Stages of the product life cycle:","bold":true},{"text":" introduction, growth, maturity, decline."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Target costing example.","italic":true},{"text":" A Lagos firm plans a blender that will sell for ₦5,000. It wants a profit of 20% of the selling price. Estimated cost is ₦4,600."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Required profit = 20% × ₦5,000 = ₦1,000."}]},{"text":[{"text":"Target cost = ₦5,000 − ₦1,000 = "},{"text":"₦4,000","bold":true},{"text":"."}]},{"text":[{"text":"Cost gap = ₦4,600 − ₦4,000 = "},{"text":"₦600","bold":true},{"text":" a unit to be removed."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: target costing is "},{"text":"price-led","bold":true},{"text":" (price − profit = cost); traditional cost-plus pricing is cost-led (cost + mark-up = price)."}]}]},{"type":"paragraph","text":[{"text":"Life-cycle costing example.","italic":true},{"text":" A phone-charger project expects 5,000 units over its life. Research ₦2,000,000; design ₦1,000,000; production ₦3,000 a unit; marketing ₦1,500,000; withdrawal (decommissioning) ₦500,000."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production = 5,000 × ₦3,000 = ₦15,000,000."}]},{"text":[{"text":"Life-cycle cost = ₦2,000,000 + ₦1,000,000 + ₦15,000,000 + ₦1,500,000 + ₦500,000 = "},{"text":"₦20,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Life-cycle cost per unit = ₦20,000,000 ÷ 5,000 = "},{"text":"₦4,000","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Production cost alone (₦3,000) would understate cost by ₦1,000 a unit. Most life-cycle costs are committed at the design stage, so that is where control matters most."}]}]}]},{"number":"11.4","title":"Quality, throughput accounting and technology","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total quality management (TQM):","bold":true},{"text":" an approach in which everyone in the organisation works continuously to improve quality and meet customer needs, aiming at "},{"text":"zero defects","bold":true},{"text":" and "},{"text":"getting it right first time","bold":true},{"text":"."}]},{"text":[{"text":"Cost of quality:","bold":true},{"text":" the total cost of preventing, finding and correcting defects."}]}]},{"type":"paragraph","text":[{"text":"4 costs of quality:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Prevention costs:","bold":true},{"text":" stop defects happening, e.g. quality training, supplier vetting, preventive maintenance."}]},{"text":[{"text":"Appraisal costs:","bold":true},{"text":" check quality, e.g. inspection, testing."}]},{"text":[{"text":"Internal failure costs:","bold":true},{"text":" defects found "},{"text":"before","bold":true},{"text":" the goods reach the customer, e.g. scrap, rework."}]},{"text":[{"text":"External failure costs:","bold":true},{"text":" defects found "},{"text":"after","bold":true},{"text":" delivery, e.g. warranty repairs, returns, lost goodwill."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost of conformance = Prevention + Appraisal. Cost of non-conformance = Internal failure + External failure.","bold":true}]},{"text":[{"text":"Characteristics of quality cost information:","bold":true},{"text":" objective, timely, relevant, accurate (reliable) and understandable. It is "},{"text":"not","bold":true},{"text":" subjective."}]},{"text":[{"text":"Throughput accounting:","bold":true},{"text":" treats only direct material as variable; all other factory costs are fixed. It aims to maximise throughput through the "},{"text":"bottleneck","bold":true},{"text":" (the scarcest resource)."}]},{"text":[{"text":"Throughput = Sales − Direct material cost","bold":true}]},{"text":[{"text":"Return per factory hour = Throughput per unit ÷ Bottleneck hours per unit","bold":true}]},{"text":[{"text":"Cost per factory hour = Total factory cost (excluding materials) ÷ Total bottleneck hours available","bold":true}]},{"text":[{"text":"Throughput accounting ratio (TAR) = Return per factory hour ÷ Cost per factory hour.","bold":true},{"text":" A ratio above 1 means the product is worth making."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Cost of quality example.","italic":true},{"text":" A Kano flour mill spends: training ₦300,000; inspection ₦200,000; scrap and rework ₦250,000; warranty refunds ₦400,000. Prevention ₦300,000 + appraisal ₦200,000 = conformance "},{"text":"₦500,000","bold":true},{"text":"; internal ₦250,000 + external ₦400,000 = non-conformance "},{"text":"₦650,000","bold":true},{"text":"; total "},{"text":"₦1,150,000","bold":true},{"text":". Spending more on prevention usually cuts failure costs."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: scrap found in the factory is "},{"text":"internal","bold":true},{"text":" failure; a customer return is "},{"text":"external","bold":true},{"text":". Inspection is "},{"text":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 48, $study_guide$appraisal","bold":true},{"text":", not prevention."}]}]},{"type":"paragraph","text":[{"text":"Throughput example.","italic":true},{"text":" A product sells for ₦2,500 with direct material of ₦1,000 and needs 0.5 bottleneck hours. Factory costs are ₦4,800,000 for 2,000 bottleneck hours."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Throughput per unit = ₦2,500 − ₦1,000 = ₦1,500."}]},{"text":[{"text":"Return per factory hour = ₦1,500 ÷ 0.5 = ₦3,000."}]},{"text":[{"text":"Cost per factory hour = ₦4,800,000 ÷ 2,000 = ₦2,400."}]},{"text":[{"text":"TAR = ₦3,000 ÷ ₦2,400 = "},{"text":"1.25","bold":true},{"text":", above 1, so the product is worth making."}]}]},{"type":"paragraph","text":[{"text":"Effect of technology:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advanced manufacturing technology (computer-aided design and manufacture, robots, flexible manufacturing systems) and enterprise resource planning (ERP) software are now common."}]},{"text":[{"text":"Direct labour falls and overheads rise, so labour-hour absorption becomes less meaningful and ABC more useful."}]},{"text":[{"text":"Data are captured in real time, so cost reports are faster and more detailed; automation also supports JIT and backflush."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"ABC: activities, cost pools, cost drivers; rate = cost pool ÷ number of drivers."}]},{"text":[{"text":"ABC gives more accurate costs and stops high-volume products subsidising low-volume ones."}]},{"text":[{"text":"JIT: pull system, near-zero stock, reliable suppliers, zero defects."}]},{"text":[{"text":"Backflush costing records costs at the end of production, working backwards with standard costs."}]},{"text":[{"text":"Target cost = selling price − required profit; cost gap = estimated cost − target cost."}]},{"text":[{"text":"Life-cycle costing gathers all costs over a product's life; most are committed at design."}]},{"text":[{"text":"4 costs of quality: prevention, appraisal (conformance); internal, external failure (non-conformance)."}]},{"text":[{"text":"Quality cost information is objective, timely and relevant, never subjective."}]},{"text":[{"text":"Throughput = sales − direct material; TAR above 1 is good."}]},{"text":[{"text":"Technology lowers direct labour, raises overheads and favours ABC."}]}]}],"theory":{"itemId":"3b0500bb-11c7-52a2-b985-14b5751e9a2e","question":[{"type":"paragraph","text":[{"text":"A Lagos bottled-water company spends: staff quality training ₦180,000; testing samples ₦120,000; re-bottling rejected bottles in the factory ₦90,000; replacing bottles returned by customers ₦210,000; vetting new suppliers ₦60,000. Classify these costs and calculate the costs of conformance, non-conformance and total quality."}]}]}}}],"theory":[{"kind":"theory_question","itemId":"249f7ad9-c015-541d-b687-06b2f5ac8251","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"An Aba shoe factory produced 2,500 pairs of shoes in June. It used 1,250 m² of leather at ₦4,800 per m² and 2,500 soles at ₦900 each; labour cost ₦3,000,000 and factory overheads ₦1,750,000. (a) State a suitable cost unit and one cost centre. (b) Calculate the cost per unit."},"answer":{"kind":"model_answer","itemId":"d0c53018-0ab9-5751-98e0-07fdc71d786d","sourceKey":"guide-answer:1","payload":{"body":"(a) Cost unit: one pair of shoes. A cost centre: the cutting section (or the stitching section, or a stitching machine).\n(b)\nItem | Working | ₦\nLeather | 1,250 × 4,800 | 6,000,000\nSoles | 2,500 × 900 | 2,250,000\nLabour | given | 3,000,000\nFactory overheads | given | 1,750,000\nTotal cost |  | 13,000,000\nCost per pair = ₦13,000,000 ÷ 2,500 = ₦5,200."}}},{"kind":"theory_question","itemId":"5fdb5b63-9f86-5c5e-ad3e-5577d9bdfd25","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"Ikorodu Furniture Ltd gives you: direct materials consumed ₦250,000; direct labour ₦150,000; direct expenses ₦40,000; factory overhead ₦110,000; administration overhead ₦60,000. Calculate (a) prime cost, (b) conversion cost, (c) factory cost and (d) cost of production."},"answer":{"kind":"model_answer","itemId":"7400d154-57eb-5ec9-b43c-40030de2d53e","sourceKey":"guide-answer:2","payload":{"body":"• (a) Prime cost = ₦250,000 + ₦150,000 + ₦40,000 = ₦440,000.\n• (b) Conversion cost = ₦150,000 + ₦40,000 + ₦110,000 = ₦300,000.\n• (c) Factory cost = ₦440,000 + ₦110,000 = ₦550,000 (check: materials ₦250,000 + conversion ₦300,000 = ₦550,000).\n• (d) Cost of production = ₦550,000 + ₦60,000 = ₦610,000."}}},{"kind":"theory_question","itemId":"29bc3936-4966-5f30-8f11-373037920532","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"A Kano flour mill records electricity cost against machine hours: January 1,200 hours ₦96,000; February 1,500 hours ₦112,500; March 1,700 hours ₦129,000; April 1,800 hours ₦126,000. Using the high-low method, find the cost function and estimate the electricity cost for 1,600 machine hours."},"answer":{"kind":"model_answer","itemId":"f8b898a0-dfef-5001-b9bf-0fade03a2c47","sourceKey":"guide-answer:3","payload":{"body":"• Highest activity = April, 1,800 hours (₦126,000). March has the highest cost but not the highest activity, so ignore it. Lowest activity = January, 1,200 hours (₦96,000).\n• b = (126,000 − 96,000) ÷ (1,800 − 1,200) = 30,000 ÷ 600 = ₦50 per machine hour\n• a = 126,000 − (50 × 1,800) = 126,000 − 90,000 = ₦36,000\n• Cost function: Y = ₦36,000 + ₦50x\n• At 1,600 hours: Y = 36,000 + (50 × 1,600) = 36,000 + 80,000 = ₦116,000"}}},{"kind":"theory_question","itemId":"91479601-eefd-5aaa-a523-837cc3e8ad66","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"A Lagos printing firm uses 8,000 reams of paper a year, bought at ₦500 a ream. Each order costs ₦250 and carrying cost is 20% of the purchase price a year. Calculate (a) the EOQ, (b) the number of orders a year and (c) the total annual ordering and carrying cost at the EOQ."},"answer":{"kind":"mo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 49, $study_guide$del_answer","itemId":"257c8b2c-6618-518f-8788-79acce67c89e","sourceKey":"guide-answer:4","payload":{"body":"1. Cc = 20% × ₦500 = ₦100 per ream per year.\n2. (a) EOQ = √(2 × 8,000 × 250 ÷ 100) = √40,000 = 200 reams.\n3. (b) Orders = 8,000 ÷ 200 = 40 orders.\n4. (c) Ordering cost = 40 × ₦250 = ₦10,000; carrying cost = 200 ÷ 2 × ₦100 = ₦10,000; total = ₦20,000."}}},{"kind":"theory_question","itemId":"74f14e35-ba13-50b5-a516-cc4edc21cf23","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Ada is allowed 12 hours for a job at ₦400 per hour and finishes in 9 hours. Calculate her total wages and effective hourly rate under (a) the Halsey (50%) plan and (b) the Rowan plan."},"answer":{"kind":"model_answer","itemId":"b05f94cf-62f5-5534-861c-8b925bc7bb20","sourceKey":"guide-answer:5","payload":{"body":"Time saved = 12 − 9 = 3 hours. Basic = 9 × ₦400 = ₦3,600.\n(a) Halsey = ₦3,600 + 50% × 3 × ₦400 = ₦3,600 + ₦600 = ₦4,200; effective rate = ₦4,200 ÷ 9 = ₦466.67 (rounded).\n(b) Rowan = ₦3,600 + (3 ÷ 12) × ₦3,600 = ₦3,600 + ₦900 = ₦4,500; effective rate = ₦4,500 ÷ 9 = ₦500.\nRowan pays more because time saved (25%) is below 50% of time allowed."}}},{"kind":"theory_question","itemId":"9a8ac7c5-7c69-57dc-a8d7-e48a41c4e8b7","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"An Ibadan furniture maker budgets production overhead of ₦480,000 and 24,000 machine hours for the year. Actual results were 25,500 machine hours and overhead of ₦498,000. Calculate (a) the overhead absorption rate, (b) the overhead absorbed and (c) the under- or over-absorption, and say how a small difference is treated."},"answer":{"kind":"model_answer","itemId":"175e99c0-572c-51b0-ae68-ad1b6b6a58e6","sourceKey":"guide-answer:6","payload":{"body":"1. (a) OAR = ₦480,000 ÷ 24,000 = ₦20 per machine hour.\n2. (b) Absorbed = 25,500 × ₦20 = ₦510,000.\n3. (c) ₦510,000 − ₦498,000 = ₦12,000 over-absorbed, because absorbed overhead exceeds actual overhead.\n4. Being small, it is written off (credited) to the costing profit and loss account, increasing profit by ₦12,000."}}},{"kind":"theory_question","itemId":"ef506dd6-c5ac-592d-9802-fed3e4a82792","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"A Lekki tailoring workshop is quoting for Job 92: materials ₦45,000; 120 labour hours at ₦500 an hour; production overhead ₦300 per labour hour; administration overhead 10% of production cost. The workshop wants a profit of 20% of the selling price. Calculate the quoted price."},"answer":{"kind":"model_answer","itemId":"0155617d-7c4c-5b69-a0af-54f0b08895d6","sourceKey":"guide-answer:7","payload":{"body":"1. Direct labour = 120 × ₦500 = ₦60,000; prime cost = 45,000 + 60,000 = ₦105,000.\n2. Production overhead = 120 × ₦300 = ₦36,000; production cost = ₦141,000.\n3. Administration = 10% × 141,000 = ₦14,100; total cost = ₦155,100.\n4. Profit is a margin on sales: price = 155,100 ÷ 0.80 = ₦193,875 (profit ₦38,775)."}}},{"kind":"theory_question","itemId":"6f27d246-6c14-5b9f-a8b6-1b5f761d8f33","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"A Lagos bakery makes a cake that sells for ₦200. Variable production cost is ₦120 a cake. Fixed production overhead is ₦400,000 a month, absorbed on a normal output of 10,000 cakes. Fixed administration cost is ₦200,000 a month. In the month, 10,000 cakes were produced and 8,000 sold, with no opening stock. Calculate (a) closing stock under each technique, (b) profit under each technique and (c) reconcile the two profits."},"answer":{"kind":"model_answer","itemId":"14a8be9e-7117-555d-9568-a9125b9aa5b7","sourceKey":"guide-answer:8","payload":{"body":"1. OAR = ₦400,000 ÷ 10,000 = ₦40; full production cost = ₦120 + ₦40 = ₦160. Closing stock = 10,000 − 8,000 = 2,000 cakes.\n2. (a) Marginal: 2,000 × ₦120 = ₦240,000. Absorption: 2,000 × ₦160 = ₦320,000.\n3. (b) Marginal: contribution = 8,000 × (₦200 − ₦120) = ₦640,000; profit = ₦640,000 − ₦400,000 − ₦200,000 = ₦40,000.\n4. Absorption: sales 8,000 × ₦200 = ₦1,600,000; cost of sales 8,000 × ₦160 = ₦1,280,000 (absorbed 10,000 × ₦40 = ₦400,000, so no under/over-absorption); gross profit ₦320,000; net profit = ₦320,000 − ₦200,000 = ₦120,000.\n5. (c) Stock rose by 2,000 cakes: 2,000 × ₦40 = ₦80,000. Marginal profit ₦40,000 + ₦80,000 = absorption profit ₦120,000."}}},{"kind":"theory_question","itemId":"58f639c7-516b-5240-9185-7ba2cff7d48c","sourceKey":"guide-theory:9","position":9,"payload":{"prompt":"An Ilorin water factory sells a pack of bottled water for ₦1,500. Variable cost is ₦900 a pack and fixed costs are ₦3,600,000 a month. Budgeted sales are 9,000 packs a month. The tax rate is 30%. Calculate (a) the C/S ratio, (b) the break-even point in packs and naira, (c) the margin of safety in packs, naira and percentage, and (d) the packs needed to earn a profit after tax of ₦1,680,000."},"answer":{"kind":"model_answer","itemId":"d0f931be-fbb9-54f3-8e3f-612d1ad15206","sourceKey":"guide-answer:9","payload":{"body":"1. (a) Contribution = ₦1,500 − ₦900 = ₦600; C/S ratio = 600 ÷ 1,500 = 40%.\n2. (b) BEP = ₦3,600,000 ÷ ₦600 = 6,000 packs; in naira, 6,000 × ₦1,500 = ₦9,000,000 (or ₦3,600,000 ÷ 0.40).\n3. (c) MOS = 9,000 − 6,000 = 3,000 packs = 3,000 × ₦1,500 = ₦4,500,000; MOS % = 3,000 ÷ 9,000 = 33.3% (to 1 decimal place).\n4. (d) Profit before tax = ₦1,680,000 ÷ (1 − 0.30) = ₦2,400,000. Packs = (₦3,600,000 + ₦2,400,000) ÷ ₦600 = 10,000 packs. (The budget of 9,000 packs earns only ₦1,800,000 before tax.)"}}},{"kind":"theory_question","itemId":"bb278c77-dbf0-5de9-a605-28fc17d76bed","sourceKey":"guide-theory:10","position":10,"payload":{"prompt":"A Lagos paint factory's standard for one tin is 5 kg of material at ₦120 per kg and 2 labour hours at ₦600 an hour. In March it made 800 tins, buying and using 4,200 kg of material for ₦483,000. Labour was paid for 1,700 hours costing ₦1,054,000, of which 60 hours were idle because of a power failure. Calculate the material and labour variances and reconcile standard prime cost with actual prime co$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc121', 50, $study_guide$st."},"answer":{"kind":"model_answer","itemId":"c4f5da6e-e036-5e9b-be84-0f0b35ad66df","sourceKey":"guide-answer:10","payload":{"body":"1. AP = ₦483,000 ÷ 4,200 = ₦115. SQ = 800 × 5 = 4,000 kg.\n2. Material price = (₦120 − ₦115) × 4,200 = ₦21,000 F. Usage = (4,000 − 4,200) × ₦120 = ₦24,000 A. Cost = 4,000 × ₦120 − ₦483,000 = ₦480,000 − ₦483,000 = ₦3,000 A.\n3. AR = ₦1,054,000 ÷ 1,700 = ₦620. SH = 800 × 2 = 1,600. Hours worked = 1,700 − 60 = 1,640.\n4. Rate = (₦600 − ₦620) × 1,700 = ₦34,000 A. Idle time = 60 × ₦600 = ₦36,000 A. Efficiency = (1,600 − 1,640) × ₦600 = ₦24,000 A. Cost = 1,600 × ₦600 − ₦1,054,000 = ₦960,000 − ₦1,054,000 = ₦94,000 A.\n5. Reconciliation: standard prime cost 800 × (₦600 + ₦1,200) = ₦1,440,000; favourable ₦21,000; adverse ₦24,000 + ₦34,000 + ₦36,000 + ₦24,000 = ₦118,000; net adverse ₦97,000; actual = ₦1,440,000 + ₦97,000 = ₦1,537,000 (= ₦483,000 + ₦1,054,000)."}}},{"kind":"theory_question","itemId":"3b0500bb-11c7-52a2-b985-14b5751e9a2e","sourceKey":"guide-theory:11","position":11,"payload":{"prompt":"A Lagos bottled-water company spends: staff quality training ₦180,000; testing samples ₦120,000; re-bottling rejected bottles in the factory ₦90,000; replacing bottles returned by customers ₦210,000; vetting new suppliers ₦60,000. Classify these costs and calculate the costs of conformance, non-conformance and total quality."},"answer":{"kind":"model_answer","itemId":"38930974-7d7b-54d4-868c-e15511022b17","sourceKey":"guide-answer:11","payload":{"body":"1. Prevention: training ₦180,000 + supplier vetting ₦60,000 = ₦240,000.\n2. Appraisal: testing ₦120,000.\n3. Internal failure: re-bottling ₦90,000.\n4. External failure: customer returns ₦210,000.\n5. Conformance = ₦240,000 + ₦120,000 = ₦360,000. Non-conformance = ₦90,000 + ₦210,000 = ₦300,000. Total cost of quality = ₦660,000."}}}]}$study_guide$);
